import { Book } from "@/lib/types";

export const matthew: Book = {
  id: "matthew",
  name: "Matthäus",
  shortName: "Mt",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "*Buch des Ursprungs* Jesu Christi, des Sohnes Davids*, des Sohnes Abrahams*.", heading: "Der Stammbaum Jesu", footnotes: ["℘ 1Chr 1,34; 2,1-15; 3,5.10-19; Lk 3,23-38", "o. der Abkunft; o. des Stammbaums\n℘ 1Mo 5,1", "℘ Kap. 22,42; 2Sam 7,12; Joh 7,42", "℘ 1Mo 11,27; 17,5; Gal 3,16 ⇨Esyn: Synopse Nr. 1"] },
      { number: 2, text: "Abraham zeugte Isaak*, Isaak aber zeugte Jakob*, Jakob aber zeugte Juda und seine Brüder*,", footnotes: ["℘ 1Mo 21,3", "℘ 1Mo 25,26", "℘ 1Mo 29,35; 35,22-26; Apg 7,8 ⇨Esyn: Synopse Nr. 6"] },
      { number: 3, text: "Juda aber zeugte Perez und Serach von der Tamar*, Perez aber zeugte Hezron, Hezron aber zeugte Ram,", footnotes: ["℘ 1Mo 38,29.30; Rt 4,12"] },
      { number: 4, text: "Ram aber zeugte Amminadab, Amminadab aber zeugte Nachschon, Nachschon aber zeugte Salmon," },
      { number: 5, text: "Salmon aber zeugte Boas* von der Rahab*, Boas aber zeugte Obed von der Rut*, Obed aber zeugte Isai*,", footnotes: ["℘ Rt 2,1", "℘ Jos 2,1; Hebr 11,31; Jak 2,25", "℘ Rt 4,13-17", "℘ Jes 11,1"] },
      { number: 6, text: "Isai aber zeugte David, den König*, David aber zeugte Salomo von der <Frau> des Uria*,", footnotes: ["℘ Rt 4,17-22; 1Sam 16,12.13; 2Sam 2,4; 5,3", "℘ 2Sam 11,3; 12,24"] },
      { number: 7, text: "Salomo aber zeugte Rehabeam*, Rehabeam aber zeugte Abija*, Abija aber zeugte Asa*,", footnotes: ["℘ 1Kö 11,43", "℘ 1Kö 14,31", "mit einigen alten Handschr.: Asaf\n℘ 1Kö 15,8"] },
      { number: 8, text: "Asa* aber zeugte Joschafat*, Joschafat aber zeugte Joram*, Joram aber zeugte Usija*,", footnotes: ["mit einigen alten Handschr.: Asaf", "℘ 1Kö 22,41", "℘ 2Kö 8,16", "℘ 2Kö 14,21"] },
      { number: 9, text: "Usija aber zeugte Jotam*, Jotam aber zeugte Ahas*, Ahas aber zeugte Hiskia*,", footnotes: ["℘ 2Kö 15,32", "℘ 2Kö 16,1", "℘ 2Kö 18,1"] },
      { number: 10, text: "Hiskia aber zeugte Manasse*, Manasse aber zeugte Amon*, Amon* aber zeugte Josia*,", footnotes: ["℘ 2Kö 20,21", "mit einigen alten Handschr.: Amos\n℘ 2Kö 21,18", "mit einigen alten Handschr.: Amos", "℘ 2Kö 21,24"] },
      { number: 11, text: "Josia aber zeugte Jojachin* und seine Brüder um die Zeit der Wegführung nach Babylon*.", footnotes: ["℘ 2Kö 24,6", "℘ 2Kö 24,14-16; 25,11"] },
      { number: 12, text: "Nach der Wegführung nach Babylon aber zeugte Jojachin Schealtiël, Schealtiël aber zeugte Serubbabel*,", footnotes: ["℘ Esr 3,2"] },
      { number: 13, text: "Serubbabel aber zeugte Abihud, Abihud aber zeugte Eljakim, Eljakim aber zeugte Asor," },
      { number: 14, text: "Asor aber zeugte Zadok, Zadok aber zeugte Achim, Achim aber zeugte Eliud," },
      { number: 15, text: "Eliud aber zeugte Eleasar, Eleasar aber zeugte Mattan, Mattan aber zeugte Jakob," },
      { number: 16, text: "Jakob aber zeugte Josef, den Mann Marias*, von welcher Jesus geboren wurde, der Christus* genannt wird*.", footnotes: ["℘ Lk 1,27; Joh 1,45", "d. h. der Gesalbte, griech. Übersetzung von hebr. maschiach, dem Israel verheißenen Messias", "℘ Kap. 27,17.22"] },
      { number: 17, text: "So sind nun alle Geschlechter von Abraham bis auf David vierzehn Geschlechter und von David bis zur Wegführung nach Babylon vierzehn Geschlechter und von der Wegführung nach Babylon bis auf den Christus vierzehn Geschlechter." },
      { number: 18, text: "*Mit dem Ursprung* Jesu Christi verhielt es sich aber so: Als nämlich Maria, seine Mutter, dem Josef verlobt war, wurde sie, ehe sie zusammengekommen waren, schwanger befunden von dem Heiligen Geist*.", heading: "Die Geburt Jesu", footnotes: ["℘ Lk 2,1-7", "o. Abkunft; o. Stammbaum; mit anderen Handschr.: Mit der Geburt", "℘ Lk 1,27.35 ⇨Esyn: Synopse Nr. 7"] },
      { number: 19, text: "Josef aber, ihr Mann, der gerecht war und sie nicht öffentlich bloßstellen* wollte*, gedachte sie heimlich zu entlassen*.", footnotes: ["w. zur Schau stellen", "℘ 4Mo 5,30", "℘ 5Mo 24,1"] },
      { number: 20, text: "Während er dies aber überlegte, siehe, da erschien ihm ein Engel des Herrn* im Traum* und sprach: Josef, Sohn Davids, fürchte dich nicht, Maria, deine Frau, zu dir zu nehmen! Denn das in ihr Gezeugte ist von dem Heiligen Geist.", footnotes: ["℘ Lk 1,11", "℘ Kap. 2,13.19.22"] },
      { number: 21, text: "Und sie wird einen Sohn gebären, und du sollst seinen Namen Jesus nennen*, denn er wird sein Volk* retten von seinen* Sünden*.", footnotes: ["℘ Lk 1,31; 2,21", "℘ Tit 2,14", "w. von ihren", "℘ Ps 130,8; Joh 1,29; Apg 4,12"] },
      { number: 22, text: "Dies alles geschah aber, damit erfüllt würde, was von dem Herrn geredet ist durch den Propheten, der spricht:" },
      { number: 23, text: "»Siehe, die Jungfrau wird schwanger sein und einen Sohn gebären, und sie werden seinen Namen Emmanuel* nennen«*, was übersetzt ist: Gott mit uns*.", footnotes: ["griech. Form von hebr. Immanuel", "℘ Jes 7,14", "℘ Jes 8,10"] },
      { number: 24, text: "Josef aber, vom Schlaf erwacht, tat, wie ihm der Engel des Herrn befohlen hatte, und nahm seine Frau zu sich;" },
      { number: 25, text: "und er erkannte sie nicht, bis sie einen Sohn* geboren hatte*; und er nannte seinen Namen Jesus*.", footnotes: ["mehrere Handschr. haben: ihren erstgeborenen Sohn", "℘ Gal 4,4", "℘ Lk 2,21"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Als aber Jesus zu Bethlehem in Judäa geboren war*, in den Tagen des Königs Herodes*, siehe, da kamen Weise* vom Morgenland* nach Jerusalem, die sprachen:", heading: "Die Magier aus dem Osten", footnotes: ["℘ Lk 2,4-7", "Herodes d. Gr., unter römischer Oberherrschaft König der Juden (37—4 v. Chr.). Jesus wurde etwa im Jahr 6 vor christl. Zeitrechnung geboren.\n℘ Lk 1,5 ⇨Esyn: Synopse Nr. 8", "w. Magier; d. h. Sterndeuter", "o. Osten"] },
      { number: 2, text: "Wo ist der König der Juden*, der geboren worden ist? Denn wir haben seinen Stern* im Morgenland* gesehen und sind gekommen, ihm zu huldigen*.", footnotes: ["℘ Kap. 27,11.29.37; Joh 19,19", "℘ 4Mo 24,17", "o. Osten", "o. ihn anzubeten"] },
      { number: 3, text: "Als aber der König Herodes es hörte, wurde er bestürzt und ganz Jerusalem mit ihm;" },
      { number: 4, text: "und er versammelte alle Hohenpriester* und Schriftgelehrten des Volkes und erkundigte sich bei ihnen, wo der Christus geboren werden solle.", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien, darunter die von den Römern abgesetzten Hohenpriester, wurden zu »den Hohenpriestern« gerechnet."] },
      { number: 5, text: "Sie aber sagten ihm: Zu Bethlehem* in Judäa; denn so steht durch den Propheten geschrieben:", footnotes: ["℘ Joh 7,42"] },
      { number: 6, text: "»Und du, Bethlehem, Land Juda, bist keineswegs die geringste unter den Fürsten Judas, denn aus dir wird ein Führer hervorkommen, der mein Volk Israel hüten wird*.«", footnotes: ["℘ 2Sam 5,2; Ps 78,71; Jes 40,11; Mi 5,1.3"] },
      { number: 7, text: "Dann berief Herodes die Weisen heimlich und erforschte genau von ihnen die Zeit der Erscheinung des Sternes;" },
      { number: 8, text: "und er sandte sie nach Bethlehem und sprach: Zieht hin und forscht genau nach dem Kind! Wenn ihr es aber gefunden habt, so berichtet es mir, damit auch ich komme und ihm huldige*.", footnotes: ["o. es anbete"] },
      { number: 9, text: "Sie aber zogen hin, als sie den König gehört hatten. Und siehe, der Stern, den sie im Morgenland gesehen hatten, ging vor ihnen her, bis er kam und oben über <der Stelle> stand, wo das Kind war." },
      { number: 10, text: "Als sie aber den Stern sahen, freuten sie sich mit sehr großer Freude*.", footnotes: ["℘ Jon 4,6"] },
      { number: 11, text: "Und als sie in das Haus gekommen waren, sahen sie das Kind mit Maria, seiner Mutter*, und sie fielen nieder und huldigten ihm*, und sie öffneten ihre Schätze* und opferten ihm Gaben: Gold und Weihrauch und Myrrhe*.", footnotes: ["℘ Lk 2,16", "o. beteten es an", "o. Schatzbehälter", "ein wohlriechendes Harz, das zu Salbölen und Arzneien verwendet wurde und sehr kostbar war\n℘ Ps 72,10.11; Jes 60,6"] },
      { number: 12, text: "Und als sie im Traum eine göttliche Weisung empfangen hatten, nicht wieder zu Herodes zurückzukehren, zogen sie auf einem anderen Weg hin in ihr Land." },
      { number: 13, text: "Als sie aber hingezogen waren, siehe, da erscheint ein Engel des Herrn dem Josef im Traum* und spricht: Steh auf, nimm das Kind und seine Mutter zu dir und fliehe nach Ägypten*, und bleibe dort, bis ich es dir sage! Denn Herodes wird das Kind suchen, um es umzubringen*.", heading: "Flucht nach Ägypten — Kindermord zu Bethlehem", footnotes: ["℘ Kap. 1,20", "℘ 1Kö 11,40; Jer 26,21", "℘ Lk 13,31; Offb 12,4 ⇨Esyn: Synopse Nr. 10"] },
      { number: 14, text: "Er aber stand auf, nahm das Kind und seine Mutter des Nachts zu sich und zog hin nach Ägypten." },
      { number: 15, text: "Und er war dort bis zum Tod des Herodes; damit erfüllt würde, was von dem Herrn geredet ist durch den Propheten, der spricht: »Aus Ägypten habe ich meinen Sohn gerufen*.«", footnotes: ["℘ 2Mo 4,22.23; Hos 11,1"] },
      { number: 16, text: "Da ergrimmte Herodes sehr, als er sah, dass er von den Weisen hintergangen worden war; und er sandte hin und ließ alle Jungen töten, die in Bethlehem und in seinem ganzen Gebiet waren, von zwei Jahren und darunter, nach der Zeit, die er von den Weisen genau erforscht hatte." },
      { number: 17, text: "Da wurde erfüllt, was durch den Propheten Jeremia geredet ist, der spricht:" },
      { number: 18, text: "»Eine Stimme ist in Rama gehört worden, Weinen und viel Wehklagen: Rahel beweint ihre Kinder, und sie wollte sich nicht trösten lassen, weil sie nicht <mehr> sind*.«", footnotes: ["℘ Jer 31,15"] },
      { number: 19, text: "Als aber Herodes gestorben war, siehe, da erscheint ein Engel des Herrn dem Josef in Ägypten im Traum*", heading: "Rückkehr aus Ägypten", footnotes: ["℘ V. 13"] },
      { number: 20, text: "und spricht: Steh auf, nimm das Kind und seine Mutter zu dir und zieh in das Land Israel! Denn sie sind gestorben, die dem Kind nach dem Leben trachteten*.", footnotes: ["℘ 2Mo 4,19"] },
      { number: 21, text: "Und er stand auf und nahm das Kind und seine Mutter zu sich, und er kam in das Land Israel." },
      { number: 22, text: "Als er aber hörte, dass Archelaus* über Judäa herrschte* anstelle seines Vaters Herodes, fürchtete er sich, dahin zu gehen; und als er im Traum* eine göttliche Weisung empfangen hatte, zog er hin in die Gegenden von Galiläa", footnotes: ["seit 4 v. Chr. Fürst in Judäa und Samaria, wurde 6 n. Chr. von Kaiser Augustus seines Amtes enthoben und durch römische Statthalter ersetzt", "o. König war", "℘ V. 13 ⇨Esyn: Synopse Nr. 11"] },
      { number: 23, text: "und kam und wohnte in einer Stadt, genannt Nazareth*; damit erfüllt würde, was durch die Propheten geredet ist: »Er wird Nazoräer* genannt werden*.«", footnotes: ["℘ Kap. 21,11; 26,71; Mk 1,9; Lk 1,26; Joh 1,45; Apg 10,38", "Dies ist eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; es ist möglich, dass in Anlehnung an Jes 11,1 das hebr. Wort nezer (d. h. Spross) anklingt.", "℘ Mk 1,24; Lk 18,37; Joh 18,5; Apg 22,8"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*In jenen Tagen aber kommt Johannes der Täufer und predigt in der Wüste von Judäa*", heading: "Johannes der Täufer", footnotes: ["℘ Mk 1,1-8; Lk 3,1-18; (Joh 1,19-28)", "℘ Joh 1,6 ⇨Esyn: Synopse Nr. 13"] },
      { number: 2, text: "und spricht: Tut Buße*! Denn das Reich* der Himmel* ist nahe gekommen*.", footnotes: ["℘ Mk 6,12; Apg 2,38", "o. die Königsherrschaft", "℘ Dan 2,44", "℘ Kap. 4,17; 10,7; Mk 1,15; Lk 10,9"] },
      { number: 3, text: "Denn dieser ist der, von dem durch den Propheten Jesaja geredet ist, der spricht: »Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, macht gerade seine Pfade!«*", footnotes: ["℘ Jes 40,3; 57,14"] },
      { number: 4, text: "Er aber, Johannes, hatte seine Kleidung von Kamelhaaren* und einen ledernen Gürtel um seine Lenden*; seine Speise aber waren Heuschrecken und wilder Honig*.", footnotes: ["℘ Lk 7,25", "w. Lende\n℘ 2Kö 1,8", "℘ Kap. 11,18"] },
      { number: 5, text: "Da ging zu ihm hinaus Jerusalem und ganz Judäa und die ganze Umgegend des Jordan*;", footnotes: ["℘ Kap. 11,7"] },
      { number: 6, text: "und sie wurden von ihm im Jordanfluss getauft*, indem sie ihre Sünden bekannten.", footnotes: ["℘ Joh 3,23"] },
      { number: 7, text: "Als er aber viele der Pharisäer* und Sadduzäer* zu seiner Taufe kommen sah, sprach er zu ihnen: Otternbrut*! Wer hat euch gewiesen, dem kommenden Zorn* zu entfliehen?", footnotes: ["Jüdische Partei, die unter der Leitung der Schriftgelehrten auf peinliche Einhaltung des Gesetzes und der mündlichen Tradition achtete, römerfeindlich und gegenüber allen fremden Einflüssen ablehnend war (der Name bedeutet wahrscheinlich »die Abgesonderten«).", "Jüdische Partei der Reichen, unter dem führenden Einfluss der Hohenpriester, römerfreundlich, offen für hellenistisches Denken, stand in scharfem Gegensatz zur Partei der Pharisäer. Der Name geht vielleicht auf einen Hohenpriester Zadok zurück.", "℘ Kap. 12,34; 23,33; Jes 59,5", "℘ Röm 1,18 ⇨Esyn: Synopse Nr. 14"] },
      { number: 8, text: "Bringt nun der Buße würdige Frucht*;", footnotes: ["℘ Apg 26,20"] },
      { number: 9, text: "und meint nicht, bei euch selbst zu sagen: Wir haben Abraham zum Vater*! Denn ich sage euch, dass Gott dem Abraham aus diesen Steinen Kinder zu erwecken vermag.", footnotes: ["℘ Joh 8,39; Röm 2,28.29"] },
      { number: 10, text: "Schon ist aber die Axt an die Wurzel der Bäume gelegt; jeder Baum nun, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen*.", footnotes: ["℘ Kap. 7,19; Lk 13,7; Joh 15,2.6"] },
      { number: 11, text: "Ich zwar taufe euch mit* Wasser* zur Buße; der aber nach mir kommt, ist stärker als ich*, dessen Sandalen zu tragen ich nicht würdig bin*; er wird euch mit* Heiligem Geist und Feuer taufen*;", footnotes: ["w. in", "℘ Joh 1,33", "℘ Joh 1,15", "℘ Apg 13,24.25", "w. in", "℘ Apg 1,5 ⇨Esyn: Synopse Nr. 16"] },
      { number: 12, text: "seine Worfschaufel ist in seiner Hand, und er wird seine Tenne durch und durch reinigen und seinen Weizen in die Scheune sammeln, die Spreu aber wird er mit unauslöschlichem Feuer verbrennen*.", footnotes: ["℘ Kap. 13,30.49.50; Mk 9,48"] },
      { number: 13, text: "*Dann kommt Jesus aus Galiläa an den Jordan zu Johannes, um sich von ihm taufen zu lassen*. *", heading: "Die Taufe Jesu", footnotes: ["℘ Mk 1,9-11; Lk 3,21-22; (Joh 1,29-34)", "w. um von ihm getauft zu werden", "℘ ⇨Esyn: Synopse Nr. 18"] },
      { number: 14, text: "Johannes aber wehrte ihm* und sprach: Ich habe nötig, von dir getauft zu werden. Und du kommst zu mir?", footnotes: ["℘ Joh 13,6.8"] },
      { number: 15, text: "Jesus aber antwortete und sprach zu ihm: Lass es jetzt <so sein>! Denn so gebührt es uns, alle Gerechtigkeit zu erfüllen*. Da lässt er ihn.", footnotes: ["℘ Kap. 5,17"] },
      { number: 16, text: "Und als Jesus getauft war, stieg er sogleich aus dem Wasser herauf; und siehe, die Himmel wurden ihm* geöffnet, und er sah den Geist* Gottes wie eine Taube herabfahren und auf sich* kommen*.", footnotes: ["in einigen alten Handschr. nicht enthalten", "℘ Kap. 4,1", "w. ihn", "℘ Jes 11,2; 61,1; Apg 4,27"] },
      { number: 17, text: "Und siehe, eine Stimme* <kommt> aus den Himmeln, welche spricht: Dieser ist mein geliebter Sohn*, an dem ich Wohlgefallen gefunden habe*.", footnotes: ["℘ Joh 12,28", "℘ Kap. 14,33; Ps 2,7; Joh 3,35", "℘ Kap. 12,18; 17,5; Jes 42,1; Lk 9,35; 2Petr 1,17"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "*Dann wurde Jesus von dem Geist* in die Wüste hinaufgeführt, um von dem Teufel versucht zu werden;", heading: "Die Versuchung Jesu", footnotes: ["℘ Mk 1,12-13; Lk 4,1-13", "℘ Kap. 3,16; Apg 8,29.39 ⇨Esyn: Synopse Nr. 20"] },
      { number: 2, text: "und als er vierzig Tage und vierzig Nächte* gefastet hatte, hungerte ihn schließlich*.", footnotes: ["℘ 2Mo 34,28; 1Kö 19,8", "℘ Kap. 21,18"] },
      { number: 3, text: "Und der Versucher trat zu ihm hin und sprach*: Wenn du Gottes Sohn bist*, so sprich, dass diese Steine Brote werden!", footnotes: ["℘ 1Mo 3,1", "℘ Kap. 27,40"] },
      { number: 4, text: "Er aber antwortete und sprach: Es steht geschrieben: »Nicht von Brot allein soll der Mensch leben, sondern von jedem Wort, das durch den Mund Gottes ausgeht*.«", footnotes: ["℘ 5Mo 8,3; Joh 4,34"] },
      { number: 5, text: "Darauf nimmt der Teufel ihn mit in die heilige Stadt* und stellte ihn auf die Zinne des Tempels", footnotes: ["℘ Kap. 27,53; Neh 11,1; Jes 52,1; Offb 11,2"] },
      { number: 6, text: "und spricht zu ihm: Wenn du Gottes Sohn bist*, so wirf dich hinab! Denn es steht geschrieben: »Er wird seinen Engeln über dir befehlen, und sie werden dich auf den Händen tragen, damit du nicht etwa deinen Fuß an einen Stein stößt*.«", footnotes: ["℘ Kap. 27,40", "℘ Ps 91,11.12; Spr 3,23"] },
      { number: 7, text: "Jesus sprach zu ihm: Wiederum steht geschrieben: »Du sollst den Herrn, deinen Gott, nicht versuchen*.«", footnotes: ["℘ 5Mo 6,16; Apg 5,9; 1Kor 10,9"] },
      { number: 8, text: "Wiederum nimmt der Teufel ihn mit auf einen sehr hohen Berg und zeigt ihm alle Reiche* der Welt und ihre Herrlichkeit", footnotes: ["o. Königsherrschaften"] },
      { number: 9, text: "und sprach zu ihm: Dies alles will ich dir geben, wenn du niederfallen und mich anbeten willst." },
      { number: 10, text: "Da spricht Jesus zu ihm: Geh hinweg, Satan! Denn es steht geschrieben: »Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen*.«", footnotes: ["℘ 5Mo 6,13; 10,20; 1Sam 7,3"] },
      { number: 11, text: "Dann verlässt ihn der Teufel*, und siehe, Engel kamen herbei und dienten ihm*.", footnotes: ["℘ Jak 4,7", "℘ Lk 22,43; Joh 1,51; Hebr 1,6"] },
      { number: 12, text: "*Als er aber gehört hatte, dass Johannes überliefert worden war*, ging er weg nach Galiläa*;", heading: "Bußpredigt in Galiläa", footnotes: ["℘ Mk 1,14.15; Lk 4,14.15", "℘ Kap. 11,2; 14,3; Lk 3,20", "℘ Kap. 12,15; 14,13; Joh 4,3.43 ⇨Esyn: Synopse Nr. 30"] },
      { number: 13, text: "und er verließ Nazareth und kam und wohnte in Kapernaum*, das am See* liegt, in dem Gebiet von Sebulon und Naftali;", footnotes: ["℘ Kap. 9,1; 11,23; Mk 1,21; Lk 4,30.31 ⇨Esyn: Synopse Nr. 32", "d. i. der See Genezareth oder Tiberias"] },
      { number: 14, text: "damit erfüllt würde, was durch den Propheten Jesaja geredet worden ist, der sagt:" },
      { number: 15, text: "»Land Sebulon und Land Naftali, gegen den See hin, jenseits des Jordan, Galiläa der Nationen:" },
      { number: 16, text: "Das Volk, das in Finsternis saß, hat ein großes Licht gesehen, und denen, die im Land und Schatten des Todes saßen, ist Licht aufgegangen*.«", footnotes: ["℘ Jes 8,23; 9,1; Lk 1,79; Joh 1,5"] },
      { number: 17, text: "Von da an begann Jesus zu predigen und zu sagen: Tut Buße, denn das Reich* der Himmel ist nahe gekommen*!", footnotes: ["o. die Königsherrschaft", "℘ Kap. 3,2"] },
      { number: 18, text: "*Als er aber am See von Galiläa entlangging, sah er zwei Brüder: Simon, genannt Petrus*, und Andreas, seinen Bruder*, die ein Netz in den See warfen, denn sie waren Fischer.", heading: "Die ersten Jünger", footnotes: ["℘ Mk 1,16-20; Lk 5,1-11", "℘ Kap. 16,18; Mk 3,16", "℘ Kap. 10,2; Joh 1,40-42 ⇨Esyn: Synopse Nr. 34"] },
      { number: 19, text: "Und er spricht zu ihnen: Kommt, mir nach*! Und ich werde euch zu Menschenfischern machen.", footnotes: ["℘ Kap. 8,22; 9,9; Joh 1,43"] },
      { number: 20, text: "Sie aber verließen sogleich die Netze und folgten ihm nach*.", footnotes: ["℘ Kap. 19,27"] },
      { number: 21, text: "Und als er von dort weiterging, sah er zwei andere Brüder: Jakobus, den <Sohn> des Zebedäus, und Johannes, seinen Bruder*, im Boot mit ihrem Vater Zebedäus, wie sie ihre Netze ausbesserten; und er rief sie.", footnotes: ["℘ Kap. 10,2; Apg 12,2"] },
      { number: 22, text: "Sie aber verließen sogleich das Boot und ihren Vater und folgten ihm nach*.", footnotes: ["℘ Kap. 19,27"] },
      { number: 23, text: "*Und er zog in ganz Galiläa umher, lehrte in ihren Synagogen* und predigte das Evangelium des Reiches* und heilte jede Krankheit und jedes Gebrechen unter dem Volk*.", heading: "Predigt und Heilungen", footnotes: ["℘ Mk 1,32-39; Lk 4,40-44", "In der Synagoge kamen die Juden, bes. am Sabbat, zum Gebet, zur Schriftlesung und -auslegung zusammen. Sie war Ausgangspunkt der Schriftgelehrsamkeit und der Zucht (vgl. Anm. zu Kap. 10,17). Die Synagoge konnte jedoch nicht den Tempel ersetzen, wo allein geopfert werden durfte.", "o. der/die Königsherrschaft", "℘ Kap. 9,35; Mk 1,21; Lk 4,15; Apg 10,38 ⇨Esyn: Synopse Nr. 40"] },
      { number: 24, text: "Und die Kunde von ihm ging hinaus in das ganze Syrien; und sie brachten zu ihm alle Leidenden, die mit mancherlei Krankheiten und Qualen behaftet waren, und Besessene und Mondsüchtige und Gelähmte; und er heilte sie*.", footnotes: ["℘ Kap. 8,16; 12,15; 14,14.35.36; 15,30; 19,2; Mk 6,55.56 ⇨Esyn: Synopse Nr. 50"] },
      { number: 25, text: "Und es folgten ihm große Volksmengen von Galiläa und dem Zehnstädtegebiet* und Jerusalem und Judäa und von jenseits des Jordan*.", footnotes: ["Landschaft mit zehn Städten im Nordosten Palästinas", "℘ Mk 3,7.8; Lk 5,15"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Als er aber die Volksmengen sah, stieg er auf den Berg*; und als er sich gesetzt hatte, traten seine Jünger zu ihm.", heading: "Seligpreisungen", footnotes: ["℘ Lk 6,20-23", "℘ Kap. 15,29; Joh 6,3"] },
      { number: 2, text: "Und er tat seinen Mund auf, lehrte sie und sprach:" },
      { number: 3, text: "Glückselig die Armen im Geist*, denn ihrer ist das Reich* der Himmel*.", footnotes: ["℘ Jes 57,15", "o. der/die Königsherrschaft", "℘ Jak 2,5 ⇨Esyn: Synopse Nr. 51"] },
      { number: 4, text: "Glückselig die Trauernden, denn sie werden getröstet werden*.", footnotes: ["℘ Ps 119,28; Jes 61,2.3; Joh 16,20; Offb 7,17"] },
      { number: 5, text: "Glückselig die Sanftmütigen, denn sie werden das Land erben*.", footnotes: ["℘ Ps 37,11"] },
      { number: 6, text: "Glückselig, die nach der Gerechtigkeit hungern und dürsten, denn sie werden gesättigt werden*.", footnotes: ["℘ Spr 21,21; Joh 6,35"] },
      { number: 7, text: "Glückselig die Barmherzigen, denn ihnen wird Barmherzigkeit widerfahren*.", footnotes: ["℘ Ps 41,2"] },
      { number: 8, text: "Glückselig, die reinen Herzens sind*, denn sie werden Gott schauen*.", footnotes: ["℘ Ps 24,3.4", "℘ Ps 17,15; Offb 22,4"] },
      { number: 9, text: "Glückselig die Friedensstifter, denn sie werden Söhne Gottes heißen*.", footnotes: ["℘ Hebr 12,14"] },
      { number: 10, text: "Glückselig die um Gerechtigkeit willen Verfolgten, denn ihrer ist das Reich* der Himmel*.", footnotes: ["o. der/die Königsherrschaft", "℘ 2Thes 1,5; 1Petr 2,19"] },
      { number: 11, text: "Glückselig seid ihr, wenn sie euch schmähen und verfolgen und alles Böse lügnerisch* gegen euch reden werden um meinetwillen*.", footnotes: ["in einigen Handschr. nicht enthalten", "℘ Apg 5,41"] },
      { number: 12, text: "Freut euch und jubelt, denn euer Lohn ist groß in den Himmeln*; denn ebenso haben sie die Propheten verfolgt, die vor euch waren*.", footnotes: ["℘ Hebr 11,26", "℘ Kap. 23,31; Apg 7,52; Jak 5,10"] },
      { number: 13, text: "Ihr seid das Salz der Erde; wenn aber das Salz fade geworden ist, womit soll es gesalzen werden*? Es taugt zu nichts mehr, als hinausgeworfen und von den Menschen zertreten zu werden*.", heading: "Die Jünger als Salz und Licht", footnotes: ["o. womit soll gesalzen werden", "℘ Mk 9,50; Lk 14,34.35 ⇨Esyn: Synopse Nr. 52"] },
      { number: 14, text: "Ihr seid das Licht der Welt*; eine Stadt, die oben auf einem Berg liegt, kann nicht verborgen sein.", footnotes: ["℘ Joh 8,12; Phil 2,15 ⇨Esyn: Synopse Nr. 53"] },
      { number: 15, text: "Man zündet auch nicht eine Lampe an und setzt sie unter den Scheffel*, sondern auf das Lampengestell, und sie leuchtet allen, die im Hause sind*.", footnotes: ["w. Modios; s. Tabelle »Maße«", "℘ Mk 4,21; Lk 11,33"] },
      { number: 16, text: "So soll euer Licht leuchten vor den Menschen, damit sie eure guten Werke sehen* und euren Vater, der in den Himmeln ist, verherrlichen*.", footnotes: ["℘ 1Tim 5,25; Jak 3,13", "℘ Joh 15,8; Tit 2,7; 1Petr 2,12"] },
      { number: 17, text: "Meint nicht, dass ich gekommen sei, das Gesetz oder die Propheten aufzulösen; ich bin nicht gekommen aufzulösen, sondern zu erfüllen*.", heading: "Gesetz, Propheten und Reich der Himmel", footnotes: ["℘ Kap. 3,15; Jes 42,21; Röm 10,4 ⇨Esyn: Synopse Nr. 54"] },
      { number: 18, text: "Denn wahrlich, ich sage euch: Bis der Himmel und die Erde vergehen*, soll auch nicht ein Jota oder ein Strichlein von dem Gesetz vergehen, bis alles geschehen ist*.", footnotes: ["℘ Jes 51,6", "℘ Kap. 24,35; Ps 119,89; Jes 40,8; Mk 13,31; Lk 16,17; Joh 10,35; 1Petr 1,25"] },
      { number: 19, text: "Wer nun eins dieser geringsten Gebote auflöst und so die Menschen lehrt, wird der Geringste heißen im Reich* der Himmel; wer sie aber tut und lehrt, dieser wird groß heißen im Reich* der Himmel*.", footnotes: ["o. in der Königsherrschaft", "o. in der Königsherrschaft", "℘ Ps 119,4"] },
      { number: 20, text: "Denn ich sage euch: Wenn nicht eure Gerechtigkeit die der Schriftgelehrten und Pharisäer weit übertrifft*, so werdet ihr keinesfalls in das Reich* der Himmel hineinkommen*.", footnotes: ["w. überreich ist, mehr als die der Schriftgelehrten und Pharisäer\n℘ Phil 3,9", "o. in die Königsherrschaft", "℘ Kap. 18,3; 23,13; Mk 10,15"] },
      { number: 21, text: "Ihr habt gehört, dass zu den Alten gesagt ist: Du sollst nicht töten*; wer aber töten wird, der wird dem Gericht verfallen sein*.", heading: "Erfüllung des Gesetzes: Was ist Töten?", footnotes: ["℘ Kap. 19,18; 2Mo 20,13.14; 5Mo 5,17.18; Mk 10,19; Lk 18,20; Röm 13,9; Jak 2,11", "℘ 2Mo 21,12; 3Mo 24,17 ⇨Esyn: Synopse Nr. 55"] },
      { number: 22, text: "Ich aber sage euch, dass jeder, der seinem Bruder zürnt*, dem Gericht verfallen sein wird; wer aber zu seinem Bruder sagt: Raka*!, dem Hohen Rat* verfallen sein wird; wer aber sagt: Du Narr*!, der Hölle des Feuers verfallen sein wird*.", footnotes: ["mit vielen Handschr.: ohne Grund zürnt", "ein Ausdruck der Verachtung, etwa »Dummkopf«", "w. Synedrium; s. auch Anm. zu Kap. 26,59", "verächtlicher Ausdruck, etwa »Verrückter«, zuweilen auch »Gottloser«", "℘ Kap. 18,8.9; 25,41; Mk 9,43.47"] },
      { number: 23, text: "Wenn du nun deine Gabe darbringst zu dem Altar und dich dort erinnerst, dass dein Bruder etwas gegen dich hat*,", footnotes: ["℘ Mk 11,25"] },
      { number: 24, text: "so lass deine Gabe dort vor dem Altar und geh vorher hin*, versöhne dich mit deinem Bruder, und dann komm und bring deine Gabe dar!", footnotes: ["℘ Kap. 18,15"] },
      { number: 25, text: "Komm deinem Gegner schnell entgegen*, während du mit ihm auf dem Weg bist! Damit nicht etwa der Gegner dich dem Richter überliefert und der Richter dem Diener und du ins Gefängnis geworfen wirst*.", footnotes: ["w. sei deinem Gegner schnell wohlgesinnt", "℘ Kap. 6,15; 18,35; Mk 11,26; Lk 12,58.59"] },
      { number: 26, text: "Wahrlich, ich sage dir: Du wirst nicht von dort herauskommen, bis du auch die letzte Münze* bezahlt hast*.", footnotes: ["w. Quadrans; s. Tabelle »Münzen und Geldeinheiten«", "℘ Kap. 18,34"] },
      { number: 27, text: "Ihr habt gehört, dass gesagt ist: Du sollst nicht ehebrechen*.", heading: "Erfüllung des Gesetzes: Was ist Ehebruch?", footnotes: ["℘ V. 21 ⇨Esyn: Synopse Nr. 56"] },
      { number: 28, text: "Ich aber sage euch, dass jeder, der eine Frau ansieht, sie zu begehren, schon Ehebruch mit ihr begangen hat in seinem Herzen*.", footnotes: ["℘ Kap. 15,19; 2Sam 11,2; Hi 31,1; 2Petr 2,14"] },
      { number: 29, text: "Wenn aber dein rechtes Auge dir Anlass zur Sünde gibt*, so reiß es aus und wirf es von dir! Denn es ist dir besser, dass eins deiner Glieder umkommt und nicht dein ganzer Leib in die Hölle geworfen wird*.", footnotes: ["o. dich ärgert", "℘ V. 22; Kap. 10,28"] },
      { number: 30, text: "Und wenn deine rechte Hand dir Anlass zur Sünde gibt*, so hau sie ab und wirf sie von dir! Denn es ist dir besser, dass eins deiner Glieder umkommt und nicht dein ganzer Leib in die Hölle geworfen wird*.", footnotes: ["o. dich ärgert", "℘ V. 22; Kap. 10,28"] },
      { number: 31, text: "Es ist aber gesagt: Wer seine Frau entlassen will, gebe ihr einen Scheidebrief*.", footnotes: ["℘ Kap. 19,7; 5Mo 24,1; Mk 10,4"] },
      { number: 32, text: "Ich aber sage euch: Jeder, der seine Frau entlassen wird, außer aufgrund von Hurerei, macht, dass mit ihr Ehebruch begangen wird*; und wer eine Entlassene heiratet, begeht Ehebruch*.", footnotes: ["℘ 1Kor 7,10.11", "℘ Kap. 19,9; Mk 10,11; Lk 16,18"] },
      { number: 33, text: "Wiederum habt ihr gehört, dass zu den Alten gesagt ist: Du sollst nicht falsch schwören*, du sollst aber dem Herrn deine Eide erfüllen*.", heading: "Erfüllung des Gesetzes: Was ist falsches Schwören?", footnotes: ["℘ 2Mo 20,7; 3Mo 19,12; 5Mo 5,11", "℘ 4Mo 30,3; 5Mo 23,22; Ps 50,14 ⇨Esyn: Synopse Nr. 57"] },
      { number: 34, text: "Ich aber sage euch: Schwört überhaupt nicht! Weder bei dem Himmel, denn er ist Gottes Thron*;", footnotes: ["℘ Kap. 23,22; Ps 11,4; Apg 7,49; Jak 5,12"] },
      { number: 35, text: "noch bei der Erde, denn sie ist seiner Füße Schemel*; noch bei Jerusalem, denn sie ist des großen Königs Stadt*;", footnotes: ["℘ Ps 99,5; Jes 66,1; Kla 2,1", "℘ Ps 48,3"] },
      { number: 36, text: "noch sollst du bei deinem Haupt schwören, denn du kannst nicht ein Haar weiß oder schwarz machen." },
      { number: 37, text: "Es sei aber eure Rede: Ja, ja! Nein, nein! Was aber darüber hinausgeht, ist vom* Bösen*.", footnotes: ["o. aus dem", "℘ 2Kor 1,17; Jak 5,12"] },
      { number: 38, text: "*Ihr habt gehört, dass gesagt ist: Auge um Auge und Zahn um Zahn*.", heading: "Erfüllung des Gesetzes: Was ist Vergelten?", footnotes: ["℘ Lk 6,27-36", "℘ 2Mo 21,24; 3Mo 24,20; 5Mo 19,21 ⇨Esyn: Synopse Nr. 58"] },
      { number: 39, text: "Ich aber sage euch: Widersteht nicht dem Bösen*, sondern wenn jemand dich auf deine rechte Backe schlagen wird, dem biete auch die andere dar*;", footnotes: ["℘ Jak 5,6", "℘ 3Mo 19,18; Spr 20,22"] },
      { number: 40, text: "und dem, der mit dir vor Gericht gehen und dein Untergewand nehmen will, dem lass auch den Mantel*!", footnotes: ["℘ 1Kor 6,7"] },
      { number: 41, text: "Und wenn jemand dich zwingen wird, eine Meile zu gehen, mit dem geh zwei!" },
      { number: 42, text: "Gib dem, der dich bittet, und weise den nicht ab, der von dir borgen will*!", footnotes: ["℘ 5Mo 15,8; Ps 37,21; Spr 21,26"] },
      { number: 43, text: "Ihr habt gehört, dass gesagt ist: Du sollst deinen Nächsten lieben* und deinen Feind hassen*.", footnotes: ["℘ Kap. 19,19; 22,39; 3Mo 19,18.34; Mk 12,31.33; Lk 10,27; Gal 5,14; Jak 2,8", "℘ 5Mo 23,6.7 ⇨Esyn: Synopse Nr. 59"] },
      { number: 44, text: "Ich aber sage euch: Liebt eure Feinde*, und betet für die, die euch verfolgen*,", footnotes: ["Mehrere Handschr. fügen hinzu: segnet, die euch fluchen, tut wohl denen, die euch hassen; vor »verfolgen« ist eingefügt: beleidigen und", "℘ Hi 31,29; Lk 23,34; Röm 12,14.20; 1Kor 4,12"] },
      { number: 45, text: "damit ihr Söhne eures Vaters seid, der in den Himmeln ist! Denn er lässt seine Sonne aufgehen über Böse und Gute und lässt regnen über Gerechte und Ungerechte*.", footnotes: ["℘ Ps 145,9; Apg 14,17"] },
      { number: 46, text: "Denn wenn ihr liebt, die euch lieben, welchen Lohn habt ihr? Tun nicht auch die Zöllner dasselbe?" },
      { number: 47, text: "Und wenn ihr allein eure Brüder grüßt, was tut ihr Besonderes? Tun nicht auch die von den Nationen dasselbe?" },
      { number: 48, text: "Ihr nun sollt vollkommen sein*, wie euer himmlischer Vater vollkommen ist.", footnotes: ["℘ Kap. 19,21; 5Mo 18,13; Hebr 6,1; Jak 1,4"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Habt acht auf eure Gerechtigkeit*, dass ihr <sie> nicht vor den Menschen übt*, um von ihnen gesehen zu werden! Sonst habt ihr keinen Lohn bei eurem Vater, der in den Himmeln ist*.", heading: "Rechtes Almosengeben", footnotes: ["mit anderen Handschr.: eure Wohltat, euer Almosen", "℘ Kap. 23,5", "℘ V. 5.16 ⇨Esyn: Synopse Nr. 60"] },
      { number: 2, text: "Wenn du nun Almosen gibst, sollst du nicht vor dir her posaunen lassen, wie die Heuchler tun in den Synagogen und auf den Gassen, damit sie von den Menschen geehrt werden*. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.", footnotes: ["℘ Joh 5,44; Phil 2,3"] },
      { number: 3, text: "Wenn du aber Almosen gibst, so soll deine Linke nicht wissen, was deine Rechte tut;" },
      { number: 4, text: "damit dein Almosen im Verborgenen sei, und dein Vater, der im Verborgenen sieht*, wird dir vergelten.", footnotes: ["℘ V. 6.18; Ps 139,2.12"] },
      { number: 5, text: "*Und wenn ihr betet, sollt ihr nicht sein wie die Heuchler, denn sie lieben es, in den Synagogen und an den Ecken der Straßen stehend zu beten, damit sie von den Menschen gesehen werden. Wahrlich, ich sage euch, sie haben ihren Lohn dahin*.", heading: "Rechtes Beten", footnotes: ["℘ vgl. Lk 11,1-4", "℘ V. 1.2.16 ⇨Esyn: Synopse Nr. 61"] },
      { number: 6, text: "Wenn du aber betest, so geh in deine Kammer, und wenn du deine Tür geschlossen hast*, bete zu deinem Vater, der im Verborgenen ist*! Und dein Vater, der im Verborgenen sieht, wird dir vergelten.", footnotes: ["℘ 2Kö 4,33; Jes 26,20; Dan 6,11", "℘ V. 18"] },
      { number: 7, text: "Wenn ihr aber betet, sollt ihr nicht plappern wie die von den Nationen; denn sie meinen, dass sie um ihres vielen Redens willen erhört werden*.", footnotes: ["℘ 1Kö 18,26-29; Pred 5,1.2; Mk 12,40 ⇨Esyn: Synopse Nr. 62"] },
      { number: 8, text: "Seid ihnen nun nicht gleich! Denn euer Vater weiß, was ihr benötigt, ehe ihr ihn bittet*.", footnotes: ["℘ V. 32; Lk 12,30"] },
      { number: 9, text: "Betet ihr nun so: Unser Vater*, der <du bist> in den Himmeln*, geheiligt werde dein Name*;", footnotes: ["℘ Jes 63,16", "℘ Kap. 23,9", "℘ Jes 29,23"] },
      { number: 10, text: "dein Reich* komme*; dein Wille geschehe*, wie im Himmel, so auch auf Erden!", footnotes: ["o. deine Königsherrschaft", "℘ Offb 11,15", "℘ Kap. 26,42; Apg 21,14"] },
      { number: 11, text: "Unser tägliches Brot* gib uns heute*;", footnotes: ["d. h. das für den heutigen oder folgenden Tag nötige Brot", "℘ Spr 30,8"] },
      { number: 12, text: "und vergib uns unsere Schulden, wie auch wir unseren Schuldnern vergeben haben*;", footnotes: ["mit anderen Handschr.: vergeben\n℘ Kap. 18,21 ⇨Esyn: Synopse Nr. 99"] },
      { number: 13, text: "und führe uns nicht in Versuchung, sondern rette uns von dem Bösen!* —", footnotes: ["An dieser Stelle fügen andere Handschr. hinzu: Denn dein ist das Reich und die Kraft und die Herrlichkeit in Ewigkeit. Amen.\n℘ 2Thes 3,3; 2Tim 4,18; 2Petr 2,9"] },
      { number: 14, text: "Denn wenn ihr den Menschen ihre Vergehungen vergebt, so wird euer himmlischer Vater auch euch vergeben*;", footnotes: ["℘ Mk 11,25; Lk 6,37; Kol 3,13"] },
      { number: 15, text: "wenn ihr aber den Menschen nicht vergebt, so wird euer Vater eure Vergehungen auch nicht vergeben*.", footnotes: ["℘ Kap. 18,35; Mk 11,26; Jak 2,13"] },
      { number: 16, text: "Wenn ihr aber fastet, so seht nicht düster aus wie die Heuchler! Denn sie verstellen ihre Gesichter, damit sie den Menschen als Fastende erscheinen*. Wahrlich, ich sage euch, sie haben ihren Lohn dahin*.", heading: "Rechtes Fasten", footnotes: ["℘ Jes 58,5", "℘ V. 2.5 ⇨Esyn: Synopse Nr. 63"] },
      { number: 17, text: "Wenn du aber fastest, so salbe dein Haupt und wasche dein Gesicht," },
      { number: 18, text: "damit du nicht den Menschen als ein Fastender erscheinst, sondern deinem Vater, der im Verborgenen ist! Und dein Vater, der im Verborgenen sieht, wird dir vergelten*.", footnotes: ["℘ V. 4.6"] },
      { number: 19, text: "*Sammelt euch nicht Schätze auf der Erde*, wo Motte und Fraß* zerstören* und wo Diebe durchgraben und stehlen*;", heading: "Warnung vor Habsucht und irdischen Sorgen", footnotes: ["℘ vgl. Lk 12,33.34", "℘ Lk 12,21", "wahrscheinlich ein Schädlingsinsekt", "℘ Jak 5,2.3", "℘ Spr 23,4.5 ⇨Esyn: Synopse Nr. 64"] },
      { number: 20, text: "sammelt euch aber Schätze im Himmel*, wo weder Motte noch Fraß* zerstören und wo Diebe nicht durchgraben noch stehlen!", footnotes: ["℘ Kap. 19,21; Mk 10,21; Lk 18,22; Kol 3,2; 1Tim 6,19; Hebr 10,34", "wahrscheinlich ein Schädlingsinsekt"] },
      { number: 21, text: "Denn wo dein Schatz ist, da wird auch dein Herz sein." },
      { number: 22, text: "*Die Lampe des Leibes ist das Auge; wenn nun dein Auge klar* ist, so wird dein ganzer Leib licht sein; *", footnotes: ["℘ Lk 11,34-36", "w. schlicht, einfältig", "℘ ⇨Esyn: Synopse Nr. 65"] },
      { number: 23, text: "wenn aber dein Auge böse ist*, so wird dein ganzer Leib finster sein. Wenn nun das Licht, das in dir ist, Finsternis ist, wie groß die Finsternis!", footnotes: ["℘ Kap. 20,15; Mk 7,22"] },
      { number: 24, text: "*Niemand kann zwei Herren dienen*; denn entweder wird er den einen hassen und den anderen lieben, oder er wird einem anhängen und den anderen verachten. Ihr könnt nicht Gott dienen und dem Mammon*.", footnotes: ["℘ vgl. Lk 12,22-31", "o. Sklave sein\n℘ Röm 6,16", "d. h. Besitz, Vermögen\n℘ Lk 16,13; Jak 4,4; 1Jo 2,15 ⇨Esyn: Synopse Nr. 66"] },
      { number: 25, text: "Deshalb sage ich euch: Seid nicht besorgt* für euer Leben, was ihr essen und was ihr trinken sollt, noch für euren Leib, was ihr anziehen sollt! Ist nicht das Leben mehr als die Speise und der Leib mehr als die Kleidung?", footnotes: ["℘ 1Kor 7,32; Phil 4,6; 1Petr 5,7 ⇨Esyn: Synopse Nr. 67"] },
      { number: 26, text: "Seht hin auf die Vögel des Himmels*, dass sie weder säen noch ernten noch in Scheunen sammeln, und euer himmlischer Vater ernährt sie <doch>. Seid ihr nicht viel wertvoller als sie*?", footnotes: ["℘ Ps 147,9", "℘ Kap. 10,29.31; 12,12; Ps 145,15"] },
      { number: 27, text: "Wer aber unter euch kann mit Sorgen seiner Lebenslänge* eine Elle zusetzen?", footnotes: ["o. seiner Größe"] },
      { number: 28, text: "Und warum seid ihr um Kleidung besorgt? Betrachtet die Lilien des Feldes, wie sie wachsen; sie mühen sich nicht, auch spinnen sie nicht." },
      { number: 29, text: "Ich sage euch aber, dass selbst nicht Salomo in all seiner Herrlichkeit bekleidet war wie eine von diesen*.", footnotes: ["℘ 1Kö 3,13"] },
      { number: 30, text: "Wenn aber Gott das Gras des Feldes, das heute steht und morgen in den Ofen geworfen wird, so kleidet, <wird er das> nicht viel mehr euch <tun>, ihr Kleingläubigen*?", footnotes: ["℘ Kap. 8,26; 14,31; 16,8"] },
      { number: 31, text: "So seid nun nicht besorgt, indem ihr sagt: Was sollen wir essen? Oder: Was sollen wir trinken? Oder: Was sollen wir anziehen*?", footnotes: ["℘ 1Kor 7,32; Phil 4,6; 1Petr 5,7"] },
      { number: 32, text: "Denn nach diesem allen trachten die Nationen; denn euer himmlischer Vater weiß, dass ihr dies alles benötigt*.", footnotes: ["℘ V. 8"] },
      { number: 33, text: "Trachtet aber zuerst nach dem Reich* Gottes und nach seiner* Gerechtigkeit! Und dies alles wird euch hinzugefügt werden.", footnotes: ["o. der Königsherrschaft", "d. i. Gottes"] },
      { number: 34, text: "So seid nun nicht besorgt um den morgigen Tag! Denn der morgige Tag wird für sich selbst sorgen*. Jeder Tag hat an seinem Übel genug*.", footnotes: ["℘ 2Mo 16,19", "℘ Hi 7,1"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Richtet nicht, damit ihr nicht gerichtet werdet*!", heading: "Warnung vor dem Richten und dem Entweihen des Heiligen", footnotes: ["℘ Lk 6,37.38.41.42", "℘ Röm 2,1.3; 14,4.10; 1Kor 4,5; Jak 4,11.12; 5,9 ⇨Esyn: Synopse Nr. 68"] },
      { number: 2, text: "Denn mit welchem Gericht ihr richtet, werdet ihr gerichtet werden*, und mit welchem Maß ihr messt, wird euch zugemessen werden*.", footnotes: ["℘ Jak 2,13", "℘ Mk 4,24"] },
      { number: 3, text: "Was aber siehst du den Splitter, der in deines Bruders Auge ist, den Balken aber in deinem Auge nimmst du nicht wahr?" },
      { number: 4, text: "Oder wie wirst du zu deinem Bruder sagen: Erlaube, ich will den Splitter aus deinem Auge ziehen; und siehe, der Balken ist in deinem Auge*?", footnotes: ["℘ Kap. 23,24"] },
      { number: 5, text: "Heuchler, zieh zuerst den Balken aus deinem Auge! Und dann wirst du klar sehen, um den Splitter aus deines Bruders Auge zu ziehen." },
      { number: 6, text: "Gebt nicht das Heilige den Hunden; werft auch nicht eure Perlen vor die Schweine, damit sie diese nicht etwa mit ihren Füßen zertreten und sich umwenden und euch zerreißen! *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 69"] },
      { number: 7, text: "*Bittet, und es wird euch gegeben werden*; sucht, und ihr werdet finden*; klopft an, und es wird euch geöffnet werden*!", heading: "Zuversichtliches Beten", footnotes: ["℘ vgl. Lk 11,5-13", "℘ Kap. 18,19; 21,22; Mk 11,24; Joh 14,13.14; Jak 1,5; 1Jo 5,14.15", "℘ 5Mo 4,29; 1Chr 28,9; 2Chr 15,2; Spr 8,17", "℘ Jer 29,13.14 ⇨Esyn: Synopse Nr. 70"] },
      { number: 8, text: "Denn jeder Bittende empfängt*, und der Suchende findet*, und dem Anklopfenden wird geöffnet werden*.", footnotes: ["℘ Jer 29,13.14", "℘ Jer 29,13.14", "℘ Jer 29,13.14"] },
      { number: 9, text: "Oder welcher Mensch ist unter euch, der, wenn sein Sohn ihn um ein Brot bittet, ihm einen Stein geben wird?" },
      { number: 10, text: "Und wenn er um einen Fisch bittet, wird er ihm eine Schlange geben?" },
      { number: 11, text: "Wenn nun ihr, die ihr böse seid*, euren Kindern gute Gaben zu geben wisst, wie viel mehr wird euer Vater, der in den Himmeln ist, Gutes geben* denen, die ihn bitten*!", footnotes: ["℘ 1Mo 6,5; 8,21; Röm 3,10-12", "℘ Jak 1,17", "℘ Ps 86,5"] },
      { number: 12, text: "Alles nun, was ihr wollt, dass euch die Menschen tun sollen, das tut ihr ihnen auch*! Denn darin besteht das Gesetz und die Propheten*.", heading: "Verhalten gegen andere — Die enge Pforte", footnotes: ["℘ Lk 6,31", "℘ Kap. 22,40; Röm 13,8-10 ⇨Esyn: Synopse Nr. 71"] },
      { number: 13, text: "Geht hinein durch die enge Pforte*! Denn weit ist die Pforte und breit der Weg, der zum Verderben führt*, und viele sind, die auf ihm hineingehen.", footnotes: ["℘ Lk 13,24", "℘ Spr 14,12 ⇨Esyn: Synopse Nr. 72"] },
      { number: 14, text: "Denn* eng ist die Pforte und schmal der Weg, der zum Leben führt*, und wenige sind, die ihn finden*.", footnotes: ["mit anderen Handschr.: Wie . . .!", "℘ Ps 16,11", "℘ Lk 13,24"] },
      { number: 15, text: "*Hütet euch vor den falschen Propheten*, die in Schafskleidern zu euch kommen! Inwendig aber sind sie reißende Wölfe*.", heading: "Warnung vor falschen Propheten", footnotes: ["℘ Lk 6,43-45", "℘ Kap. 24,11.24; 5Mo 13,1.2; Jer 14,14; Mk 13,22; 1Jo 4,1", "℘ Apg 20,29; Offb 13,11 ⇨Esyn: Synopse Nr. 73"] },
      { number: 16, text: "An ihren Früchten werdet ihr sie erkennen. Liest man etwa von Dornen Trauben oder von Disteln Feigen*?", footnotes: ["℘ Jak 3,12 ⇨Esyn: Synopse Nr. 118"] },
      { number: 17, text: "So bringt jeder gute Baum gute Früchte, aber der faule Baum bringt schlechte Früchte." },
      { number: 18, text: "Ein guter Baum kann nicht schlechte Früchte bringen, noch <kann> ein fauler Baum gute Früchte bringen." },
      { number: 19, text: "Jeder Baum, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen*.", footnotes: ["℘ Kap. 3,10; Lk 3,9"] },
      { number: 20, text: "Deshalb, an ihren Früchten werdet ihr sie erkennen*.", footnotes: ["℘ Kap. 12,33"] },
      { number: 21, text: "*Nicht jeder, der zu mir sagt: Herr, Herr*!, wird in das Reich* der Himmel hineinkommen, sondern wer den Willen meines Vaters tut, der in den Himmeln ist*.", footnotes: ["℘ V. 21-29: Lk 6,46-49", "℘ Jes 29,13", "o. die Königsherrschaft", "℘ Kap. 12,50; 21,31; Röm 2,13; Jak 1,22.25; 1Jo 2,17 ⇨Esyn: Synopse Nr. 74"] },
      { number: 22, text: "Viele werden an jenem Tage zu mir sagen: Herr, Herr*! Haben wir nicht durch deinen Namen geweissagt* und durch deinen Namen Dämonen ausgetrieben und durch deinen Namen viele Wunderwerke* getan?", footnotes: ["℘ Kap. 25,11", "℘ Jer 27,15", "o. Machttaten; griech. dynamis"] },
      { number: 23, text: "Und dann werde ich ihnen bekennen: Ich habe euch niemals gekannt*. Weicht von mir, ihr Übeltäter*!", footnotes: ["℘ Kap. 25,12; Ps 101,4", "℘ Kap. 25,41; Ps 6,9; 119,115; Lk 13,25.27"] },
      { number: 24, text: "Jeder nun, der diese meine Worte hört und sie tut*, den werde ich mit einem klugen Mann vergleichen*, der sein Haus auf den Felsen baute;", heading: "Gleichnis vom Haus auf Felsen und Sand — Wirkung der Predigt", footnotes: ["℘ Lk 8,21; Joh 13,17; Jak 1,22 ⇨Esyn: Synopse Nr. 75", "mit mehreren alten Handschr.: der ist mit einem klugen Mann zu vergleichen; o. wird mit einem klugen Mann verglichen werden"] },
      { number: 25, text: "und der Platzregen fiel herab, und die Ströme kamen, und die Winde wehten und stürmten gegen jenes Haus; und es fiel nicht, denn es war auf den Felsen gegründet*.", footnotes: ["℘ Spr 10,25; 12,7"] },
      { number: 26, text: "Und jeder, der diese meine Worte hört und sie nicht tut, der wird mit einem törichten Mann zu vergleichen sein*, der sein Haus auf den Sand baute;", footnotes: ["o. wird mit einem törichten Mann verglichen werden"] },
      { number: 27, text: "und der Platzregen fiel herab, und die Ströme kamen, und die Winde wehten und stießen an jenes Haus; und es fiel, und sein Fall war groß*.", footnotes: ["℘ Jes 28,17; Hes 13,11"] },
      { number: 28, text: "Und es geschah, als Jesus diese Worte vollendet hatte*, da erstaunten die Volksmengen sehr über seine Lehre*;", footnotes: ["℘ Kap. 11,1; 13,53; 19,1; 26,1", "℘ Kap. 13,54; 19,25; 22,33; Mk 6,2; Lk 4,32; Apg 13,12 ⇨Esyn: Synopse Nr. 76"] },
      { number: 29, text: "denn er lehrte sie wie einer, der Vollmacht hat, und nicht wie ihre Schriftgelehrten*.", footnotes: ["℘ Mk 1,22; Lk 24,19; Joh 7,46"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Als er aber von dem Berg herabgestiegen war, folgten ihm große Volksmengen. *", heading: "Heilung eines Aussätzigen", footnotes: ["℘ Mk 1,40-45; Lk 5,12-16", "℘ ⇨Esyn: Synopse Nr. 84"] },
      { number: 2, text: "Und siehe, ein Aussätziger* kam heran und warf sich vor ihm nieder und sprach: Herr, wenn du willst, kannst du mich reinigen.", footnotes: ["»Aussatz« umfasste in biblischer Zeit mehrere Hautkrankheiten, z. T. auch die damals noch unheilbare Lepra. Der Aussätzige galt bei den Juden als kultisch unrein."] },
      { number: 3, text: "Und er streckte die Hand aus, rührte ihn an und sprach: Ich will. Sei gereinigt! Und sogleich wurde sein Aussatz gereinigt." },
      { number: 4, text: "Und Jesus spricht zu ihm: Siehe, sage es niemandem*, sondern geh hin, zeige dich dem Priester, und bring die Gabe dar, die Mose angeordnet hat, ihnen zum Zeugnis*!", footnotes: ["℘ Kap. 9,30; 12,16; 16,20; Mk 1,34", "℘ 3Mo 14,1-20; Lk 17,14"] },
      { number: 5, text: "*Als er aber nach Kapernaum hineinkam, trat ein Hauptmann zu ihm, der ihn bat *", heading: "Heilung des Dieners eines Hauptmanns", footnotes: ["℘ Lk 7,1-10; vgl. Joh 4,43-54", "℘ ⇨Esyn: Synopse Nr. 85"] },
      { number: 6, text: "und sprach: Herr, mein Diener liegt zu Hause gelähmt und wird schrecklich gequält." },
      { number: 7, text: "Und Jesus spricht zu ihm: Ich will kommen und ihn heilen." },
      { number: 8, text: "Der Hauptmann aber antwortete und sprach: Herr, ich bin nicht würdig, dass du unter mein Dach trittst; aber sprich nur ein Wort, und mein Diener wird gesund werden*.", footnotes: ["℘ Ps 107,20"] },
      { number: 9, text: "Denn auch ich bin ein Mensch unter Befehlsgewalt* und habe Soldaten unter mir; und ich sage zu diesem: Geh hin!, und er geht; und zu einem anderen: Komm!, und er kommt; und zu meinem Knecht*: Tu dies!, und er tut es.", footnotes: ["o. Macht, Vollmacht", "w. Sklaven"] },
      { number: 10, text: "Als aber Jesus es hörte, wunderte er sich* und sprach zu denen, die nachfolgten: Wahrlich, ich sage euch, bei keinem in Israel habe ich so großen Glauben gefunden*.", footnotes: ["℘ Mk 6,6", "℘ Kap. 15,28"] },
      { number: 11, text: "Ich sage euch aber, dass viele von Osten und Westen kommen und mit Abraham und Isaak und Jakob zu Tisch liegen werden in dem Reich* der Himmel*,", footnotes: ["o. der Königsherrschaft", "℘ Jes 49,12; Lk 13,29"] },
      { number: 12, text: "aber die Söhne des Reiches* werden hinausgeworfen werden in die äußere Finsternis*; da wird das Weinen und das Zähneknirschen sein*.", footnotes: ["o. der Königsherrschaft", "℘ 2Petr 2,17", "℘ Kap. 13,42.50; 22,13; 24,51; 25,30; Lk 13,28"] },
      { number: 13, text: "Und Jesus sprach zu dem Hauptmann: Geh hin, dir geschehe, wie du geglaubt hast*! Und der Diener wurde gesund in jener Stunde*.", footnotes: ["℘ Kap. 9,29; 2Chr 20,20; Mk 9,23", "℘ Kap. 9,22; 15,28"] },
      { number: 14, text: "*Und als Jesus in das Haus des Petrus gekommen war, sah er dessen Schwiegermutter* fieberkrank daniederliegen.", heading: "Heilung der Schwiegermutter des Petrus und anderer Kranker", footnotes: ["℘ Mk 1,29-34; Lk 4,38-41", "℘ 1Kor 9,5 ⇨Esyn: Synopse Nr. 87"] },
      { number: 15, text: "Und er rührte ihre Hand an, und das Fieber verließ sie; und sie stand auf und diente ihm." },
      { number: 16, text: "Als es aber Abend geworden war, brachten sie viele Besessene zu ihm; und er trieb die Geister aus mit <seinem> Wort, und er heilte alle Leidenden*,", footnotes: ["℘ Kap. 4,23.24; 17,18; Lk 4,35 ⇨Esyn: Synopse Nr. 88"] },
      { number: 17, text: "damit erfüllt würde, was durch den Propheten Jesaja geredet ist, der spricht: »Er selbst nahm unsere Schwachheiten und trug unsere Krankheiten*.«", footnotes: ["℘ Jes 53,4"] },
      { number: 18, text: "*Als aber Jesus eine Volksmenge* um sich sah, befahl er, an das jenseitige Ufer wegzufahren*.", heading: "Rechte Nachfolge", footnotes: ["℘ Lk 9,57-62", "mit anderen Handschr.: eine große Volksmenge", "℘ Mk 4,35; Lk 8,22 ⇨Esyn: Synopse Nr. 89"] },
      { number: 19, text: "Und ein Schriftgelehrter kam heran und sprach zu ihm: Lehrer, ich will dir nachfolgen, wohin du auch gehst." },
      { number: 20, text: "Und Jesus spricht zu ihm: Die Füchse haben Höhlen und die Vögel des Himmels Nester, aber der Sohn des Menschen hat nicht, wo er das Haupt hinlege*.", footnotes: ["℘ 2Kor 8,9"] },
      { number: 21, text: "Ein anderer aber von seinen Jüngern sprach zu ihm: Herr, erlaube mir, vorher hinzugehen und meinen Vater zu begraben." },
      { number: 22, text: "Jesus aber spricht zu ihm: Folge mir nach*, und lass die Toten ihre Toten begraben!", footnotes: ["℘ Kap. 4,19"] },
      { number: 23, text: "*Und als er in das Boot gestiegen war, folgten ihm seine Jünger. *", heading: "Stillung des Sturmes", footnotes: ["℘ Mk 4,35-41; Lk 8,22-25", "℘ ⇨Esyn: Synopse Nr. 90"] },
      { number: 24, text: "Und siehe, es erhob sich ein heftiger Sturm* auf dem See, so dass das Boot von den Wellen bedeckt wurde*; er aber schlief.", footnotes: ["w. ein großes Beben", "℘ Kap. 14,24; Ps 107,25"] },
      { number: 25, text: "Und sie traten hinzu, weckten ihn auf und sprachen: Herr, rette <uns>, wir kommen um*!", footnotes: ["℘ Kap. 14,30; Ps 50,15"] },
      { number: 26, text: "Und er spricht zu ihnen: Was seid ihr furchtsam, Kleingläubige*? Dann stand er auf und bedrohte die Winde und den See; und es entstand eine große Stille*.", footnotes: ["℘ Kap. 6,30", "℘ Kap. 14,32; Ps 65,8; Ps 107,29"] },
      { number: 27, text: "Die Menschen aber wunderten sich und sagten: Was für einer ist dieser, dass auch die Winde und der See ihm gehorchen*?", footnotes: ["℘ Ps 93,4"] },
      { number: 28, text: "*Und als er an das jenseitige Ufer gekommen war, in das Land der Gadarener, begegneten ihm zwei Besessene, die aus den Grüften hervorkamen. <Sie waren> sehr bösartig, so dass niemand auf jenem Weg vorbeigehen konnte. *", heading: "Heilung zweier Besessener", footnotes: ["℘ Mk 5,1-20; Lk 8,26-39", "℘ ⇨Esyn: Synopse Nr. 91"] },
      { number: 29, text: "Und siehe, sie schrien* und sagten: Was haben wir mit dir zu schaffen*, Sohn Gottes? Bist du hierher gekommen, uns vor der Zeit zu quälen*?", footnotes: ["℘ Mk 1,23; Apg 8,7", "℘ 1Kö 17,18; Joh 2,4", "℘ Mk 1,24; Lk 4,34"] },
      { number: 30, text: "Es weidete aber fern von ihnen eine Herde von vielen Schweinen." },
      { number: 31, text: "Die Dämonen aber baten ihn und sprachen: Wenn du uns austreibst, so sende uns in die Herde Schweine!" },
      { number: 32, text: "Und er sprach zu ihnen: Geht hin! Sie aber fuhren aus und fuhren in die Schweine. Und siehe, die ganze Herde stürzte sich den Abhang hinab in den See, und sie kamen um in dem Gewässer." },
      { number: 33, text: "Die Hüter aber flohen und gingen in die Stadt und verkündeten alles und das von den Besessenen." },
      { number: 34, text: "Und siehe, die ganze Stadt ging hinaus, Jesus entgegen, und als sie ihn sahen, baten sie, dass er aus ihrem Gebiet weggehen möchte*.", footnotes: ["℘ Hi 21,14"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Und er stieg in ein Boot, setzte über und kam in seine eigene Stadt*.", heading: "Heilung eines Gelähmten", footnotes: ["℘ Mk 2,1-12; Lk 5,17-26", "d. i. Kapernaum; vgl. Kap. 4,13\n℘ Kap. 4,13 ⇨Esyn: Synopse Nr. 92"] },
      { number: 2, text: "Und siehe, sie brachten einen Gelähmten zu ihm, der auf einem Bett lag; und als Jesus ihren Glauben* sah, sprach er zu dem Gelähmten: Sei guten Mutes, Kind, deine Sünden sind vergeben*.", footnotes: ["℘ V. 22.29", "w. werden vergeben (Zeitform Gegenwart)\n℘ Lk 7,48 ⇨Esyn: Synopse Nr. 99"] },
      { number: 3, text: "Und siehe, einige von den Schriftgelehrten sprachen bei sich selbst: Dieser lästert*.", footnotes: ["℘ Kap. 26,65"] },
      { number: 4, text: "Und als Jesus ihre Gedanken sah*, sprach er: Warum denkt ihr Arges in euren Herzen?", footnotes: ["℘ Kap. 12,25; 22,18; Joh 2,24.25"] },
      { number: 5, text: "Denn was ist leichter zu sagen: Deine Sünden sind vergeben*, oder zu sagen: Steh auf und geh umher?", footnotes: ["w. werden vergeben (Zeitform Gegenwart)"] },
      { number: 6, text: "Damit ihr aber wisst, dass der Sohn des Menschen Vollmacht hat, auf der Erde Sünden zu vergeben . . . Dann sagt er zu dem Gelähmten: Steh auf, nimm dein Bett auf, und geh in dein Haus*!", footnotes: ["℘ Joh 5,8"] },
      { number: 7, text: "Und er stand auf und ging in sein Haus." },
      { number: 8, text: "Als aber die Volksmengen es sahen, fürchteten sie sich und verherrlichten Gott, der solche Vollmacht den Menschen gegeben hat*.", footnotes: ["℘ Kap. 15,31; 21,14.15; Jes 29,23; Mk 7,37"] },
      { number: 9, text: "*Und als Jesus von dort weiterging, sah er einen Menschen mit Namen Matthäus* am Zollhaus sitzen, und er spricht zu ihm: Folge mir nach! Und er stand auf und folgte ihm nach*.", heading: "Berufung des Matthäus", footnotes: ["℘ Mk 2,13-17; Lk 5,27-32", "℘ Kap. 10,3", "℘ Kap. 4,19-22 ⇨Esyn: Synopse Nr. 93"] },
      { number: 10, text: "Und es geschah, als er in dem Haus zu Tisch lag, und siehe, da kamen viele Zöllner und Sünder und lagen zu Tisch mit Jesus und seinen Jüngern." },
      { number: 11, text: "Und als die Pharisäer es sahen, sprachen sie zu seinen Jüngern: Warum isst euer Lehrer mit den Zöllnern und Sündern*?", footnotes: ["℘ Kap. 11,19; Lk 15,2"] },
      { number: 12, text: "Als aber er es hörte, sprach er: Nicht die Starken brauchen einen Arzt, sondern die Kranken." },
      { number: 13, text: "Geht aber hin und lernt, was das ist: »Ich will Barmherzigkeit und nicht Schlachtopfer*.« Denn ich bin nicht gekommen, Gerechte zu rufen, sondern Sünder*.", footnotes: ["℘ Kap. 12,7; 23,23; Hos 6,6", "℘ Kap. 18,11; 1Tim 1,15"] },
      { number: 14, text: "*Dann kommen die Jünger des Johannes* zu ihm und sagen: Warum fasten wir und die Pharisäer oft, deine Jünger aber fasten nicht*?", heading: "Die Frage nach dem Fasten", footnotes: ["℘ Mk 2,18-22; Lk 5,33-39", "℘ Joh 1,35", "℘ Lk 18,12 ⇨Esyn: Synopse Nr. 94"] },
      { number: 15, text: "Und Jesus sprach zu ihnen: Können etwa die Hochzeitsgäste* trauern, solange der Bräutigam bei ihnen ist*? Es werden aber Tage kommen, da der Bräutigam von ihnen weggenommen sein wird, und dann werden sie fasten*.", footnotes: ["w. Söhne des Brautgemachs; d. h. der dem Bräutigam am nächsten stehende unentbehrliche Teil der Hochzeitsgäste", "℘ Joh 3,29", "℘ Kap. 17,23"] },
      { number: 16, text: "Niemand aber setzt einen Flicken von neuem Tuch auf ein altes Gewand; denn das Eingesetzte reißt von dem Gewand ab, und der Riss wird schlimmer." },
      { number: 17, text: "Auch füllt man nicht neuen Wein in alte Schläuche; sonst zerreißen die Schläuche, und der Wein wird verschüttet, und die Schläuche verderben; sondern man füllt neuen Wein in neue Schläuche, und beide bleiben zusammen erhalten." },
      { number: 18, text: "*Während er dies zu ihnen redete, siehe, da kam ein Vorsteher herein und warf sich vor ihm nieder und sprach: Meine Tochter ist eben jetzt verschieden; aber komm und lege deine Hand auf sie, so wird sie leben. *", heading: "Heilung der blutflüssigen Frau — Auferweckung der Tochter des Jaïrus", footnotes: ["℘ Mk 5,21-43; Lk 8,40-56", "℘ ⇨Esyn: Synopse Nr. 95"] },
      { number: 19, text: "Und Jesus stand auf und folgte ihm, und seine Jünger. —" },
      { number: 20, text: "Und siehe, eine Frau, die zwölf Jahre blutflüssig* war, trat von hinten heran und rührte die Quaste* seines Gewandes an;", footnotes: ["℘ 3Mo 15,25", "zur Bedeutung der Quasten siehe 4Mo 15,37—40\n℘ Kap. 23,5"] },
      { number: 21, text: "denn sie sprach bei sich selbst: Wenn ich nur sein Gewand anrühre, so werde ich geheilt* werden*.", footnotes: ["w. gerettet", "℘ Kap. 14,36"] },
      { number: 22, text: "Jesus aber wandte sich um, und als er sie sah, sprach er: Sei guten Mutes*, Tochter! Dein Glaube hat dich geheilt*. Und die Frau war geheilt* von jener Stunde an*. —", footnotes: ["℘ V. 2", "w. gerettet\n℘ V. 29; Mk 10,52", "w. gerettet", "℘ Kap. 8,13"] },
      { number: 23, text: "Und als Jesus in das Haus des Vorstehers kam und die Pfeifer und die lärmende Volksmenge sah," },
      { number: 24, text: "sprach er: Geht fort! Denn das Mädchen ist nicht gestorben, sondern es schläft*. Und sie lachten ihn aus.", footnotes: ["℘ Joh 11,11"] },
      { number: 25, text: "Als aber die Volksmenge hinausgetrieben war, ging er hinein und ergriff sie bei der Hand; und das Mädchen stand auf*.", footnotes: ["℘ 1Kö 17,22; 2Kö 4,35; 13,21; Lk 7,15; Joh 11,44; Apg 9,40; 20,12"] },
      { number: 26, text: "Und die Kunde hiervon ging hinaus in jene ganze Gegend*.", footnotes: ["w. in jenes ganze Land\n℘ Lk 7,17"] },
      { number: 27, text: "*Und als Jesus von dort weiterging, folgten ihm zwei Blinde, die schrien und sprachen: Erbarme dich unser, Sohn Davids*!", heading: "Heilung zweier Blinder", footnotes: ["℘ vgl. Kap. 20,29-34; Mk 8,22-26; 10,46-52; Lk 18,35-43", "℘ Kap. 1,1; 12,23; 15,22; 21,9; 22,42 ⇨Esyn: Synopse Nr. 96"] },
      { number: 28, text: "Als er aber in das Haus gekommen war, traten die Blinden zu ihm; und Jesus spricht zu ihnen: Glaubt ihr, dass ich dies tun kann? Sie sagen zu ihm: Ja, Herr*.", footnotes: ["℘ Mk 9,24; Apg 14,9"] },
      { number: 29, text: "Dann rührte er ihre Augen an* und sprach: Euch geschehe nach eurem Glauben*!", footnotes: ["℘ Joh 9,6", "℘ V. 22; Kap. 8,13"] },
      { number: 30, text: "Und ihre Augen wurden geöffnet*; und Jesus bedrohte sie und sprach: Seht zu, niemand erfahre es*!", footnotes: ["℘ Ps 146,8; Jes 35,5", "℘ Kap. 8,4; Mk 1,44"] },
      { number: 31, text: "Sie aber gingen hinaus und machten ihn bekannt in jener ganzen Gegend*.", footnotes: ["w. in jenem ganzen Land\n℘ Mk 1,45"] },
      { number: 32, text: "Als sie aber weggingen, siehe, da brachten sie einen stummen Menschen zu ihm, der besessen war*.", heading: "Heilung eines stummen Besessenen", footnotes: ["℘ Kap. 12,22; Lk 11,14 ⇨Esyn: Synopse Nr. 97"] },
      { number: 33, text: "Und als der Dämon ausgetrieben war, redete der Stumme*. Und die Volksmengen wunderten sich und sprachen: Niemals wurde so etwas in Israel gesehen*.", footnotes: ["℘ Jes 35,6", "℘ Kap. 12,23"] },
      { number: 34, text: "Die Pharisäer aber sagten: Er treibt die Dämonen aus durch den Obersten der Dämonen*.", footnotes: ["℘ Kap. 12,24; Mk 3,22; Lk 11,15; Joh 7,20"] },
      { number: 35, text: "Und Jesus zog umher durch alle Städte und Dörfer und lehrte in ihren Synagogen* und predigte das Evangelium des Reiches* und heilte jede Krankheit und jedes Gebrechen*.", heading: "Aussendung der zwölf Apostel", footnotes: ["℘ Mk 6,6; Lk 8,1", "o. der Königsherrschaft", "℘ Kap. 4,23 ⇨Esyn: Synopse Nr. 98"] },
      { number: 36, text: "Als er aber die Volksmengen sah, wurde er innerlich bewegt über sie*, weil sie erschöpft und verschmachtet* waren wie Schafe, die keinen Hirten haben*.", footnotes: ["℘ Kap. 14,14; 15,32; 20,34; Mk 1,41; Lk 7,13", "w. niedergeworfen, am Boden liegend", "℘ 4Mo 27,17; 1Kö 22,17; Hes 34,5; Mk 6,34"] },
      { number: 37, text: "Dann spricht er zu seinen Jüngern: Die Ernte zwar ist groß, die Arbeiter aber sind wenige*.", footnotes: ["℘ Lk 10,2"] },
      { number: 38, text: "Bittet nun den Herrn der Ernte, dass er Arbeiter aussende in seine Ernte*!", footnotes: ["℘ Lk 10,2"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und als er seine zwölf Jünger herangerufen hatte, gab er ihnen Vollmacht über unreine Geister, sie auszutreiben und jede Krankheit und jedes Gebrechen zu heilen*.", footnotes: ["℘ Mk 3,13-19; Lk 6,12-16; (Apg 1,13)", "℘ Mk 6,7; Lk 9,1 ⇨Esyn: Synopse Nr. 99"] },
      { number: 2, text: "Die Namen der zwölf Apostel* aber sind diese: der erste Simon, der Petrus genannt wird*, und Andreas, sein Bruder*, und Jakobus, der <Sohn> des Zebedäus, und Johannes, sein Bruder*,", footnotes: ["d. h. Gesandte, o. Boten", "℘ Kap. 16,17.18; Joh 1,42; 1Petr 1,1", "℘ Kap. 4,18", "℘ Kap. 4,21; 20,20"] },
      { number: 3, text: "Philippus* und Bartholomäus, Thomas* und Matthäus, der Zöllner*, Jakobus, der <Sohn> des Alphäus, und Thaddäus,", footnotes: ["℘ Joh 1,43", "℘ Joh 11,16", "℘ Kap. 9,9"] },
      { number: 4, text: "Simon, der Kananäer*, und Judas, der Iskariot*, der ihn auch überlieferte*.", footnotes: ["wahrscheinlich von hebr. kana (d. h. eifern); s. auch Anm. zu Lk 6,15", "Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente vielleicht zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Joh 14,22).", "℘ Kap. 26,14"] },
      { number: 5, text: "*Diese zwölf sandte Jesus aus und befahl ihnen und sprach: Geht nicht auf einen Weg der Nationen, und geht nicht in eine Stadt der Samariter*;", footnotes: ["℘ Mk 6,7-13; Lk 9,1-6; vgl. Lk 10,1-12", "℘ 2Kö 17,24; Esr 4,10"] },
      { number: 6, text: "geht aber vielmehr zu den verlorenen Schafen des Hauses Israel*!", footnotes: ["℘ Kap. 15,24; Apg 11,19; 13,46"] },
      { number: 7, text: "Wenn ihr aber hingeht, predigt und sprecht: Das Reich* der Himmel ist nahe gekommen*.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 3,2"] },
      { number: 8, text: "Heilt Kranke, weckt Tote auf, reinigt Aussätzige*, treibt Dämonen aus*! Umsonst habt ihr empfangen, umsonst gebt*!", footnotes: ["»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten, z. T. auch die damals noch unheilbare Lepra. Der Aussätzige galt bei den Juden als kultisch unrein.", "℘ Mk 16,17.18", "℘ 3Jo 7"] },
      { number: 9, text: "Verschafft euch nicht Gold noch Silber noch Kupfer in eure Gürtel*,", footnotes: ["℘ Lk 22,35"] },
      { number: 10, text: "keine Tasche auf den Weg, noch zwei Unterkleider noch Sandalen noch einen Stab! Denn der Arbeiter ist seiner Nahrung wert*.", footnotes: ["℘ 4Mo 18,31; 1Kor 9,4.14; 1Tim 5,18"] },
      { number: 11, text: "Wenn ihr aber in eine Stadt oder in ein Dorf einkehrt, so forscht, wer darin würdig ist; und dort bleibt, bis ihr weggeht*!", footnotes: ["℘ Apg 16,15"] },
      { number: 12, text: "Wenn ihr aber in das Haus eintretet, so grüßt es!" },
      { number: 13, text: "Und wenn nun das Haus würdig ist, so komme euer Friede darauf; wenn es aber nicht würdig ist, so wende sich euer Friede zu euch zurück." },
      { number: 14, text: "Und wenn jemand euch nicht aufnehmen noch eure Worte hören wird — geht hinaus aus jenem Haus oder jener Stadt und schüttelt den Staub von euren Füßen*!", footnotes: ["℘ Apg 13,51"] },
      { number: 15, text: "Wahrlich, ich sage euch, es wird dem Land von Sodom und Gomorra* erträglicher ergehen am Tag des Gerichts als jener Stadt*.", footnotes: ["℘ 1Mo 19,24.25", "℘ Kap. 11,22.24; Kla 4,6; Lk 10,14; 20,47; Offb 20,12"] },
      { number: 16, text: "*Siehe, ich sende euch wie Schafe mitten unter Wölfe*; so seid nun klug wie die Schlangen und einfältig wie die Tauben.", heading: "Ermutigung zum Bekenntnis in Verfolgungen", footnotes: ["℘ V. 16-22: vgl. Kap. 24,9-13; Mk 13,9-13; Lk 12,11-12; 21,12-17; V. 26-33: vgl. Lk 12,2-9", "℘ Lk 10,3"] },
      { number: 17, text: "Hütet euch aber vor den Menschen! Denn sie werden euch an Gerichte* überliefern* und in ihren Synagogen euch geißeln*;", footnotes: ["w. Synedrien", "℘ Apg 5,40; 6,12", "Die Strafe des Geißelns wurde nach dem Gesetz (vgl. 5Mo 25,3) vollzogen, und zwar in den Synagogen; s. auch Anm. zu Kap. 4,23 und zu 2Kor 11,24.\n℘ Kap. 23,34; Apg 22,19; 2Kor 11,24 ⇨Esyn: Synopse Nr. 100"] },
      { number: 18, text: "und auch vor Statthalter und Könige werdet ihr geführt werden um meinetwillen, ihnen und den Nationen zum Zeugnis*.", footnotes: ["℘ Kap. 24,14; Joh 15,27; Apg 23,33; 27,24"] },
      { number: 19, text: "Wenn sie euch aber überliefern, so seid nicht besorgt, wie oder was ihr reden sollt; denn es wird euch in jener Stunde gegeben werden, was ihr reden sollt*.", footnotes: ["℘ 2Mo 4,12"] },
      { number: 20, text: "Denn nicht ihr seid die Redenden, sondern der Geist eures Vaters, der in euch redet." },
      { number: 21, text: "Es wird aber der Bruder den Bruder zum Tode überliefern und der Vater das Kind; und Kinder werden sich erheben gegen die Eltern und sie zu Tode bringen*.", footnotes: ["℘ V. 35.36; Mi 7,6"] },
      { number: 22, text: "Und ihr werdet von allen gehasst werden um meines Namens willen*. Wer aber ausharrt bis ans Ende, der wird gerettet werden.", footnotes: ["℘ Lk 6,22; Joh 15,21"] },
      { number: 23, text: "Wenn sie euch aber verfolgen in dieser Stadt, so flieht in die andere*! Denn wahrlich, ich sage euch, ihr werdet mit den Städten Israels nicht zu Ende sein, bis der Sohn des Menschen gekommen sein wird.", footnotes: ["℘ Kap. 23,34; Apg 14,6"] },
      { number: 24, text: "Ein Jünger ist nicht über dem Lehrer und ein Sklave nicht über seinem Herrn*.", footnotes: ["℘ Lk 6,40; Joh 13,16"] },
      { number: 25, text: "Es ist dem Jünger genug, dass er werde* wie sein Lehrer und der Sklave wie sein Herr. Wenn sie den Hausherrn Beelzebul* genannt haben, wie viel mehr seine Hausgenossen!", footnotes: ["o. ist", "im Judentum der Name für den Obersten der Dämonen; die Bedeutung des Namens ist umstritten\n℘ Kap. 12,24; Joh 8,48"] },
      { number: 26, text: "Fürchtet euch nun nicht vor ihnen! Denn es ist nichts verdeckt, was nicht aufgedeckt, und nichts verborgen, was nicht erkannt werden wird*.", footnotes: ["℘ Mk 4,22 ⇨Esyn: Synopse Nr. 101"] },
      { number: 27, text: "Was ich euch sage in der Finsternis, redet im Licht, und was ihr ins Ohr <geflüstert> hört, ruft aus auf den Dächern!" },
      { number: 28, text: "Und fürchtet euch nicht vor denen, die den Leib töten, die Seele aber nicht zu töten vermögen*; fürchtet aber vielmehr den, der sowohl Seele als <auch> Leib zu verderben vermag* in der Hölle*!", footnotes: ["℘ Jer 1,8; 1Petr 3,14; Offb 2,10", "℘ Jak 4,12", "℘ Kap. 5,29.30"] },
      { number: 29, text: "Werden nicht zwei Sperlinge für eine Münze* verkauft? Und nicht einer von ihnen wird auf die Erde fallen ohne euren Vater.", footnotes: ["w. ein Assarion; s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 30, text: "Bei euch aber sind selbst die Haare des Hauptes alle gezählt." },
      { number: 31, text: "Fürchtet euch nun nicht! Ihr seid wertvoller als viele Sperlinge*.", footnotes: ["℘ Kap. 6,26"] },
      { number: 32, text: "Jeder nun, der sich vor den Menschen zu mir bekennen wird, zu dem werde auch ich mich bekennen vor meinem Vater, der in den Himmeln ist*.", footnotes: ["℘ Röm 10,9; Offb 3,5"] },
      { number: 33, text: "Wer aber mich vor den Menschen verleugnen wird*, den werde auch ich verleugnen vor meinem Vater, der in den Himmeln ist*.", footnotes: ["℘ 2Petr 2,1; 1Jo 2,23; Jud 4", "℘ Mk 8,38; Lk 9,26; 2Tim 2,12"] },
      { number: 34, text: "Meint nicht, dass ich gekommen sei, Frieden auf die Erde zu bringen; ich bin nicht gekommen, Frieden zu bringen, sondern das Schwert. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 102"] },
      { number: 35, text: "Denn ich bin gekommen, den Menschen zu entzweien mit seinem Vater und die Tochter mit ihrer Mutter und die Schwiegertochter mit ihrer Schwiegermutter;" },
      { number: 36, text: "und des Menschen Feinde <werden> seine eigenen Hausgenossen <sein>*.", footnotes: ["℘ V. 21; Lk 12,51-53"] },
      { number: 37, text: "Wer Vater oder Mutter mehr liebt als mich, ist meiner nicht würdig; und wer Sohn oder Tochter mehr liebt als mich, ist meiner nicht würdig*;", footnotes: ["℘ 5Mo 13,7-11; 33,9 ⇨Esyn: Synopse Nr. 103"] },
      { number: 38, text: "und wer nicht sein Kreuz aufnimmt und mir nachfolgt, ist meiner nicht würdig*.", footnotes: ["℘ Kap. 16,24; Mk 8,34"] },
      { number: 39, text: "Wer sein Leben* findet, wird es verlieren, und wer sein Leben* verliert um meinetwillen, wird es finden*.", footnotes: ["o. seine Seele", "o. seine Seele", "℘ Kap. 16,25; Lk 9,24; 14,26.27; Joh 12,25; 2Tim 2,11"] },
      { number: 40, text: "*Wer euch aufnimmt, nimmt mich auf*, und wer mich aufnimmt, nimmt den auf, der mich gesandt hat*.", heading: "Belohnung für jeden Dienst um Jesu willen", footnotes: ["℘ vgl. Kap. 25,34-40", "℘ Kap. 18,5; Mk 9,37", "℘ Lk 9,48; Joh 12,44; Gal 4,14 ⇨Esyn: Synopse Nr. 104"] },
      { number: 41, text: "Wer einen Propheten aufnimmt in eines Propheten Namen*, wird eines Propheten Lohn empfangen; und wer einen Gerechten aufnimmt in eines Gerechten Namen*, wird eines Gerechten Lohn empfangen*.", footnotes: ["d. h. im Blick auf seine Eigenschaft als Prophet (bzw. als Gerechter o. als Jünger)", "d. h. im Blick auf seine Eigenschaft als Prophet (bzw. als Gerechter o. als Jünger)", "℘ 2Kö 4,8.17"] },
      { number: 42, text: "Und wenn jemand einem dieser Geringen nur einen Becher kalten Wassers zu trinken gibt in eines Jüngers Namen*, wahrlich, ich sage euch, er wird seinen Lohn gewiss nicht verlieren*.", footnotes: ["d. h. im Blick auf seine Eigenschaft als Prophet (bzw. als Gerechter o. als Jünger)", "℘ Mk 9,41; Hebr 6,10"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und es geschah, als Jesus seine Befehle an seine zwölf Jünger vollendet hatte*, ging er von dort weg, um in ihren Städten zu lehren und zu predigen.", footnotes: ["℘ Kap. 7,28 ⇨Esyn: Synopse Nr. 105"] },
      { number: 2, text: "*Als aber Johannes im Gefängnis* die Werke des Christus hörte, sandte er durch seine Jünger", heading: "Die Frage des Täufers — Jesu Antwort und Zeugnis über ihn", footnotes: ["℘ Lk 7,18-35", "℘ Kap. 4,12; Lk 3,20 ⇨Esyn: Synopse Nr. 106"] },
      { number: 3, text: "und ließ ihm sagen: Bist du der Kommende, oder sollen wir auf einen anderen warten*?", footnotes: ["℘ Joh 10,24"] },
      { number: 4, text: "Und Jesus antwortete und sprach zu ihnen: Geht hin und verkündet Johannes, was ihr hört und seht:" },
      { number: 5, text: "Blinde werden sehend, und Lahme gehen, Aussätzige* werden gereinigt, und Taube hören, und Tote werden auferweckt*, und Armen wird gute Botschaft verkündigt*.", footnotes: ["»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten; s. Anm. zu Kap. 8,2", "℘ Jes 35,5.6; Joh 5,36", "℘ Jes 29,18.19; 61,1"] },
      { number: 6, text: "Und glückselig ist, wer sich nicht an mir ärgern* wird*!", footnotes: ["»ärgern«, w. zur Sünde verleiten. Sich an Jesus ärgern, d. h. Anstoß nehmen und sich von ihm abwenden.", "℘ Kap. 13,57; 26,31; Jes 8,14.15; 1Petr 2,8"] },
      { number: 7, text: "Als die aber hingingen, fing Jesus an, zu den Volksmengen zu reden über Johannes: Was seid ihr in die Wüste hinausgegangen anzuschauen*? Ein Rohr, vom Wind hin und her bewegt?", footnotes: ["℘ Kap. 3,1.5 ⇨Esyn: Synopse Nr. 107"] },
      { number: 8, text: "Oder was seid ihr hinausgegangen zu sehen? Einen Menschen, mit weichen <Kleidern> bekleidet? Siehe, die weiche <Kleider> tragen, sind in den Häusern der Könige." },
      { number: 9, text: "Oder was seid ihr hinausgegangen zu sehen? Einen Propheten? Ja, sage ich euch, und mehr als einen Propheten*.", footnotes: ["℘ Kap. 14,5; 21,26; Lk 1,76"] },
      { number: 10, text: "Dieser ist es, von dem geschrieben steht: »Siehe, ich sende meinen Boten vor deinem Angesicht her, der deinen Weg vor dir bereiten wird*.«", footnotes: ["℘ Mal 3,1; Mk 1,2; Joh 3,28"] },
      { number: 11, text: "Wahrlich, ich sage euch, unter den von Frauen Geborenen ist kein Größerer aufgestanden als Johannes der Täufer*; der Kleinste aber im Reich* der Himmel ist größer als er.", footnotes: ["℘ Lk 1,15", "o. in der Königsherrschaft"] },
      { number: 12, text: "Aber von den Tagen Johannes des Täufers an bis jetzt wird dem Reich* der Himmel Gewalt angetan, und Gewalttuende reißen es an sich*.", footnotes: ["o. der Königsherrschaft", "℘ Lk 16,16"] },
      { number: 13, text: "Denn alle Propheten und das Gesetz haben geweissagt bis auf Johannes*.", footnotes: ["o. bis auf Johannes hin\n℘ Joh 1,6-8; 5,33"] },
      { number: 14, text: "Und wenn ihr es annehmen wollt: Er ist Elia, der kommen soll*.", footnotes: ["℘ Kap. 14,10; 17,13; Mal 3,23; Mk 9,13; Lk 1,17; Joh 1,21"] },
      { number: 15, text: "Wer Ohren hat, der höre*!", footnotes: ["℘ Kap. 13,9.43; Mk 4,9.23; Lk 8,8; Offb 2,7"] },
      { number: 16, text: "Mit wem aber soll ich dieses Geschlecht vergleichen? Es ist Kindern gleich, die auf den Märkten sitzen und den anderen zurufen" },
      { number: 17, text: "und sagen: Wir haben euch gepfiffen, und ihr habt nicht getanzt; wir haben Klagelieder gesungen, und ihr habt nicht gewehklagt." },
      { number: 18, text: "Denn Johannes ist gekommen, der weder aß noch trank*, und sie sagen: Er hat einen Dämon*.", footnotes: ["℘ Kap. 3,4; Lk 1,15", "℘ Kap. 21,25"] },
      { number: 19, text: "Der Sohn des Menschen ist gekommen, der isst und trinkt, und sie sagen: Siehe, ein Fresser und Weinsäufer, ein Freund der Zöllner und Sünder* — und die Weisheit ist gerechtfertigt worden aus ihren Werken*.", footnotes: ["℘ Kap. 9,11; 12,32", "Andere gute Handschr. lesen: von ihren Kindern"] },
      { number: 20, text: "*Dann fing er an, die Städte zu schelten, in denen seine meisten Wunderwerke* geschehen waren, weil sie nicht Buße getan hatten: *", heading: "Weheruf über unbußfertige Städte — Jesus als Retter der Unmündigen und Bedrückten", footnotes: ["℘ Lk 10,13-16", "o. Machttaten; griech. dynamis", "℘ ⇨Esyn: Synopse Nr. 108"] },
      { number: 21, text: "Wehe dir, Chorazin! Wehe dir, Betsaida! Denn wenn in Tyrus und Sidon* die Wunderwerke* geschehen wären, die unter euch geschehen sind, längst hätten sie in Sack und Asche Buße getan*.", footnotes: ["℘ Hes 28,1.19.21-23", "o. Machttaten; griech. dynamis", "℘ Jon 3,6"] },
      { number: 22, text: "Doch ich sage euch: Tyrus und Sidon wird es erträglicher ergehen am Tag des Gerichts als euch*.", footnotes: ["℘ Kap. 10,15; Lk 12,48"] },
      { number: 23, text: "Und du, Kapernaum, <meinst du,> du werdest etwa bis zum Himmel erhöht werden*? Bis zum Hades* wirst du hinabgestoßen werden*; denn wenn in Sodom* die Wunderwerke* geschehen wären, die in dir geschehen sind, es wäre geblieben bis auf den heutigen Tag.", footnotes: ["℘ Kap. 4,13", "d. i. das Totenreich", "mit anderen Handschr.: wirst du hinabsteigen\n℘ Jes 14,15", "℘ 1Mo 18,20", "o. Machttaten; griech. dynamis"] },
      { number: 24, text: "Doch ich sage euch: Dem Sodomer Land wird es erträglicher ergehen am Tag des Gerichts als dir*.", footnotes: ["℘ V. 22"] },
      { number: 25, text: "*Zu jener Zeit begann* Jesus und sprach: Ich preise dich, Vater, Herr des Himmels und der Erde*, dass du dies vor Weisen und Verständigen verborgen* und es Unmündigen offenbart hast*.", footnotes: ["℘ Lk 10,21.22", "w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "℘ Apg 17,24", "℘ Hi 37,24", "℘ 1Kor 1,26-29 ⇨Esyn: Synopse Nr. 109"] },
      { number: 26, text: "Ja, Vater, denn so war es wohlgefällig* vor dir.", footnotes: ["w. denn so ist Wohlgefallen geworden"] },
      { number: 27, text: "Alles ist mir übergeben worden von meinem Vater*; und niemand erkennt den Sohn als nur der Vater, noch erkennt jemand den Vater als nur der Sohn*, und der, dem der Sohn <ihn> offenbaren will*.", footnotes: ["℘ Kap. 28,18; Joh 3,35; 17,2; Hebr 2,8", "℘ Joh 7,29", "℘ Joh 1,18; 1Jo 2,13.14"] },
      { number: 28, text: "Kommt her zu mir, alle ihr Mühseligen und Beladenen*! Und ich werde euch Ruhe geben.", footnotes: ["℘ Ps 38,5 ⇨Esyn: Synopse Nr. 110"] },
      { number: 29, text: "Nehmt auf euch mein Joch, und lernt von mir*! Denn ich bin sanftmütig* und von Herzen demütig*, und »ihr werdet Ruhe finden für eure Seelen*«;", footnotes: ["℘ Eph 4,20", "℘ Ps 45,5", "℘ Sach 9,9; 2Kor 10,1", "℘ Jer 6,16"] },
      { number: 30, text: "denn mein Joch ist sanft, und meine Last ist leicht*.", footnotes: ["℘ 1Jo 5,3"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Zu jener Zeit ging Jesus am Sabbat* durch die Saaten; es hungerte aber seine Jünger, und sie fingen an, Ähren abzupflücken und zu essen*.", heading: "Die Sabbatfrage", footnotes: ["℘ Mk 2,23-3,6; Lk 6,1-11", "w. an den Sabbaten", "℘ 5Mo 23,26 ⇨Esyn: Synopse Nr. 111"] },
      { number: 2, text: "Als aber die Pharisäer es sahen, sprachen sie zu ihm: Siehe, deine Jünger tun, was am Sabbat zu tun nicht erlaubt ist*.", footnotes: ["℘ Joh 5,10"] },
      { number: 3, text: "Er aber sprach zu ihnen: Habt ihr nicht gelesen, was David tat, als ihn und die bei ihm waren hungerte*?", footnotes: ["℘ 1Sam 21,4-7"] },
      { number: 4, text: "Wie er in das Haus Gottes ging und die Schaubrote aß, die er nicht essen durfte, noch die bei ihm waren, sondern allein die Priester*?", footnotes: ["℘ 3Mo 24,9"] },
      { number: 5, text: "Oder habt ihr nicht in dem Gesetz gelesen, dass am Sabbat* die Priester in dem Tempel den Sabbat entheiligen und <doch> schuldlos sind*?", footnotes: ["w. an den Sabbaten", "℘ 4Mo 28,9; Joh 7,23"] },
      { number: 6, text: "Ich sage euch aber: Größeres als der Tempel ist hier*.", footnotes: ["℘ V. 41.42"] },
      { number: 7, text: "Wenn ihr aber erkannt hättet, was das heißt: »Ich will Barmherzigkeit und nicht Schlachtopfer«*, so würdet ihr die Schuldlosen nicht verurteilt haben.", footnotes: ["℘ Kap. 9,13; Hos 6,6"] },
      { number: 8, text: "Denn der Sohn des Menschen ist Herr des Sabbats*.", footnotes: ["℘ 2Mo 16,29"] },
      { number: 9, text: "Und als er von dort weiterging, kam er in ihre Synagoge. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 112"] },
      { number: 10, text: "Und siehe, da war ein Mensch, der eine verdorrte Hand hatte. Und sie fragten ihn und sprachen: Ist es erlaubt, am Sabbat* zu heilen*?, damit sie ihn anklagen könnten*.", footnotes: ["w. an den Sabbaten", "℘ Lk 13,14", "℘ Joh 8,6"] },
      { number: 11, text: "Er aber sprach zu ihnen: Welcher Mensch wird unter euch sein, der ein Schaf hat und, wenn dieses am Sabbat* in eine Grube fällt, es nicht ergreift und herauszieht*?", footnotes: ["w. an den Sabbaten", "w. aufrichtet\n℘ Lk 14,5"] },
      { number: 12, text: "Wie viel wertvoller ist nun ein Mensch als ein Schaf*! Also ist es erlaubt, am Sabbat* Gutes zu tun.", footnotes: ["℘ Kap. 6,26", "w. an den Sabbaten"] },
      { number: 13, text: "Dann spricht er zu dem Menschen: Strecke deine Hand aus! Und er streckte sie aus, und sie wurde wiederhergestellt, gesund wie die andere." },
      { number: 14, text: "Die Pharisäer aber gingen hinaus und hielten Rat gegen ihn, wie sie ihn umbringen könnten*.", footnotes: ["℘ Kap. 21,46; 26,4; Joh 5,16"] },
      { number: 15, text: "*Als aber Jesus es erkannte, ging er von dort weg*; und es folgten ihm große Volksmengen, und er heilte sie alle*.", heading: "Heilungen und die Erfüllung des Prophetenwortes", footnotes: ["℘ Mk 3,7-12; Lk 6,17-19", "℘ Kap. 4,12", "℘ Kap. 4,24 ⇨Esyn: Synopse Nr. 113"] },
      { number: 16, text: "Und er bedrohte sie, dass sie ihn nicht offenbar machten*,", footnotes: ["℘ Kap. 8,4"] },
      { number: 17, text: "damit erfüllt würde, was durch den Propheten Jesaja geredet ist, der spricht*:", footnotes: ["℘ Jes 42,1-4"] },
      { number: 18, text: "»Siehe, mein Knecht, den ich erwählt habe, mein Geliebter, an dem meine Seele Wohlgefallen gefunden hat*; ich werde meinen Geist auf ihn legen*, und er wird den Nationen Recht* verkünden.", footnotes: ["℘ Kap. 3,17", "℘ Jes 11,2; 61,1", "o. Gericht"] },
      { number: 19, text: "Er wird nicht streiten* noch schreien, noch wird jemand seine Stimme auf den Straßen hören;", footnotes: ["℘ 2Tim 2,24"] },
      { number: 20, text: "ein geknicktes Rohr wird er nicht zerbrechen, und einen glimmenden Docht wird er nicht auslöschen*, bis er das Recht* hinausführe zum Sieg*;", footnotes: ["℘ Jes 57,15", "o. Gericht", "℘ Jes 11,4.5"] },
      { number: 21, text: "und auf seinen Namen werden die Nationen hoffen*.«", footnotes: ["℘ Jes 11,10; Röm 15,12"] },
      { number: 22, text: "*Dann wurde ein Besessener zu ihm gebracht, blind und stumm*; und er heilte ihn, so dass der Stumme redete und sah*.", heading: "Heilung eines Besessenen — Lästerung des Geistes", footnotes: ["℘ Mk 3,20-30; Lk 11,14-23; 12,10", "℘ Kap. 9,32", "℘ Jes 35,5.6 ⇨Esyn: Synopse Nr. 117"] },
      { number: 23, text: "Und es erstaunten die ganzen Volksmengen und sagten: Dieser ist doch nicht etwa der Sohn Davids*?", footnotes: ["℘ Kap. 9,27.33"] },
      { number: 24, text: "Die Pharisäer aber sagten, als sie es hörten: Dieser treibt die Dämonen nicht anders aus als durch den Beelzebul*, den Obersten der Dämonen*.", footnotes: ["im Judentum der Name für den Obersten der Dämonen; die Bedeutung des Namens ist umstritten", "℘ Kap. 9,34; 10,25"] },
      { number: 25, text: "Da er aber ihre Gedanken wusste*, sprach er zu ihnen: Jedes Reich*, das mit sich selbst entzweit ist, wird verwüstet; und jede Stadt oder jedes Haus, die mit sich selbst entzweit sind, werden nicht bestehen.", footnotes: ["℘ Kap. 9,4", "o. Jede Königsherrschaft, die"] },
      { number: 26, text: "Und wenn der Satan den Satan austreibt, so ist er mit sich selbst entzweit. Wie wird denn sein Reich* bestehen?", footnotes: ["o. seine Königsherrschaft"] },
      { number: 27, text: "Und wenn ich durch Beelzebul die Dämonen austreibe, durch wen treiben eure Söhne sie aus? Darum werden sie eure Richter sein." },
      { number: 28, text: "Wenn ich aber durch den Geist Gottes die Dämonen austreibe, so ist also das Reich* Gottes zu euch gekommen.", footnotes: ["o. die Königsherrschaft"] },
      { number: 29, text: "Oder wie kann jemand in das Haus des Starken eindringen und seinen Hausrat rauben, wenn er nicht vorher den Starken bindet? Und dann wird er sein Haus berauben." },
      { number: 30, text: "Wer nicht mit mir ist, ist gegen mich, und wer nicht mit mir sammelt, zerstreut*.", footnotes: ["℘ Mk 9,40"] },
      { number: 31, text: "Deshalb sage ich euch: Jede Sünde und Lästerung wird den Menschen vergeben werden; aber die Lästerung des Geistes wird nicht vergeben werden*.", footnotes: ["℘ Hebr 10,26 ⇨Esyn: Synopse Nr. 118"] },
      { number: 32, text: "Und wenn jemand ein Wort reden wird gegen den Sohn des Menschen*, dem wird vergeben werden; wenn aber jemand gegen den Heiligen Geist reden wird*, dem wird nicht vergeben werden, weder in diesem Zeitalter* noch in dem zukünftigen. —", footnotes: ["℘ Kap. 11,19", "℘ Hebr 10,29", "griech. Äon"] },
      { number: 33, text: "Entweder macht den Baum gut, dann ist seine Frucht* gut, oder macht den Baum faul, dann ist seine Frucht* faul; denn an der Frucht wird der Baum erkannt*.", footnotes: ["w. und seine Frucht ist", "w. und seine Frucht ist", "℘ Kap. 7,17.20"] },
      { number: 34, text: "Otternbrut*! Wie könnt ihr Gutes reden, da ihr böse seid? Denn aus der Fülle des Herzens redet der Mund*.", footnotes: ["℘ Kap. 3,7", "℘ Kap. 15,18"] },
      { number: 35, text: "Der gute Mensch bringt aus dem guten Schatz Gutes hervor, und der böse Mensch bringt aus dem bösen Schatz Böses hervor*.", footnotes: ["℘ Jes 32,6-8; Lk 6,45"] },
      { number: 36, text: "Ich sage euch aber, dass die Menschen von jedem unnützen Wort, das sie reden werden*, Rechenschaft geben müssen am Tag des Gerichts*;", footnotes: ["℘ Jud 15", "℘ Pred 12,14; Apg 17,31; Röm 14,12; Jak 5,12"] },
      { number: 37, text: "denn aus deinen Worten wirst du gerechtfertigt werden, und aus deinen Worten wirst du verdammt werden*.", footnotes: ["℘ Lk 19,22"] },
      { number: 38, text: "*Dann antworteten ihm einige der Schriftgelehrten und Pharisäer und sprachen: Lehrer, wir möchten ein Zeichen von dir sehen*!", heading: "Das Zeichen Jonas", footnotes: ["℘ Lk 11,29-32", "℘ Kap. 16,1; Mk 8,11; 1Kor 1,22 ⇨Esyn: Synopse Nr. 119"] },
      { number: 39, text: "Er aber antwortete und sprach zu ihnen: Ein böses und ehebrecherisches Geschlecht begehrt ein Zeichen, und kein Zeichen wird ihm gegeben werden als nur das Zeichen Jonas, des Propheten*.", footnotes: ["℘ Kap. 16,4; Mk 8,12 ⇨Esyn: Synopse Nr. 296"] },
      { number: 40, text: "Denn wie Jona drei Tage und drei Nächte in dem Bauch des großen Fisches war*, so wird der Sohn des Menschen drei Tage und drei Nächte im Herzen der Erde sein*.", footnotes: ["℘ Jon 2,1", "℘ Kap. 16,21; 1Kor 15,4"] },
      { number: 41, text: "Männer von Ninive werden aufstehen im Gericht mit diesem Geschlecht und werden es verdammen*, denn sie taten Buße auf die Predigt Jonas*; und siehe, mehr als Jona ist hier*.", footnotes: ["℘ Röm 2,27", "℘ Jon 3,5", "℘ V. 6; Joh 3,31"] },
      { number: 42, text: "Eine Königin des Südens wird auftreten im Gericht mit diesem Geschlecht und wird es verdammen, denn sie kam von den Enden der Erde, um die Weisheit Salomos zu hören*; und siehe, mehr als Salomo ist hier*.", footnotes: ["℘ 1Kö 10,1", "℘ V. 6; Joh 3,31"] },
      { number: 43, text: "*Wenn aber der unreine Geist von dem Menschen ausgefahren ist, so durchwandert er dürre Orte, sucht Ruhe und findet sie nicht. *", heading: "Von der Rückkehr unreiner Geister", footnotes: ["℘ Lk 11,24-26", "℘ ⇨Esyn: Synopse Nr. 120"] },
      { number: 44, text: "Dann spricht er: Ich will in mein Haus zurückkehren, aus dem ich herausgegangen bin; und wenn er kommt, findet er es leer, gekehrt und geschmückt." },
      { number: 45, text: "Dann geht er hin und nimmt sieben andere Geister mit sich, böser als er selbst, und sie gehen hinein und wohnen dort; und das Ende jenes Menschen wird schlimmer als der Anfang*. So wird es auch diesem bösen Geschlecht ergehen.", footnotes: ["℘ 2Petr 2,20"] },
      { number: 46, text: "*Als er aber noch zu den Volksmengen redete, siehe, da standen seine Mutter und seine Brüder* draußen und suchten ihn zu sprechen.", heading: "Die wahren Verwandten Jesu", footnotes: ["℘ Mk 3,31-35; Lk 8,19-21", "℘ Kap. 13,55; Mk 6,3; Joh 2,12; Apg 1,14 ⇨Esyn: Synopse Nr. 121"] },
      { number: 47, text: "*Und es sprach einer zu ihm: Siehe, deine Mutter und deine Brüder stehen draußen und suchen dich zu sprechen.*", footnotes: ["Dieser Vers ist in einigen alten Handschr. nicht enthalten.", "Dieser Vers ist in einigen alten Handschr. nicht enthalten."] },
      { number: 48, text: "Er aber antwortete und sprach zu dem, der es ihm sagte: Wer ist meine Mutter, und wer sind meine Brüder?" },
      { number: 49, text: "Und er streckte seine Hand aus über seine Jünger und sprach: Siehe da, meine Mutter und meine Brüder!" },
      { number: 50, text: "Denn wer den Willen meines Vaters tut, der in den Himmeln ist*, der ist mein Bruder und meine Schwester und meine Mutter.", footnotes: ["℘ Kap. 7,21"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "*An jenem Tag aber ging Jesus aus dem Haus hinaus und setzte sich an den See. *", heading: "Gleichnis vom Sämann", footnotes: ["℘ Mk 4,1-20; Lk 8,4-15", "℘ ⇨Esyn: Synopse Nr. 122"] },
      { number: 2, text: "Und es versammelten sich große Volksmengen um ihn, so dass er in ein Boot stieg und sich setzte; und die ganze Volksmenge stand am Ufer*.", footnotes: ["℘ Mk 3,9; Lk 5,3"] },
      { number: 3, text: "Und er redete vieles in Gleichnissen zu ihnen* und sprach: Siehe, der Sämann ging hinaus zu säen;", footnotes: ["℘ V. 34"] },
      { number: 4, text: "und indem er säte, fiel einiges an den Weg, und die Vögel kamen und fraßen es auf." },
      { number: 5, text: "Anderes aber fiel auf das Steinige, wo es nicht viel Erde hatte; und sogleich ging es auf, weil es nicht tiefe Erde hatte." },
      { number: 6, text: "Als aber die Sonne aufging, wurde es verbrannt, und weil es keine Wurzel hatte, verdorrte es." },
      { number: 7, text: "Anderes aber fiel unter die Dornen; und die Dornen sprossen auf und erstickten es." },
      { number: 8, text: "Anderes aber fiel auf die gute Erde und gab Frucht: das eine hundert-, das andere sechzig-, das andere dreißig<fach>." },
      { number: 9, text: "Wer Ohren hat, der höre*!", footnotes: ["℘ Kap. 11,15"] },
      { number: 10, text: "Und die Jünger traten hinzu und sprachen zu ihm: Warum redest du in Gleichnissen zu ihnen? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 123"] },
      { number: 11, text: "Er aber antwortete und sprach zu ihnen: Weil euch gegeben ist, die Geheimnisse des Reiches* der Himmel zu wissen, jenen aber ist es nicht gegeben*;", footnotes: ["o. der Königsherrschaft", "℘ Mk 4,33.34"] },
      { number: 12, text: "denn wer hat, dem wird gegeben und überreichlich gewährt werden; wer aber nicht hat, von dem wird selbst, was er hat, genommen werden*.", footnotes: ["℘ Kap. 25,29; Mk 4,25"] },
      { number: 13, text: "Darum rede ich in Gleichnissen zu ihnen, weil sie sehend nicht sehen und hörend nicht hören noch verstehen*;", footnotes: ["℘ 5Mo 29,3; Jer 5,21; Mk 8,18"] },
      { number: 14, text: "und es wird an ihnen die Weissagung Jesajas erfüllt, die lautet: »Mit Gehör werdet ihr hören und doch nicht verstehen, und sehend werdet ihr sehen und doch nicht wahrnehmen;" },
      { number: 15, text: "denn das Herz dieses Volkes ist dick geworden, und mit den Ohren haben sie schwer gehört, und ihre Augen haben sie geschlossen, damit sie nicht etwa mit den Augen sehen* und mit den Ohren hören und mit dem Herzen verstehen und sich bekehren und ich sie heile*.«", footnotes: ["℘ Joh 9,39; Röm 11,8", "℘ Jes 6,9.10; Joh 12,39.40; Apg 28,25-27"] },
      { number: 16, text: "Glückselig aber eure Augen, dass sie sehen, und eure Ohren, dass sie hören;" },
      { number: 17, text: "denn wahrlich, ich sage euch: Viele Propheten und Gerechte haben begehrt zu sehen, was ihr anschaut, und haben es nicht gesehen; und zu hören, was ihr hört, und haben es nicht gehört*.", footnotes: ["℘ Lk 10,23.24; Hebr 11,39; 1Petr 1,10"] },
      { number: 18, text: "Hört nun ihr das Gleichnis vom Sämann: *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 124"] },
      { number: 19, text: "Sooft jemand das Wort vom Reich* hört und nicht versteht, kommt der Böse und reißt weg, was in sein Herz gesät war; dieser ist es, bei dem an den Weg gesät ist.", footnotes: ["o. von der Königsherrschaft"] },
      { number: 20, text: "Bei dem* aber auf das Steinige gesät ist, dieser ist es, der das Wort hört und es sogleich mit Freuden aufnimmt*;", footnotes: ["w. Wer", "℘ Hebr 6,5"] },
      { number: 21, text: "er hat aber keine Wurzel in sich, sondern ist nur <ein Mensch> des Augenblicks; und wenn Bedrängnis entsteht oder Verfolgung um des Wortes willen*, nimmt er sogleich Anstoß*.", footnotes: ["℘ 2Tim 3,12", "o. lässt er sich sogleich zur Sünde verleiten; o. ärgert er sich sogleich\n℘ Joh 16,1"] },
      { number: 22, text: "Bei dem* aber unter die Dornen gesät ist, dieser ist es, der das Wort hört, und die Sorge der Zeit* und der Betrug des Reichtums* ersticken das Wort, und er bringt keine Frucht.", footnotes: ["w. Wer", "o. dieses Zeitalters; o. dieser Welt; griech. Äon\n℘ Kap. 6,25-34; 2Tim 2,4", "℘ Kap. 6,19; 19,23; Mk 10,23; 1Tim 6,9"] },
      { number: 23, text: "Bei dem* aber auf die gute Erde gesät ist, dieser ist es, der das Wort hört und versteht, der wirklich Frucht bringt; und der eine trägt hundert-, der andere sechzig-, der andere dreißig<fach>.", footnotes: ["w. Wer"] },
      { number: 24, text: "*Ein anderes Gleichnis legte er ihnen vor und sprach: Mit dem Reich* der Himmel ist es wie* mit einem Menschen, der guten Samen auf seinen Acker säte*.", heading: "Gleichnis vom Unkraut des Ackers", footnotes: ["℘ vgl. V. 36-43", "o. der/die Königsherrschaft", "w. Das Reich der Himmel ist verglichen worden (o. zu vergleichen)", "℘ Mk 4,26 ⇨Esyn: Synopse Nr. 127"] },
      { number: 25, text: "Während aber die Menschen schliefen, kam sein Feind und säte Unkraut* mitten unter den Weizen und ging weg.", footnotes: ["w. Lolch; d. i. ein dem Weizen ähnliches Unkraut; so auch V. 26 usw."] },
      { number: 26, text: "Als aber die Saat aufsprosste und Frucht brachte, da erschien auch das Unkraut." },
      { number: 27, text: "Es kamen aber die Knechte* des Hausherrn hinzu und sprachen zu ihm: Herr, hast du nicht guten Samen auf deinen Acker gesät? Woher hat er denn Unkraut?", footnotes: ["w. Sklaven; so auch V. 28"] },
      { number: 28, text: "Er aber sprach zu ihnen: Ein feindseliger Mensch hat dies getan. Die Knechte aber sagen zu ihm: Willst du denn, dass wir hingehen und es zusammenlesen?" },
      { number: 29, text: "Er aber spricht: Nein, damit ihr nicht etwa beim Zusammenlesen des Unkrauts gleichzeitig mit ihm den Weizen ausreißt*.", footnotes: ["℘ Jes 65,8"] },
      { number: 30, text: "Lasst beides zusammen wachsen bis zur Ernte, und zur Zeit der Ernte werde ich den Schnittern sagen: Lest zuerst das Unkraut zusammen, und bindet es in Bündel, um es zu verbrennen; den Weizen aber sammelt in meine Scheune*!", footnotes: ["℘ Kap. 3,12; Offb 14,15"] },
      { number: 31, text: "*Ein anderes Gleichnis legte er ihnen vor und sprach: Das Reich* der Himmel gleicht einem Senfkorn, das ein Mensch nahm und auf seinen Acker säte; *", heading: "Gleichnis vom Senfkorn und Sauerteig", footnotes: ["℘ Mk 4,30-34; Lk 13,18-21", "o. der/die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 128"] },
      { number: 32, text: "es ist zwar kleiner als alle <Arten von> Samen, wenn es aber gewachsen ist, so ist es größer als die Kräuter und wird ein Baum, so dass die Vögel des Himmels kommen und in seinen Zweigen nisten*.", footnotes: ["℘ Hes 17,23; 31,6"] },
      { number: 33, text: "Ein anderes Gleichnis redete er zu ihnen: Das Reich* der Himmel gleicht einem Sauerteig, den eine Frau nahm und unter drei Maß* Mehl mengte, bis es ganz durchsäuert war*.", footnotes: ["o. der/die Königsherrschaft", "w. Saton; ein Hohlmaß von etwa 13 l", "℘ 1Kor 5,6; Gal 5,9 ⇨Esyn: Synopse Nr. 129"] },
      { number: 34, text: "Dies alles redete Jesus in Gleichnissen zu den Volksmengen, und ohne Gleichnis redete er nichts zu ihnen*,", footnotes: ["℘ V. 3 ⇨Esyn: Synopse Nr. 130"] },
      { number: 35, text: "damit erfüllt würde, was durch den Propheten geredet ist, der spricht: »Ich werde meinen Mund öffnen in Gleichnissen; ich werde aussprechen, was von Grundlegung der Welt an verborgen war*.«", footnotes: ["℘ Ps 78,2"] },
      { number: 36, text: "*Dann entließ er die Volksmengen und kam in das Haus; und seine Jünger traten zu ihm und sprachen: Deute uns das Gleichnis vom Unkraut des Ackers*!", heading: "Deutung des Gleichnisses vom Unkraut des Ackers", footnotes: ["℘ vgl. V. 24-30", "℘ Kap. 15,15 ⇨Esyn: Synopse Nr. 131"] },
      { number: 37, text: "Er aber antwortete und sprach: Der den guten Samen sät, ist der Sohn des Menschen," },
      { number: 38, text: "der Acker aber ist die Welt; der gute Same aber sind die Söhne des Reiches*, das Unkraut aber sind die Söhne des Bösen*;", footnotes: ["o. der/die Königsherrschaft", "℘ Joh 8,44; 1Jo 3,10"] },
      { number: 39, text: "der Feind aber, der es gesät hat, ist der Teufel; die Ernte aber ist die Vollendung des Zeitalters*, die Schnitter aber sind Engel.", footnotes: ["griech. Äon\n℘ Kap. 24,3; Joe 4,13; Offb 14,16"] },
      { number: 40, text: "Wie nun das Unkraut zusammengelesen und im Feuer verbrannt wird, so wird es in der Vollendung des Zeitalters* sein.", footnotes: ["griech. Äon"] },
      { number: 41, text: "Der Sohn des Menschen wird seine Engel aussenden*, und sie werden aus seinem Reich* alle Ärgernisse* zusammenlesen und die, die Gesetzloses tun*,", footnotes: ["℘ Kap. 24,31; Mk 13,27", "o. der/die Königsherrschaft", "o. alle Anlässe zur Sünde; o. alles Anstößige; vielleicht ist gemeint: alle, die andere zur Sünde verführt haben", "w. die, die die Gesetzlosigkeit tun\n℘ Zef 1,3"] },
      { number: 42, text: "und sie werden sie in den Feuerofen werfen*; da wird das Weinen und das Zähneknirschen sein*.", footnotes: ["℘ Kap. 25,41", "℘ V. 50; Kap. 8,12"] },
      { number: 43, text: "Dann werden die Gerechten leuchten wie die Sonne in dem Reich* ihres Vaters*. Wer Ohren hat, der höre*!", footnotes: ["o. der/die Königsherrschaft", "℘ Spr 4,18; Dan 12,3", "℘ Kap. 11,15"] },
      { number: 44, text: "Das Reich* der Himmel gleicht einem im Acker verborgenen Schatz, den ein Mensch fand und verbarg; und vor Freude darüber geht er hin und verkauft alles, was er hat, und kauft jenen Acker. *", heading: "Gleichnisse vom Schatz im Acker, von der kostbaren Perle und vom Fischnetz", footnotes: ["o. der/die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 132"] },
      { number: 45, text: "Wiederum gleicht das Reich* der Himmel einem Kaufmann, der schöne Perlen suchte;", footnotes: ["o. der/die Königsherrschaft"] },
      { number: 46, text: "als er aber eine sehr kostbare Perle gefunden hatte, ging er hin und verkaufte alles, was er hatte, und kaufte sie." },
      { number: 47, text: "Wiederum gleicht das Reich* der Himmel einem Netz, das ins Meer geworfen wurde und <Fische> von jeder Art zusammenbrachte, *", footnotes: ["o. der/die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 133"] },
      { number: 48, text: "das sie dann, als es voll war, ans Ufer heraufzogen; und sie setzten sich nieder und lasen die guten in Gefäße zusammen, aber die faulen warfen sie hinaus." },
      { number: 49, text: "So wird es in der Vollendung des Zeitalters* sein: Die Engel werden hinausgehen und die Bösen aus der Mitte der Gerechten aussondern*", footnotes: ["griech. Äon", "℘ Kap. 3,12; 25,32"] },
      { number: 50, text: "und sie in den Feuerofen werfen*; da wird das Weinen und das Zähneknirschen sein*.", footnotes: ["℘ Lk 16,24", "℘ V. 42"] },
      { number: 51, text: "Habt ihr dies alles verstanden? Sie sagen zu ihm: Ja. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 134"] },
      { number: 52, text: "Er aber sprach zu ihnen: Darum ist jeder Schriftgelehrte, der ein Jünger des Reichs* der Himmel geworden ist, gleich einem Hausherrn, der aus seinem Schatz Neues und Altes hervorbringt*.", footnotes: ["o. von der Königsherrschaft", "℘ Kap. 24,45; 2Tim 2,15"] },
      { number: 53, text: "*Und es geschah, als Jesus diese Gleichnisse vollendet hatte*, ging er von dort weg.", heading: "Unglauben in Nazareth", footnotes: ["℘ Mk 6,1-6; vgl. Lk 4,16-30", "℘ Kap. 7,28 ⇨Esyn: Synopse Nr. 139"] },
      { number: 54, text: "Und er kam in seine Vaterstadt und lehrte sie in ihrer Synagoge, so dass sie sehr erstaunten* und sprachen: Woher hat er diese Weisheit und die Wunderwerke*?", footnotes: ["℘ Kap. 7,28", "o. Machttaten; griech. dynamis\n℘ Joh 7,15"] },
      { number: 55, text: "Ist er nicht der Sohn des Zimmermanns*? Heißt nicht seine Mutter Maria und seine Brüder* Jakobus* und Josef und Simon und Judas*?", footnotes: ["℘ Joh 6,42", "℘ Kap. 12,46", "℘ Apg 12,17", "℘ Jud 1"] },
      { number: 56, text: "Und seine Schwestern, sind sie nicht alle bei uns? Woher hat er nun dies alles?" },
      { number: 57, text: "Und sie ärgerten* sich an ihm*. Jesus aber sprach zu ihnen: Ein Prophet ist nicht ohne Ehre, außer in seiner Vaterstadt und in seinem Haus*.", footnotes: ["Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, zur Sünde verleitet werden.", "℘ Kap. 11,6", "℘ Jer 11,21; Joh 4,44"] },
      { number: 58, text: "Und er tat dort nicht viele Wunderwerke* wegen ihres Unglaubens.", footnotes: ["o. Machttaten; griech. dynamis"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Zu jener Zeit hörte Herodes*, der Vierfürst*, die Kunde von Jesus", heading: "Der Tod des Täufers", footnotes: ["℘ Mk 6,14-29; Lk 3,19.20; 9,7-9", "Herodes Antipas, Sohn Herodes' d. Gr., unter römischer Oberherrschaft Fürst von Galiläa und Peräa (4 v. Chr. bis 39 n. Chr.)", "griech. Tetrarch; ursprünglich Titel eines Fürsten, der über den vierten Teil eines Reiches regierte, später überhaupt für Fürsten geringerer Bedeutung verwendet\n℘ Lk 3,1; Apg 13,1 ⇨Esyn: Synopse Nr. 143"] },
      { number: 2, text: "und sprach zu seinen Dienern: Dieser ist Johannes der Täufer*; er ist von den Toten auferweckt worden, und darum wirken solche <Wunder>kräfte in ihm.", footnotes: ["℘ Kap. 16,14"] },
      { number: 3, text: "Denn Herodes hatte Johannes gegriffen, ihn gebunden und ins Gefängnis gesetzt* um der Herodias* willen, der Frau seines Bruders Philippus*.", footnotes: ["℘ Kap. 4,12", "Enkeltochter Herodes' d. Gr. und Stiefnichte ihrer beiden Ehegatten; ihr erster Gatte ist nicht mit dem Lk 3,1 genannten Vierfürsten Philippus identisch (vgl. erste Anm. zu V. 1).", "Herodes Philippus, Sohn Herodes' d. Gr. und Halbbruder des Herodes Antipas. Er hat nie ein Regierungsamt ausgeübt.\n℘ Joh 3,24 ⇨Esyn: Synopse Nr. 144"] },
      { number: 4, text: "Denn Johannes hatte ihm gesagt: Es ist dir nicht erlaubt, sie zu haben*.", footnotes: ["℘ Kap. 19,9; 3Mo 18,16"] },
      { number: 5, text: "Und als er ihn töten wollte, fürchtete er die Volksmenge, weil sie ihn für einen Propheten hielten*.", footnotes: ["℘ Kap. 11,9; Mk 11,32"] },
      { number: 6, text: "Als aber der Geburtstag des Herodes begangen wurde, tanzte die Tochter der Herodias vor ihnen*, und sie gefiel dem Herodes.", footnotes: ["w. in der Mitte"] },
      { number: 7, text: "Deshalb sagte er mit einem Eid zu, ihr zu geben, um was sie auch bitten würde." },
      { number: 8, text: "Sie aber, von ihrer Mutter angewiesen*, sagt: Gib mir hier auf einer Schüssel das Haupt Johannes' des Täufers!", footnotes: ["w. nach vorne geschoben\n℘ 2Chr 22,3"] },
      { number: 9, text: "Und der König wurde traurig; aber um der Eide und um derer willen, die mit zu Tisch lagen, befahl er, es zu geben*.", footnotes: ["℘ 4Mo 30,3"] },
      { number: 10, text: "Und er sandte hin und ließ den Johannes im Gefängnis enthaupten*.", footnotes: ["℘ Kap. 17,12.13"] },
      { number: 11, text: "Und sein Haupt wurde auf einer Schüssel gebracht und dem Mädchen gegeben, und sie brachte es ihrer Mutter." },
      { number: 12, text: "Und seine Jünger kamen herbei, hoben den Leib auf und begruben ihn*. Und sie kamen und verkündeten es Jesus.", footnotes: ["℘ Apg 8,2"] },
      { number: 13, text: "Und als Jesus es hörte, zog er sich von dort in einem Boot abseits an einen öden Ort zurück*.*Und als die Volksmengen es hörten, folgten sie ihm zu Fuß aus den Städten.", heading: "Speisung der Fünftausend", footnotes: ["℘ Kap. 4,12 ⇨Esyn: Synopse Nr. 146", "℘ Mk 6,30-44; Lk 9,10-17; Joh 6,1-14; vgl. Kap. 15,32-39; Mk 8,1-9"] },
      { number: 14, text: "Und als er ausstieg, sah er eine große Volksmenge, und er wurde innerlich bewegt über sie* und heilte ihre Kranken*.", footnotes: ["℘ Kap. 9,36", "℘ Kap. 4,24"] },
      { number: 15, text: "Als es aber Abend geworden war, traten seine Jünger zu ihm und sprachen: Der Ort ist öde, und die Zeit ist schon vergangen. Entlass die Volksmengen, dass sie hingehen in die Dörfer und sich Speise kaufen!" },
      { number: 16, text: "Jesus aber sprach zu ihnen: Sie haben nicht nötig wegzugehen. Gebt ihr ihnen zu essen!" },
      { number: 17, text: "Sie aber sagen zu ihm: Wir haben nichts hier als nur fünf Brote und zwei Fische*.", footnotes: ["℘ 4Mo 11,13.21.22; 2Kö 4,43"] },
      { number: 18, text: "Er aber sprach: Bringt sie mir her!" },
      { number: 19, text: "Und er befahl den Volksmengen, sich auf das Gras zu lagern, nahm die fünf Brote und die zwei Fische, blickte auf zum Himmel* und dankte*; und er brach die Brote und gab sie den Jüngern, die Jünger aber <gaben sie> den Volksmengen.", footnotes: ["℘ Joh 11,41", "℘ Kap. 26,26"] },
      { number: 20, text: "Und sie aßen alle und wurden gesättigt*. Und sie hoben auf, was an Brocken übrig blieb: zwölf Handkörbe voll*.", footnotes: ["℘ Ps 104,28", "℘ Kap. 16,9; 2Kö 4,44; Mk 8,19"] },
      { number: 21, text: "Die aber aßen, waren ungefähr fünftausend Männer, ohne Frauen und Kinder." },
      { number: 22, text: "*Und sogleich nötigte er die Jünger, in das Boot zu steigen und ihm an das jenseitige Ufer vorauszufahren, bis er die Volksmengen entlassen habe. *", heading: "Jesus geht auf dem See — Hilfe für den sinkenden Petrus", footnotes: ["℘ Mk 6,45-52; Joh 6,15-21", "℘ ⇨Esyn: Synopse Nr. 147"] },
      { number: 23, text: "Und als er die Volksmengen entlassen hatte, stieg er für sich allein auf den Berg, um zu beten*. Als es aber Abend geworden, war er dort allein.", footnotes: ["℘ Mk 1,35; Lk 5,16"] },
      { number: 24, text: "Das Boot aber war schon mitten auf dem See* und litt Not von den Wellen*, denn der Wind war <ihnen> entgegen.", footnotes: ["mit anderen alten Handschr.: viele Stadien vom Land entfernt", "℘ Kap. 8,24; Lk 8,23"] },
      { number: 25, text: "Aber in der vierten Nachtwache* kam er zu ihnen, indem er auf dem See einherging*.", footnotes: ["In neutestamentl. Zeit galt die griech.-röm. Einteilung der Nacht in vier Nachtwachen zu je 3 Stunden; die hier angegebene Zeit liegt also zwischen drei und sechs Uhr morgens.", "℘ Hi 9,8"] },
      { number: 26, text: "Und als die Jünger ihn auf dem See einhergehen sahen, wurden sie bestürzt und sprachen: Es ist ein Gespenst! Und sie schrien vor Furcht." },
      { number: 27, text: "Sogleich aber redete Jesus zu ihnen und sprach: Seid guten Mutes! Ich bin es. Fürchtet euch nicht!" },
      { number: 28, text: "Petrus aber antwortete ihm und sprach: Herr, wenn du es bist, so befiehl mir, auf dem Wasser zu dir zu kommen!" },
      { number: 29, text: "Er aber sprach: Komm! Und Petrus stieg aus dem Boot und ging auf dem Wasser und kam auf Jesus zu." },
      { number: 30, text: "Als er aber den starken Wind sah, fürchtete er sich; und als er anfing zu sinken, schrie er und sprach: Herr, rette mich*!", footnotes: ["℘ Kap. 8,25"] },
      { number: 31, text: "Sogleich aber streckte Jesus die Hand aus, ergriff ihn* und spricht zu ihm: Kleingläubiger*, warum zweifeltest du*?", footnotes: ["℘ Kla 3,57", "℘ Kap. 6,30", "℘ Jak 1,6"] },
      { number: 32, text: "Und als sie in das Boot gestiegen waren, legte sich der Wind*.", footnotes: ["℘ Kap. 8,26"] },
      { number: 33, text: "Die aber in dem Boot waren, warfen sich vor ihm nieder* und sprachen: Wahrhaftig, du bist Gottes Sohn*!", footnotes: ["℘ Joh 9,38", "℘ Kap. 3,17; 16,16; 27,54; Lk 1,35; Joh 1,34; Hebr 1,2"] },
      { number: 34, text: "*Und als sie hinübergefahren waren, kamen sie an Land in* Genezareth. *", heading: "Heilung vieler Kranker", footnotes: ["℘ Mk 6,53-56", "w. nach", "℘ ⇨Esyn: Synopse Nr. 148"] },
      { number: 35, text: "Und als die Männer jenes Ortes ihn erkannten, schickten sie <Boten> in jene ganze Umgegend und brachten alle Leidenden zu ihm*;", footnotes: ["℘ Kap. 4,23.24"] },
      { number: 36, text: "und sie baten ihn, dass sie nur die Quaste* seines Gewandes anrühren dürften; und alle, die ihn anrührten, wurden völlig geheilt*.", footnotes: ["zur Bedeutung der Quasten siehe 4Mo 15,37—40", "℘ Kap. 9,21"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Dann kommen Pharisäer und Schriftgelehrte von Jerusalem zu Jesus und sagen: *", heading: "Gottes Gebot steht höher als menschliche Überlieferung — Verunreinigung des Menschen", footnotes: ["℘ Mk 7,1-23", "℘ ⇨Esyn: Synopse Nr. 150"] },
      { number: 2, text: "Warum übertreten deine Jünger die Überlieferung* der Ältesten? Denn sie waschen ihre Hände nicht, wenn sie Brot essen*.", footnotes: ["Vorschriften, die über das Gesetz hinaus das Leben bis ins Einzelne regelten und einengten und mit denen sich besonders die Schriftgelehrten beschäftigten; die Pharisäer bemühten sich, die Überlieferungen genau zu halten.\n℘ Kol 2,8", "℘ Lk 11,38"] },
      { number: 3, text: "Er aber antwortete und sprach zu ihnen: Warum übertretet auch ihr das Gebot Gottes um eurer Überlieferung willen?" },
      { number: 4, text: "Denn Gott hat gesagt: »Ehre den Vater und die Mutter*!«, und: »Wer Vater oder Mutter flucht, soll des Todes sterben*.«", footnotes: ["℘ Kap. 19,19; 2Mo 20,12; 5Mo 5,16; Spr 23,22; Eph 6,2", "℘ 2Mo 21,17; 3Mo 20,9; Spr 20,20"] },
      { number: 5, text: "Ihr aber sagt: Wer zum Vater oder zur Mutter spricht: Eine Opfergabe <sei das>, was du von mir an Nutzen haben würdest," },
      { number: 6, text: "der braucht seinen Vater <oder seine Mutter> nicht zu ehren; und ihr habt <so> das Wort Gottes ungültig gemacht um eurer Überlieferung willen*.", footnotes: ["℘ Jer 8,8"] },
      { number: 7, text: "Heuchler*! Treffend hat Jesaja über euch geweissagt, indem er spricht:", footnotes: ["℘ Kap. 23,13"] },
      { number: 8, text: "»Dieses Volk ehrt mich mit den Lippen, aber ihr Herz ist weit entfernt von mir*.", footnotes: ["℘ Jes 58,2"] },
      { number: 9, text: "Vergeblich aber verehren sie mich, indem sie als Lehren Menschengebote lehren*.«", footnotes: ["℘ Jes 29,13; Kol 2,22"] },
      { number: 10, text: "Und er rief die Volksmenge herbei und sprach zu ihnen: Hört und versteht!" },
      { number: 11, text: "Nicht was in den Mund hineingeht, verunreinigt den Menschen*, sondern was aus dem Mund herausgeht, das verunreinigt den Menschen*.", footnotes: ["℘ Apg 10,15; Röm 14,14; 1Tim 4,4", "℘ V. 18; Eph 4,29; Jak 3,6"] },
      { number: 12, text: "Dann traten die Jünger hinzu und sprachen zu ihm: Weißt du, dass die Pharisäer sich ärgerten*, als sie das Wort hörten?", footnotes: ["o. Anstoß nahmen; s. auch Anm. zu Mt 11,6"] },
      { number: 13, text: "Er aber antwortete und sprach: Jede Pflanze, die mein himmlischer Vater nicht gepflanzt hat, wird ausgerissen werden*.", footnotes: ["℘ Apg 5,38"] },
      { number: 14, text: "Lasst sie! Sie sind blinde Leiter der Blinden*. Wenn aber ein Blinder einen Blinden leitet, so werden beide in eine Grube fallen*.", footnotes: ["℘ Kap. 23,16.24", "℘ Lk 6,39; Röm 2,19"] },
      { number: 15, text: "Petrus aber antwortete und sprach zu ihm: Deute uns dieses Gleichnis*!", footnotes: ["℘ Kap. 13,36"] },
      { number: 16, text: "Er aber sprach: Seid auch ihr noch unverständig*?", footnotes: ["℘ Kap. 16,9; Mk 8,17"] },
      { number: 17, text: "Begreift ihr nicht, dass alles, was in den Mund hineingeht, in den Bauch geht und in den Abort ausgeworfen wird?" },
      { number: 18, text: "Was aber aus dem Mund herausgeht, kommt aus dem Herzen hervor, und das verunreinigt den Menschen*.", footnotes: ["℘ V. 11; Kap. 12,34"] },
      { number: 19, text: "Denn aus dem Herzen kommen hervor böse Gedanken*: Mord*, Ehebruch*, Unzucht*, Diebstahl, falsche Zeugnisse, Lästerungen*;", footnotes: ["℘ 1Mo 6,5; Ps 58,3; Spr 6,14; Jak 1,14", "Im Griech. stehen die Wörter »Mord« bis »Diebstahl« in der Mehrzahl.", "℘ Kap. 5,28", "o. Hurerei", "℘ Röm 1,29-31; 13,13; 1Kor 6,9.10; Gal 5,19-21; Eph 5,3-5; Kol 3,5-9; 1Petr 4,3; Offb 21,8"] },
      { number: 20, text: "diese Dinge sind es, die den Menschen verunreinigen*, aber mit ungewaschenen Händen zu essen, verunreinigt den Menschen nicht.", footnotes: ["℘ Ps 106,39"] },
      { number: 21, text: "*Und Jesus ging von dort weg und zog sich in die Gegenden von Tyrus und Sidon zurück; *", heading: "Heilung der Tochter der kanaanäischen Frau", footnotes: ["℘ Mk 7,24-30", "℘ ⇨Esyn: Synopse Nr. 151"] },
      { number: 22, text: "und siehe, eine kanaanäische Frau, die aus jenem Gebiet herkam*, schrie und sprach: Erbarme dich meiner, Herr, Sohn Davids*! Meine Tochter ist schlimm besessen.", footnotes: ["℘ Mk 3,8", "℘ Kap. 9,27"] },
      { number: 23, text: "Er aber antwortete ihr nicht ein Wort. Und seine Jünger traten hinzu und baten ihn und sprachen: Entlass sie! Denn sie schreit hinter uns her." },
      { number: 24, text: "Er aber antwortete und sprach: Ich bin nur gesandt zu den verlorenen Schafen des Hauses Israel*.", footnotes: ["℘ Kap. 10,5.6; Apg 3,26"] },
      { number: 25, text: "Sie aber kam und warf sich vor ihm nieder und sprach: Herr, hilf mir!" },
      { number: 26, text: "Er antwortete und sprach: Es ist nicht schön, das Brot der Kinder zu nehmen und den Hunden hinzuwerfen." },
      { number: 27, text: "Sie aber sprach: Ja, Herr; doch es essen ja auch die Hunde von den Krumen, die von dem Tisch ihrer Herren fallen." },
      { number: 28, text: "Da antwortete Jesus und sprach zu ihr: Frau, dein Glaube ist groß*. Dir geschehe, wie du willst*! Und ihre Tochter war geheilt von jener Stunde an.", footnotes: ["℘ Kap. 8,10", "℘ Kap. 8,13"] },
      { number: 29, text: "*Und Jesus ging von dort weg und kam an den See von Galiläa; und als er auf den Berg gestiegen war, setzte er sich dort*.", heading: "Krankenheilungen — Speisung der Viertausend", footnotes: ["℘ Mk 8,1-9; vgl. Kap. 14,13-21; Mk 6,30-44; Lk 9,10-17; Joh 6,1-14", "℘ Kap. 5,1; Mk 7,31 ⇨Esyn: Synopse Nr. 152"] },
      { number: 30, text: "Und große Volksmengen kamen zu ihm, die Lahme, Blinde, Krüppel, Stumme und viele andere bei sich hatten, und sie warfen sie ihm zu Füßen; und er heilte sie*,", footnotes: ["℘ Kap. 4,23.24; Lk 7,22"] },
      { number: 31, text: "so dass die Volksmenge sich wunderte, als sie sahen, dass Stumme redeten, Krüppel gesund wurden, Lahme gingen und Blinde sahen; und sie verherrlichten den Gott Israels*.", footnotes: ["℘ Kap. 9,8; Joh 10,32"] },
      { number: 32, text: "Als Jesus aber seine Jünger herangerufen hatte, sprach er: Ich bin innerlich bewegt über die Volksmenge*, denn schon drei Tage harren sie bei mir aus und haben nichts zu essen; und ich will sie nicht hungrig entlassen, damit sie nicht etwa auf dem Weg verschmachten.", footnotes: ["℘ Kap. 9,36 ⇨Esyn: Synopse Nr. 153"] },
      { number: 33, text: "Und seine Jünger sagen zu ihm: Woher nehmen wir in der Einöde so viele Brote, um eine so große Volksmenge zu sättigen?" },
      { number: 34, text: "Und Jesus spricht zu ihnen: Wie viele Brote habt ihr? Sie aber sagen: Sieben* und wenige kleine Fische.", footnotes: ["℘ Kap. 16,10"] },
      { number: 35, text: "Und er gebot den Volksmengen, sich auf die Erde zu lagern." },
      { number: 36, text: "Er nahm die sieben Brote und die Fische, dankte* und brach und gab sie den Jüngern, die Jünger aber <gaben sie> den Volksmengen.", footnotes: ["℘ 1Tim 4,4.5"] },
      { number: 37, text: "Und sie aßen alle und wurden gesättigt; und sie hoben auf, was an Brocken übrig blieb, sieben Körbe voll*.", footnotes: ["℘ Mk 8,20"] },
      { number: 38, text: "Die aber aßen, waren viertausend Männer, ohne Frauen und Kinder." },
      { number: 39, text: "Und als er die Volksmengen entlassen hatte, stieg er in das Boot und kam in das Gebiet von Magadan*.", footnotes: ["Wahrscheinlich ist mit namhaften Texten »Magdala« zu lesen."] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Und die Pharisäer* und Sadduzäer* kamen herbei; und um ihn zu versuchen*, baten sie ihn, er möge ihnen ein Zeichen aus dem Himmel zeigen*.", heading: "Zeichenforderung der Pharisäer und Sadduzäer — Warnung vor ihnen", footnotes: ["℘ Mk 8,11-21", "religiöse Partei, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Kap. 3,7", "religiöse Partei, der u. a. die vornehmen Priesterfamilien angehörten; s. auch Anm. zu Kap. 3,7", "℘ Joh 8,6", "℘ Kap. 12,38 ⇨Esyn: Synopse Nr. 154"] },
      { number: 2, text: "Er aber antwortete und sprach zu ihnen: Wenn es Abend geworden ist, so sagt ihr: Heiteres Wetter, denn der Himmel ist feuerrot;" },
      { number: 3, text: "und frühmorgens: Heute stürmisches Wetter, denn der Himmel ist feuerrot <und> trübe. Das Aussehen des Himmels wisst ihr zwar zu beurteilen*, aber die Zeichen der Zeiten könnt ihr nicht <beurteilen>*.", footnotes: ["o. zu unterscheiden", "℘ Lk 12,54-56"] },
      { number: 4, text: "Ein böses und ehebrecherisches Geschlecht verlangt nach einem Zeichen; und kein Zeichen wird ihm gegeben werden, als nur das Zeichen Jonas*. Und er verließ sie und ging weg*.", footnotes: ["℘ Kap. 12,39.40", "℘ Kap. 21,17"] },
      { number: 5, text: "Und als seine Jünger an das jenseitige Ufer gekommen waren, hatten sie vergessen, Brote mitzunehmen. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 155"] },
      { number: 6, text: "Jesus aber sprach zu ihnen: Seht zu und hütet euch vor dem Sauerteig der Pharisäer und Sadduzäer*!", footnotes: ["℘ Lk 12,1"] },
      { number: 7, text: "Sie aber überlegten bei sich selbst und sagten: <Das sagt er,> weil wir keine Brote mitgenommen haben." },
      { number: 8, text: "Als aber Jesus es erkannte, sprach er: Was überlegt ihr bei euch selbst, Kleingläubige*, weil ihr keine Brote habt?", footnotes: ["℘ Kap. 6,30"] },
      { number: 9, text: "Versteht ihr noch nicht*, erinnert ihr euch auch nicht an die fünf Brote der Fünftausend, und wie viele Handkörbe ihr aufhobt*?", footnotes: ["℘ Kap. 15,16", "℘ Kap. 14,17-21"] },
      { number: 10, text: "Auch nicht an die sieben Brote der Viertausend, und wie viele Körbe ihr aufhobt*?", footnotes: ["℘ Kap. 15,34-38"] },
      { number: 11, text: "Wie, versteht ihr nicht, dass ich nicht von Broten zu euch sprach? Hütet euch aber vor dem Sauerteig der Pharisäer und Sadduzäer!" },
      { number: 12, text: "Da verstanden sie, dass er nicht gesagt hatte, sich zu hüten vor dem Sauerteig der Brote, sondern vor der Lehre der Pharisäer* und Sadduzäer*.", footnotes: ["℘ Kap. 15,1-9", "℘ Kap. 22,23"] },
      { number: 13, text: "*Als aber Jesus in die Gegenden von Cäsarea Philippi gekommen war, fragte er seine Jünger und sprach: Was sagen die Menschen, wer der Sohn des Menschen ist*?", heading: "Das Bekenntnis des Petrus", footnotes: ["℘ Mk 8,27-30; Lk 9,18-21", "℘ Joh 12,34 ⇨Esyn: Synopse Nr. 158"] },
      { number: 14, text: "Sie aber sagten: Einige: Johannes der Täufer; andere aber: Elia; und andere wieder: Jeremia oder einer der Propheten*.", footnotes: ["℘ Kap. 14,2; 17,10; Mk 6,14.15"] },
      { number: 15, text: "Er spricht zu ihnen: Ihr aber, was sagt ihr, wer ich bin?" },
      { number: 16, text: "Simon Petrus aber antwortete und sprach: Du bist der Christus, der Sohn des lebendigen Gottes*.", footnotes: ["℘ Kap. 14,33; Joh 6,69; 1Jo 4,15"] },
      { number: 17, text: "Und Jesus antwortete und sprach zu ihm: Glückselig bist du, Simon, Bar Jona*; denn Fleisch und Blut haben es dir nicht offenbart, sondern mein Vater, der in den Himmeln ist*.", footnotes: ["d. h. Sohn Jonas\n℘ Joh 1,42", "℘ Gal 1,15.16"] },
      { number: 18, text: "Aber auch ich sage dir: Du bist Petrus*, und auf diesem Felsen werde ich meine Gemeinde* bauen, und des Hades* Pforten werden sie nicht überwältigen.", footnotes: ["d. h. Fels o. Stein (aram. Kephas)\n℘ Kap. 4,18; 10,2", "o. Versammlung", "d. i. das Totenreich"] },
      { number: 19, text: "Ich werde dir die Schlüssel des Reiches* der Himmel geben; und was immer du auf der Erde binden wirst, wird in den Himmeln gebunden sein, und was immer du auf der Erde lösen wirst, wird in den Himmeln gelöst sein*.", footnotes: ["o. der Königsherrschaft", "℘ Kap. 18,18"] },
      { number: 20, text: "Dann gebot er den Jüngern, dass sie niemand sagten, dass er der Christus sei*.", footnotes: ["℘ Kap. 8,4; 17,9"] },
      { number: 21, text: "*Von der Zeit an begann Jesus seinen Jüngern zu zeigen, dass er nach Jerusalem hingehen müsse* und von den Ältesten und Hohenpriestern* und Schriftgelehrten vieles leiden und getötet und am dritten Tag auferweckt werden müsse*.", heading: "Erste Leidensankündigung — Bedingungen der Nachfolge", footnotes: ["℘ Mk 8,31-9,1; Lk 9,22-27", "℘ Lk 9,31.51", "Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ Kap. 12,40; 17,12.22.23; 20,17-19; 26,2; 27,63; 28,6; Mk 9,31; 10,33.34; Lk 9,44; 17,25; 18,31-33; 24,6.7.46; Joh 2,19.21; 10,17 ⇨Esyn: Synopse Nr. 159"] },
      { number: 22, text: "Und Petrus nahm ihn beiseite und fing an, ihn zu tadeln, indem er sagte: <Gott> behüte dich, Herr! Dies wird dir keinesfalls widerfahren." },
      { number: 23, text: "Er aber wandte sich um und sprach zu Petrus: Geh hinter mich, Satan! Du bist mir ein Ärgernis*, denn du sinnst nicht auf das, was Gottes, sondern auf das, was der Menschen ist*.", footnotes: ["o. eine Verführung zur Sünde", "℘ Jes 55,8.9"] },
      { number: 24, text: "Dann sprach Jesus zu seinen Jüngern: Wenn jemand mir nachkommen will, verleugne er sich selbst und nehme sein Kreuz auf und folge mir nach*!", footnotes: ["℘ Kap. 10,38 ⇨Esyn: Synopse Nr. 160"] },
      { number: 25, text: "Denn wer sein Leben* retten will, wird es verlieren; wer aber sein Leben* verliert um meinetwillen, wird es finden*.", footnotes: ["o. seine Seele", "o. seine Seele", "℘ Kap. 10,39; Hebr 11,35"] },
      { number: 26, text: "Denn was wird es einem Menschen nützen, wenn er die ganze Welt gewönne, aber sein Leben* einbüßte? Oder was wird ein Mensch als Lösegeld geben für sein Leben*?", footnotes: ["o. seine Seele", "o. seine Seele\n℘ Ps 49,8.9"] },
      { number: 27, text: "Denn der Sohn des Menschen wird kommen in der Herrlichkeit seines Vaters mit seinen Engeln*, und dann wird er einem jeden vergelten nach seinem Tun*.", footnotes: ["℘ Kap. 24,30; 25,31; 26,64; Mk 13,26; 2Thes 1,7", "℘ 2Kor 5,10; Offb 2,23"] },
      { number: 28, text: "Wahrlich, ich sage euch: Es sind einige von denen, die hier stehen, die werden den Tod keinesfalls schmecken, bis sie den Sohn des Menschen haben kommen sehen in seinem Reich*.", footnotes: ["o. seiner Königsherrschaft\n℘ Dan 7,13.14; Lk 23,42; 2Tim 4,1; 2Petr 1,16"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "*Und nach sechs Tagen nimmt Jesus den Petrus und Jakobus und Johannes, seinen Bruder*, mit und führt sie abseits auf einen hohen Berg.", heading: "Die Verklärung Jesu", footnotes: ["℘ Mk 9,2-13; Lk 9,28-36; 2Petr 1,16-18", "℘ Kap. 26,37; Mk 5,37 ⇨Esyn: Synopse Nr. 161"] },
      { number: 2, text: "Und er wurde vor ihnen umgestaltet. Und sein Angesicht leuchtete wie die Sonne*, seine Kleider aber wurden weiß wie das Licht;", footnotes: ["℘ Kap. 28,3; Offb 1,16"] },
      { number: 3, text: "und siehe, Mose und Elia erschienen ihnen und unterredeten sich mit ihm." },
      { number: 4, text: "Petrus aber begann* und sprach zu Jesus: Herr, es ist gut, dass wir hier sind. Wenn du willst, werde ich hier drei Hütten machen, dir eine und Mose eine und Elia eine.", footnotes: ["w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht"] },
      { number: 5, text: "Während er noch redete, siehe, da überschattete sie eine lichte Wolke*, und siehe, eine Stimme <kam> aus der Wolke, welche sprach: Dieser ist mein geliebter Sohn, an dem ich Wohlgefallen gefunden habe*. Ihn hört*!", footnotes: ["℘ 2Mo 24,16", "℘ Kap. 3,17", "℘ 5Mo 18,15"] },
      { number: 6, text: "Und als die Jünger es hörten, fielen sie auf ihr Angesicht und fürchteten sich sehr." },
      { number: 7, text: "Und Jesus trat herbei, rührte sie an und sprach: Steht auf und fürchtet euch nicht!" },
      { number: 8, text: "Als sie aber ihre Augen aufhoben, sahen sie niemand als ihn, Jesus, allein*.", footnotes: ["℘ Hebr 12,2"] },
      { number: 9, text: "Und als sie von dem Berg herabstiegen, gebot ihnen Jesus und sprach: Sagt niemandem die Erscheinung <weiter>, bis der Sohn des Menschen aus den Toten auferweckt worden ist*!", footnotes: ["℘ Kap. 16,20.21"] },
      { number: 10, text: "Und die Jünger fragten ihn und sprachen: Was sagen denn die Schriftgelehrten, dass Elia zuerst kommen müsse*?", footnotes: ["℘ Kap. 16,14 ⇨Esyn: Synopse Nr. 162"] },
      { number: 11, text: "Er aber antwortete und sprach zu ihnen: Elia kommt zwar und wird alle Dinge wiederherstellen*.", footnotes: ["℘ Mal 3,23; Apg 3,21"] },
      { number: 12, text: "Ich sage euch aber, dass Elia schon gekommen ist, und sie haben ihn nicht erkannt, sondern an ihm getan, was sie wollten. Ebenso wird auch der Sohn des Menschen von ihnen leiden*.", footnotes: ["℘ Kap. 16,20.21"] },
      { number: 13, text: "Da verstanden die Jünger, dass er von Johannes dem Täufer zu ihnen sprach*.", footnotes: ["℘ Kap. 11,14; 14,10; Mk 6,28; Lk 1,16.17"] },
      { number: 14, text: "*Und als sie zu der Volksmenge kamen, trat ein Mensch zu ihm und fiel vor ihm auf die Knie*", heading: "Heilung eines Fallsüchtigen", footnotes: ["℘ Mk 9,14-29; Lk 9,37-43", "℘ Lk 8,41 ⇨Esyn: Synopse Nr. 163"] },
      { number: 15, text: "und sprach: Herr, erbarme dich meines Sohnes! Denn er ist mondsüchtig und leidet arg; denn oft fällt er ins Feuer und oft ins Wasser." },
      { number: 16, text: "Und ich brachte ihn zu deinen Jüngern, doch sie konnten ihn nicht heilen." },
      { number: 17, text: "Jesus aber antwortete und sprach: Ungläubiges und verkehrtes Geschlecht*! Bis wann soll ich bei euch sein? Bis wann soll ich euch ertragen*? Bringt ihn mir her!", footnotes: ["℘ 5Mo 32,5; Apg 2,40; Phil 2,15", "℘ 4Mo 14,11"] },
      { number: 18, text: "Und Jesus bedrohte ihn*, und der Dämon fuhr von ihm aus; und von jener Stunde an war der Junge geheilt*.", footnotes: ["℘ Kap. 8,16", "℘ Apg 10,38"] },
      { number: 19, text: "Da traten die Jünger für sich allein zu Jesus und sprachen: Warum haben wir ihn nicht austreiben können?" },
      { number: 20, text: "Er aber spricht zu ihnen: Wegen eures Kleinglaubens*; denn wahrlich, ich sage euch, wenn ihr Glauben habt wie ein Senfkorn, so werdet ihr zu diesem Berg sagen: Hebe dich weg von hier dorthin!, und er wird sich hinwegheben. Und nichts wird euch unmöglich sein*.", footnotes: ["mit mehreren alten Handschr.: Unglaubens\n℘ Hebr 3,19", "℘ Kap. 21,21.22; Mk 11,23; Lk 17,6; 1Kor 13,2"] },
      { number: 21, text: "[T>]*", footnotes: ["Mehrere Handschr. fügen hinzu: Diese Art aber fährt nicht aus außer durch Gebet und Fasten."] },
      { number: 22, text: "*Als sie sich aber in Galiläa aufhielten*, sprach Jesus zu ihnen: Der Sohn des Menschen wird überliefert werden in der Menschen Hände*,", heading: "Zweite Leidensankündigung", footnotes: ["℘ Mk 9,30-32; Lk 9,43-45", "o. umherzogen", "℘ Kap. 26,45 ⇨Esyn: Synopse Nr. 164"] },
      { number: 23, text: "und sie werden ihn töten, und am dritten Tag wird er auferweckt werden*. Und sie wurden sehr betrübt*.", footnotes: ["℘ Kap. 16,21; Mk 8,31; Lk 9,22", "℘ Kap. 9,15; Joh 16,6"] },
      { number: 24, text: "Als sie aber nach Kapernaum kamen, traten die Einnehmer der Doppeldrachmen* zu Petrus und sprachen: Zahlt euer Lehrer nicht die Doppeldrachmen*?", heading: "Die Tempelsteuer", footnotes: ["℘ 2Mo 30,12-15; 2Chr 24,6; Neh 10,33 ⇨Esyn: Synopse Nr. 165", "d. i. der Jahresbetrag der jüdischen Kopfsteuer für den Tempel"] },
      { number: 25, text: "Er sagt: Doch. Und als er in das Haus eintrat, kam Jesus ihm zuvor und sprach: Was meinst du, Simon? Von wem erheben die Könige der Erde Zoll oder Steuer, von ihren Söhnen oder von den Fremden?" },
      { number: 26, text: "Da er aber sagte: Von den Fremden, sprach Jesus zu ihm: Demnach sind die Söhne frei." },
      { number: 27, text: "Damit wir ihnen aber kein Ärgernis geben*, geh an den See, wirf eine Angel aus und nimm den ersten Fisch, der heraufkommt, öffne sein Maul, und du wirst einen Stater* finden; den nimm und gib ihnen für mich und dich!", footnotes: ["Das griech. Wort bedeutet auch: Anstoß geben, zu Fall bringen, zur Sünde verleiten.\n℘ Röm 14,13", "d. i. ein Vierdrachmenstück"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "*In jener Stunde traten die Jünger zu Jesus und sprachen: Wer ist denn der Größte im Reich* der Himmel*?", heading: "Wahre Größe im Reich der Himmel — Warnung vor Verführung zur Sünde — Gleichnis vom verlorenen Schaf", footnotes: ["℘ V. 1-9; Mk 9,33-37.42-48; Lk 9,46-48", "o. in der Königsherrschaft", "℘ Lk 22,24 ⇨Esyn: Synopse Nr. 166"] },
      { number: 2, text: "Und als Jesus ein Kind herbeigerufen hatte, stellte er es in ihre Mitte" },
      { number: 3, text: "und sprach: Wahrlich, ich sage euch, wenn ihr nicht umkehrt und werdet wie die Kinder*, so werdet ihr keinesfalls in das Reich* der Himmel hineinkommen*.", footnotes: ["℘ Kap. 19,14", "o. die Königsherrschaft", "℘ Kap. 5,20; Lk 18,16"] },
      { number: 4, text: "Darum, wenn jemand sich selbst erniedrigen wird wie dieses Kind, der ist der Größte im Reich* der Himmel*;", footnotes: ["o. in der Königsherrschaft", "℘ Kap. 20,26; 23,11.12"] },
      { number: 5, text: "und wenn jemand ein solches Kind aufnehmen wird in meinem Namen, nimmt er mich auf*.", footnotes: ["℘ Kap. 10,40"] },
      { number: 6, text: "Wenn aber jemand einem dieser Kleinen, die an mich glauben, Anlass zur Sünde gibt*, für den wäre es besser, dass ein Mühlstein an seinen Hals gehängt und er in die Tiefe des Meeres versenkt würde*.", footnotes: ["o. Anstoß gibt; o. ärgert", "℘ Lk 17,2 ⇨Esyn: Synopse Nr. 168"] },
      { number: 7, text: "Wehe der Welt der Verführungen* wegen! Denn es ist notwendig, dass Verführungen* kommen. Doch wehe dem Menschen, durch den die Verführung* kommt*!", footnotes: ["o. der Anlässe zur Sünde; o. der Ärgernisse", "o. Anlässe zur Sünde; o. Ärgernisse", "o. der Anlass zur Sünde; o. das Ärgernis", "℘ Kap. 26,24; Lk 17,1"] },
      { number: 8, text: "Wenn aber deine Hand oder dein Fuß dir Anlass zur Sünde gibt, so hau ihn ab und wirf ihn von dir*! Es ist besser für dich, lahm oder als Krüppel in das Leben hineinzugehen, als mit zwei Händen oder mit zwei Füßen in das ewige Feuer geworfen zu werden*.", footnotes: ["℘ Kap. 5,29.30", "℘ Kap. 5,22; Jes 66,24; Jud 7"] },
      { number: 9, text: "Und wenn dein Auge dir Anlass zur Sünde gibt, so reiß es aus und wirf es von dir*! Es ist besser für dich, einäugig in das Leben hineinzugehen, als mit zwei Augen in die Hölle des Feuers geworfen zu werden*.", footnotes: ["℘ Kap. 5,22; Jes 66,24; Jud 7", "℘ Kap. 5,22; Jes 66,24; Jud 7"] },
      { number: 10, text: "Seht zu, dass ihr nicht eines dieser Kleinen verachtet! Denn ich sage euch, dass ihre Engel* in den Himmeln allezeit das Angesicht meines Vaters schauen, der in den Himmeln ist.", footnotes: ["℘ Apg 12,15 ⇨Esyn: Synopse Nr. 169"] },
      { number: 11, text: "[T>]*", footnotes: ["Mehrere Handschr. fügen hinzu: Denn der Sohn des Menschen ist gekommen, das Verlorene zu retten.\n℘ Lk 15,6"] },
      { number: 12, text: "*Was meint ihr? Wenn ein Mensch hundert Schafe hätte und eins von ihnen sich verirrte*, lässt er nicht die neunundneunzig auf den Bergen und geht hin und sucht das irrende?", footnotes: ["℘ V. 12.13: vgl. Lk 15,4-7", "℘ Jes 53,6; Hes 34,11.12"] },
      { number: 13, text: "Und wenn es geschieht, dass er es findet, wahrlich, ich sage euch, er freut sich mehr über dieses als über die neunundneunzig, die nicht verirrt sind." },
      { number: 14, text: "So ist es nicht der Wille eures Vaters, der in den Himmeln ist, dass eines dieser Kleinen verloren gehe." },
      { number: 15, text: "Wenn aber dein Bruder* sündigt, so geh hin*, überführe ihn zwischen dir und ihm allein*! Wenn er auf dich hört, so hast du deinen Bruder gewonnen.", heading: "Verhalten gegen sündigende Brüder — Gemeinschaft in Jesu Namen", footnotes: ["Andere Handschr. fügen hinzu: gegen dich", "℘ Kap. 5,24", "℘ 3Mo 19,17; Lk 17,3 ⇨Esyn: Synopse Nr. 170"] },
      { number: 16, text: "Wenn er aber nicht hört, so nimm noch einen oder zwei mit dir, damit aus zweier oder dreier Zeugen Mund jede Sache bestätigt werde*!", footnotes: ["℘ 5Mo 17,6; 19,15; Joh 8,17; 2Kor 13,1; 1Tim 5,19; Hebr 10,28"] },
      { number: 17, text: "Wenn er aber nicht auf sie hören wird, so sage es der Gemeinde*; wenn er aber auch auf die Gemeinde* nicht hören wird, so sei er dir wie der Heide und der Zöllner*!", footnotes: ["o. Versammlung", "o. Versammlung", "℘ 1Kor 5,13"] },
      { number: 18, text: "Wahrlich, ich sage euch: Wenn ihr etwas auf der Erde bindet, wird es im Himmel gebunden sein, und wenn ihr etwas auf der Erde löst, wird es im Himmel gelöst sein*.", footnotes: ["℘ Kap. 16,19; Joh 20,23"] },
      { number: 19, text: "Wiederum sage ich euch: Wenn zwei von euch auf der Erde übereinkommen, irgendeine Sache zu erbitten, so wird sie ihnen werden von meinem Vater, der in den Himmeln ist*.", footnotes: ["℘ Kap. 7,7.8 ⇨Esyn: Synopse Nr. 171"] },
      { number: 20, text: "Denn wo zwei oder drei versammelt sind in meinem Namen*, da bin ich in ihrer Mitte*.", footnotes: ["o. zu meinem Namen hin", "℘ 1Kor 5,4"] },
      { number: 21, text: "Dann trat Petrus zu ihm und sprach: Herr, wie oft soll ich meinem Bruder, der gegen mich sündigt, vergeben? Bis siebenmal*?", heading: "Gleichnis vom unbarmherzigen Knecht", footnotes: ["℘ Kap. 6,12 ⇨Esyn: Synopse Nr. 172"] },
      { number: 22, text: "Jesus spricht zu ihm: Ich sage dir: Nicht bis siebenmal, sondern bis siebzigmal sieben<mal>*!", footnotes: ["d. h. sehr oft\n℘ Lk 17,3.4"] },
      { number: 23, text: "Deswegen ist es mit dem Reich* der Himmel wie* mit einem König, der mit seinen Knechten* abrechnen wollte*.", footnotes: ["o. der Königsherrschaft", "w. Deswegen ist das Reich der Himmel verglichen worden (o. zu vergleichen)", "w. Sklaven; so auch V. 26—32", "℘ Kap. 25,19 ⇨Esyn: Synopse Nr. 173"] },
      { number: 24, text: "Als er aber anfing abzurechnen, wurde einer zu ihm gebracht, der zehntausend Talente* schuldete.", footnotes: ["größte damalige Geldeinheit; s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 25, text: "Da er aber nicht zahlen konnte, befahl der Herr, ihn und seine Frau und die Kinder und alles, was er hatte, zu verkaufen und <damit> zu bezahlen." },
      { number: 26, text: "Der Knecht nun fiel nieder, bat ihn kniefällig und sprach: Herr, habe Geduld mit mir, und ich will dir alles bezahlen." },
      { number: 27, text: "Der Herr jenes Knechtes aber wurde innerlich bewegt, gab ihn los und erließ ihm das Darlehen." },
      { number: 28, text: "Jener Knecht aber ging hinaus und fand einen seiner Mitknechte, der ihm hundert Denare* schuldig war. Und er ergriff und würgte ihn und sprach: Bezahle, wenn du etwas schuldig bist!", footnotes: ["s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 29, text: "Sein Mitknecht nun fiel nieder und bat ihn und sprach: Habe Geduld mit mir, und ich will dir bezahlen." },
      { number: 30, text: "Er aber wollte nicht, sondern ging hin und warf ihn ins Gefängnis, bis er die Schuld bezahlt habe." },
      { number: 31, text: "Als aber seine Mitknechte sahen, was geschehen war, wurden sie sehr betrübt und gingen und berichteten ihrem Herrn alles, was geschehen war." },
      { number: 32, text: "Da rief ihn sein Herr herbei und spricht zu ihm: Böser Knecht! Jene ganze Schuld habe ich dir erlassen, weil du mich batest." },
      { number: 33, text: "Solltest nicht auch du dich deines Mitknechtes erbarmt haben, wie auch ich mich deiner erbarmt habe*?", footnotes: ["℘ 2Petr 1,9"] },
      { number: 34, text: "Und sein Herr wurde zornig und überlieferte ihn den Folterknechten, bis er alles bezahlt habe, was er ihm schuldig war*.", footnotes: ["℘ Kap. 5,26"] },
      { number: 35, text: "So wird auch mein himmlischer Vater euch tun, wenn ihr nicht ein jeder seinem Bruder von Herzen vergebt*.", footnotes: ["℘ Kap. 6,15"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Und es geschah, als Jesus diese Reden beendet hatte*, begab er sich von Galiläa weg und kam in das Gebiet von Judäa, jenseits des Jordan*.", heading: "Ehescheidung und Eheverzicht", footnotes: ["℘ Mk 10,1-12", "℘ Kap. 7,28", "℘ Joh 10,40 ⇨Esyn: Synopse Nr. 251"] },
      { number: 2, text: "Und es folgten ihm große Volksmengen, und er heilte sie dort*.", footnotes: ["℘ Kap. 4,23.24"] },
      { number: 3, text: "Und Pharisäer kamen zu ihm, versuchten ihn* und sprachen: Ist es <einem> Mann erlaubt, aus jeder <beliebigen> Ursache seine Frau zu entlassen*?", footnotes: ["℘ Kap. 22,15.35; Lk 10,25", "℘ Mal 2,16 ⇨Esyn: Synopse Nr. 252"] },
      { number: 4, text: "Er aber antwortete und sprach: Habt ihr nicht gelesen, dass der, welcher sie schuf, sie von Anfang an <als> Mann und Frau* schuf*", footnotes: ["w. männlich und weiblich", "℘ 1Mo 1,27; 5,2"] },
      { number: 5, text: "und sprach: »Darum wird ein Mensch Vater und Mutter verlassen und seiner Frau anhängen, und es werden die zwei ein Fleisch sein*« —", footnotes: ["℘ 1Mo 2,24; 1Kor 6,16; Eph 5,31"] },
      { number: 6, text: "so dass sie nicht mehr zwei sind, sondern ein Fleisch? Was nun Gott zusammengefügt hat, soll <der> Mensch nicht scheiden*.", footnotes: ["℘ 1Kor 7,10.11"] },
      { number: 7, text: "Sie sagen zu ihm: Warum hat denn Mose geboten, einen Scheidebrief zu geben und zu entlassen*?", footnotes: ["℘ Kap. 5,31"] },
      { number: 8, text: "Er spricht zu ihnen: Mose hat wegen eurer Herzenshärtigkeit* euch gestattet, eure Frauen zu entlassen; von Anfang an aber ist es nicht so gewesen.", footnotes: ["℘ Sach 7,12"] },
      { number: 9, text: "Ich sage euch aber, dass, wer immer seine Frau entlässt, außer wegen Hurerei, und eine andere heiratet, Ehebruch begeht; *und wer eine Entlassene heiratet, begeht Ehebruch*.", footnotes: ["in namhaften Handschr. nicht enthalten", "in namhaften Handschr. nicht enthalten\n℘ Kap. 5,32; Röm 7,2.3"] },
      { number: 10, text: "Seine Jünger sagen zu ihm: Wenn die Sache des Mannes mit der Frau so steht, so ist es nicht ratsam zu heiraten." },
      { number: 11, text: "Er aber sprach zu ihnen: Nicht alle fassen dieses Wort, sondern die, denen es gegeben ist*;", footnotes: ["℘ 1Kor 7,7-9"] },
      { number: 12, text: "denn es gibt Verschnittene, die von Mutterleib so geboren sind; und es gibt Verschnittene, die von den Menschen verschnitten worden sind; und es gibt Verschnittene, die sich selbst verschnitten haben um des Reiches* der Himmel willen. Wer es fassen kann, der fasse es*.", footnotes: ["o. der Königsherrschaft", "℘ 1Kor 7,7-9"] },
      { number: 13, text: "*Dann wurden Kinder zu ihm gebracht, damit er ihnen die Hände auflege und bete. Die Jünger aber fuhren sie an. *", heading: "Jesus und die Kinder", footnotes: ["℘ Mk 10,13-16; Lk 18,15-17", "℘ ⇨Esyn: Synopse Nr. 253"] },
      { number: 14, text: "Jesus aber sprach: Lasst die Kinder, und wehrt ihnen nicht, zu mir zu kommen! Denn solchen gehört das Reich* der Himmel*.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 18,2.3"] },
      { number: 15, text: "Und er legte ihnen die Hände auf und ging von dort weg." },
      { number: 16, text: "*Und siehe, einer trat herbei und sprach zu ihm: Lehrer, was soll ich Gutes tun, damit ich ewiges Leben habe*?", heading: "Frage eines Reichen nach dem ewigen Leben — Lohn der Nachfolge", footnotes: ["℘ Mk 10,17-31; Lk 18,18-30", "℘ Joh 6,27.28 ⇨Esyn: Synopse Nr. 254"] },
      { number: 17, text: "Er aber sprach zu ihm: Was fragst du mich über das Gute? Einer ist der Gute*. Wenn du aber ins Leben hineinkommen willst, so halte die Gebote*!", footnotes: ["℘ Ps 100,5", "℘ 3Mo 18,5; Neh 9,29; Lk 10,28; Gal 3,12"] },
      { number: 18, text: "Er spricht zu ihm: Welche? Jesus aber sprach: Diese: Du sollst nicht töten*; du sollst nicht ehebrechen*; du sollst nicht stehlen; du sollst nicht falsches Zeugnis geben*;", footnotes: ["℘ Kap. 5,21", "℘ Kap. 5,27", "℘ 2Mo 20,12-26; 5Mo 5,16-20"] },
      { number: 19, text: "ehre den Vater und die Mutter*; und du sollst deinen Nächsten lieben wie dich selbst*!", footnotes: ["℘ Kap. 15,4", "℘ Kap. 5,43"] },
      { number: 20, text: "Der junge Mann spricht zu ihm: Alles dies habe ich befolgt*. Was fehlt mir noch?", footnotes: ["o. beachtet, eingehalten"] },
      { number: 21, text: "Jesus sprach zu ihm: Wenn du vollkommen sein willst*, so geh hin, verkaufe deine Habe und gib <den Erlös> den Armen*! Und du wirst einen Schatz im Himmel haben*. Und komm, folge mir nach!", footnotes: ["℘ Kap. 5,48", "℘ Gal 2,10", "℘ Kap. 6,20"] },
      { number: 22, text: "Als aber der junge Mann das Wort hörte, ging er betrübt weg, denn er hatte viele Güter*.", footnotes: ["℘ Ps 62,11"] },
      { number: 23, text: "Jesus aber sprach zu seinen Jüngern: Wahrlich, ich sage euch: Schwer wird ein Reicher in das Reich* der Himmel hineinkommen*.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 13,22 ⇨Esyn: Synopse Nr. 255"] },
      { number: 24, text: "Wiederum aber sage ich euch: Es ist leichter, dass ein Kamel durch ein Nadelöhr geht, als dass ein Reicher in das Reich* Gottes hineinkommt.", footnotes: ["o. die Königsherrschaft"] },
      { number: 25, text: "Als aber die Jünger es hörten, gerieten sie ganz außer sich* und sagten: Wer kann dann gerettet werden?", footnotes: ["℘ Kap. 7,28"] },
      { number: 26, text: "Jesus aber sah sie an und sprach zu ihnen: Bei Menschen ist dies unmöglich, bei Gott aber sind alle Dinge möglich*.", footnotes: ["℘ 1Mo 18,14; Hi 42,2; Jer 32,17.27; Sach 8,6; Lk 1,37"] },
      { number: 27, text: "Da antwortete Petrus und sprach zu ihm: Siehe, wir haben alles verlassen und sind dir nachgefolgt*. Was wird uns nun werden?", footnotes: ["℘ Kap. 4,20.22; Lk 5,11"] },
      { number: 28, text: "Jesus aber sprach zu ihnen: Wahrlich, ich sage euch: Ihr, die ihr mir nachgefolgt seid, auch ihr werdet in der Wiedergeburt, wenn der Sohn des Menschen auf seinem Thron der Herrlichkeit* sitzen wird, auf zwölf Thronen sitzen und die zwölf Stämme Israels richten*.", footnotes: ["℘ Kap. 25,31", "℘ Lk 22,30"] },
      { number: 29, text: "Und ein jeder, der Häuser oder Brüder oder Schwestern oder Vater oder Mutter oder Kinder oder Äcker um meines Namens willen verlassen hat, wird hundertfach empfangen und ewiges Leben erben*.", footnotes: ["℘ Hebr 10,34"] },
      { number: 30, text: "Aber viele Erste werden Letzte und Letzte Erste sein*.", footnotes: ["℘ Kap. 20,16; Lk 13,30"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Denn mit dem Reich* der Himmel ist es wie mit einem Hausherrn*, der ganz frühmorgens hinausging, um Arbeiter in seinen Weinberg einzustellen. *", heading: "Gleichnis von den Arbeitern im Weinberg", footnotes: ["o. der Königsherrschaft", "w. das Reich der Himmel ist einem Hausherrn gleich", "℘ ⇨Esyn: Synopse Nr. 256"] },
      { number: 2, text: "Nachdem er aber mit den Arbeitern um einen Denar den Tag übereingekommen war, sandte er sie in seinen Weinberg." },
      { number: 3, text: "Und als er um die dritte Stunde* ausging, sah er andere auf dem Markt müßig stehen;", footnotes: ["In neutestamentl. Zeit teilte man Tag und Nacht in je 12 Stunden ein (vgl. auch Anm. zu Mk 13,35), wobei sich die Länge der Stunden nach der Länge des Tages zwischen Sonnenauf- und Sonnenuntergang richtete. Das Ende der 6. Stunde fiel also dabei immer auf den Mittag 12 Uhr unserer Zeit."] },
      { number: 4, text: "und zu diesen sprach er: Geht auch ihr hin in den Weinberg! Und was recht ist, werde ich euch geben*.", footnotes: ["℘ 1Kor 3,8"] },
      { number: 5, text: "Sie aber gingen hin. Wieder aber ging er hinaus um die sechste und neunte Stunde und machte es ebenso." },
      { number: 6, text: "Als er aber um die elfte <Stunde> hinausging, fand er andere stehen und spricht zu ihnen: Was steht ihr hier den ganzen Tag müßig?" },
      { number: 7, text: "Sie sagen zu ihm: Weil niemand uns eingestellt hat. Er spricht zu ihnen: Geht auch ihr hin in den Weinberg!" },
      { number: 8, text: "Als es aber Abend geworden war, spricht der Herr des Weinbergs zu seinem Verwalter: Rufe die Arbeiter und zahle ihnen den Lohn*, angefangen von den letzten bis zu den ersten!", footnotes: ["℘ 3Mo 19,13; 5Mo 24,15"] },
      { number: 9, text: "Und als die um die elfte Stunde <Eingestellten> kamen, empfingen sie je einen Denar." },
      { number: 10, text: "Als aber die Ersten kamen, meinten sie, dass sie mehr empfangen würden; und auch sie empfingen je einen Denar." },
      { number: 11, text: "Als sie den aber empfingen, murrten sie gegen den Hausherrn" },
      { number: 12, text: "und sprachen: Diese Letzten haben eine Stunde gearbeitet, und du hast sie uns gleichgemacht, die wir die Last des Tages und die Hitze getragen haben." },
      { number: 13, text: "Er aber antwortete und sprach zu einem von ihnen: Freund, ich tue dir nicht Unrecht*. Bist du nicht um einen Denar mit mir übereingekommen?", footnotes: ["℘ Ps 145,17"] },
      { number: 14, text: "Nimm das Deine und geh hin! Ich will aber diesem Letzten geben wie auch dir." },
      { number: 15, text: "Ist es mir nicht erlaubt, mit dem Meinen zu tun, was ich will*? Oder blickt dein Auge böse*, weil ich gütig bin?", footnotes: ["℘ Röm 9,20", "℘ Kap. 6,23; Mk 7,22"] },
      { number: 16, text: "So werden die Letzten Erste und die Ersten Letzte sein*; *denn viele sind Berufene, wenige aber Auserwählte*.", footnotes: ["℘ Kap. 19,30; Mk 10,31", "in den wichtigsten alten Handschr. nicht enthalten", "in den wichtigsten alten Handschr. nicht enthalten\n℘ Kap. 22,14"] },
      { number: 17, text: "*Und als Jesus nach Jerusalem hinaufging, nahm er die zwölf Jünger allein zu sich und sprach auf dem Weg zu ihnen: *", heading: "Dritte Leidensankündigung", footnotes: ["℘ Mk 10,32-34; Lk 18,31-34", "℘ ⇨Esyn: Synopse Nr. 262"] },
      { number: 18, text: "Siehe, wir gehen hinauf nach Jerusalem, und der Sohn des Menschen wird den Hohenpriestern* und Schriftgelehrten überliefert werden*, und sie werden ihn zum Tode verurteilen*;", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ Kap. 16,21", "℘ Kap. 26,66; Joh 19,7"] },
      { number: 19, text: "und sie werden ihn den Nationen überliefern*, um ihn zu verspotten und zu geißeln* und zu kreuzigen*; und am dritten Tag wird er auferweckt werden*.", footnotes: ["℘ Kap. 27,2", "℘ Joh 19,1", "℘ Kap. 26,2; 27,22.23; Joh 12,33; 19,18", "℘ Kap. 27,63"] },
      { number: 20, text: "*Dann trat die Mutter der Söhne des Zebedäus* mit ihren Söhnen zu ihm und warf sich nieder und wollte etwas von ihm erbitten.", heading: "Wahre Größe im Reich Gottes", footnotes: ["℘ Mk 10,35-45", "℘ Kap. 10,2 ⇨Esyn: Synopse Nr. 263"] },
      { number: 21, text: "Er aber sprach zu ihr: Was willst du? Sie sagt zu ihm: Bestimme*, dass diese meine zwei Söhne einer zu deiner Rechten und einer zu deiner Linken sitzen mögen in deinem Reich*!", footnotes: ["w. Sprich", "o. deiner Königsherrschaft"] },
      { number: 22, text: "Jesus aber antwortete und sprach: Ihr wisst nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken werde*? Sie sagen zu ihm: Wir können es.", footnotes: ["℘ Kap. 26,39.42; Joh 18,11"] },
      { number: 23, text: "Er spricht zu ihnen: Meinen Kelch werdet ihr zwar trinken, aber das Sitzen zu meiner Rechten und zu <meiner> Linken zu vergeben, steht nicht bei mir, sondern <ist für die,> denen es von meinem Vater bereitet ist*.", footnotes: ["℘ Kap. 25,34"] },
      { number: 24, text: "Und als die Zehn es hörten, wurden sie unwillig über die zwei Brüder*.", footnotes: ["℘ Gal 5,26"] },
      { number: 25, text: "Jesus aber rief sie heran und sprach: Ihr wisst, dass die Regenten der Nationen sie beherrschen und die Großen Gewalt gegen sie üben*.", footnotes: ["℘ Lk 22,25"] },
      { number: 26, text: "Unter euch wird es nicht so sein; sondern wenn jemand unter euch groß werden will, wird er euer Diener sein*,", footnotes: ["℘ Kap. 18,4; Lk 9,48"] },
      { number: 27, text: "und wenn jemand unter euch der Erste sein will, wird er euer Sklave sein*;", footnotes: ["℘ Kap. 23,11; 2Kor 4,5; 1Petr 5,3"] },
      { number: 28, text: "gleichwie der Sohn des Menschen nicht gekommen ist, um bedient zu werden, sondern um zu dienen* und sein Leben zu geben* als Lösegeld für viele*.", footnotes: ["℘ Lk 22,27; Phil 2,7", "℘ Joh 10,11.15.17; 1Jo 3,16", "℘ Kap. 26,28; Jes 53,12; 1Tim 2,6; Tit 2,14; 1Petr 1,18.19"] },
      { number: 29, text: "*Und als sie von Jericho auszogen, folgte ihm eine große Volksmenge. *", heading: "Heilung zweier Blinder", footnotes: ["℘ Mk 10,46-52; Lk 18,35-43; vgl. Kap. 9,27-31; Mk 8,22-26", "℘ ⇨Esyn: Synopse Nr. 264"] },
      { number: 30, text: "Und siehe, zwei Blinde, die am Weg saßen und hörten, dass Jesus vorübergehe, schrien und sprachen: Erbarme dich unser, Herr, Sohn Davids!" },
      { number: 31, text: "Die Volksmenge aber bedrohte sie, dass sie schweigen sollten. Sie aber schrien noch mehr und sprachen: Erbarme dich unser, Herr, Sohn Davids*!", footnotes: ["℘ Kap. 1,1"] },
      { number: 32, text: "Und Jesus blieb stehen und rief sie und sprach: Was wollt ihr, dass ich euch tun soll?" },
      { number: 33, text: "Sie sagen zu ihm: Herr, dass unsere Augen geöffnet werden." },
      { number: 34, text: "Jesus aber, innerlich bewegt*, rührte ihre Augen an; und sogleich wurden sie sehend, und sie folgten ihm nach.", footnotes: ["℘ Kap. 9,36"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Und als sie sich Jerusalem näherten und nach Betfage kamen, an den Ölberg, da sandte Jesus zwei Jünger *", heading: "Einzug in Jerusalem", footnotes: ["℘ Mk 11,1-11; Lk 19,28-40; Joh 12,12-19", "℘ ⇨Esyn: Synopse Nr. 269"] },
      { number: 2, text: "und sprach zu ihnen: Geht hin in das Dorf, das euch gegenüberliegt; und sogleich werdet ihr eine Eselin angebunden finden und ein Fohlen bei ihr. Bindet sie los und führt sie zu mir!" },
      { number: 3, text: "Und wenn jemand etwas zu euch sagt, so sollt ihr sprechen: Der Herr braucht sie, und sogleich wird er sie senden*.", footnotes: ["℘ Kap. 26,18"] },
      { number: 4, text: "Dies aber ist geschehen, damit erfüllt würde, was durch den Propheten geredet ist, der spricht:" },
      { number: 5, text: "»Sagt der Tochter Zion: Siehe, dein König kommt* zu dir, sanftmütig und auf einer Eselin reitend, und <zwar> auf einem Fohlen, dem Jungen eines Lasttiers*.«", footnotes: ["℘ Jes 62,11", "℘ Sach 9,9"] },
      { number: 6, text: "Als aber die Jünger hingegangen waren und getan hatten, wie Jesus ihnen aufgetragen," },
      { number: 7, text: "brachten sie die Eselin und das Fohlen und legten ihre Kleider auf sie, und er setzte sich darauf." },
      { number: 8, text: "Und eine sehr große Volksmenge breitete ihre Kleider aus auf den Weg, andere aber hieben Zweige von den Bäumen und streuten sie auf den Weg*.", footnotes: ["℘ 2Kö 9,13"] },
      { number: 9, text: "Die Volksmengen aber, die vor ihm hergingen und nachfolgten, riefen und sprachen: Hosanna* dem Sohn Davids*! Gepriesen <sei>, der da kommt im Namen des Herrn*! Hosanna in der Höhe*!", footnotes: ["griech. Form des hebr.-aram. Ausdrucks für »Hilf doch <Herr>!«", "℘ V. 15; Kap. 9,27", "℘ Kap. 23,39; Ps 118,26", "℘ Lk 2,14"] },
      { number: 10, text: "Und als er in Jerusalem einzog, kam die ganze Stadt in Bewegung und sprach: Wer ist dieser*?", footnotes: ["℘ Mk 4,41 ⇨Esyn: Synopse Nr. 271"] },
      { number: 11, text: "Die Volksmengen aber sagten: Dieser ist Jesus, der Prophet*, der von Nazareth in Galiläa*.", footnotes: ["℘ V. 46; Lk 7,16; Joh 7,40", "℘ Kap. 2,23"] },
      { number: 12, text: "*Und Jesus trat in den Tempel ein und trieb alle hinaus, die im Tempel verkauften und kauften*, und die Tische der Wechsler und die Sitze der Taubenverkäufer stieß er um.", heading: "Tempelreinigung", footnotes: ["℘ Mk 11,15-19; Lk 19,45-48; vgl. Joh 2,13-17", "℘ 5Mo 14,24-26 ⇨Esyn: Synopse Nr. 100"] },
      { number: 13, text: "Und er spricht zu ihnen: Es steht geschrieben: »Mein Haus wird ein Bethaus genannt werden«*; ihr aber macht es zu einer »Räuberhöhle«*.", footnotes: ["℘ Jes 56,7", "℘ Jer 7,11"] },
      { number: 14, text: "Und es traten Blinde und Lahme in dem Tempel zu ihm, und er heilte sie*.", footnotes: ["℘ Kap. 9,8; Jes 35,5.6"] },
      { number: 15, text: "Als aber die Hohenpriester und die Schriftgelehrten die Wunder sahen, die er tat, und die Kinder, die im Tempel schrien und sagten: Hosanna dem Sohn Davids*!, wurden sie unwillig", footnotes: ["℘ V. 9"] },
      { number: 16, text: "und sprachen zu ihm: Hörst du, was diese sagen? Jesus aber sprach zu ihnen: Ja, habt ihr nie gelesen: »Aus dem Mund der Unmündigen und Säuglinge hast du dir Lob bereitet«?*", footnotes: ["℘ Ps 8,3; Lk 19,39.40"] },
      { number: 17, text: "Und er verließ sie und ging zur Stadt hinaus nach Betanien und übernachtete dort*.", footnotes: ["℘ Kap. 16,4; Mk 11,11; Lk 21,37"] },
      { number: 18, text: "*Des Morgens früh aber, als er in die Stadt zurückkehrte, hungerte ihn*.", heading: "Der verdorrende Feigenbaum und das Glaubensgebet", footnotes: ["℘ Mk 11,12-14.20-24", "℘ Kap. 4,2; Lk 4,2; Hebr 4,15 ⇨Esyn: Synopse Nr. 272"] },
      { number: 19, text: "Und als er einen Feigenbaum an dem Weg sah, ging er auf ihn zu und fand nichts an ihm als nur Blätter*. Und er spricht zu ihm: Nie mehr komme Frucht von dir in Ewigkeit*! Und sogleich verdorrte der Feigenbaum*.", footnotes: ["℘ Lk 13,6", "griech. Äon", "℘ Hos 9,16"] },
      { number: 20, text: "Und als die Jünger es sahen, verwunderten sie sich und sprachen: Wie ist der Feigenbaum sogleich verdorrt? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 275"] },
      { number: 21, text: "Jesus aber antwortete und sprach zu ihnen: Wahrlich, ich sage euch: Wenn ihr Glauben habt und nicht zweifelt*, so werdet ihr nicht allein das mit dem Feigenbaum Geschehene tun, sondern wenn ihr auch zu diesem Berg sagen werdet: Hebe dich empor und wirf dich ins Meer!, so wird es geschehen*.", footnotes: ["℘ Röm 4,20; Jak 1,6", "℘ Kap. 17,20; Lk 17,6"] },
      { number: 22, text: "Und alles, was immer ihr im Gebet glaubend begehrt, werdet ihr empfangen*.", footnotes: ["℘ Kap. 7,7.8"] },
      { number: 23, text: "*Und als er in den Tempel kam, traten, als er lehrte, die Hohenpriester und die Ältesten des Volkes zu ihm und sprachen: In welcher Vollmacht tust du diese Dinge? Und wer hat dir diese Vollmacht gegeben*?", heading: "Die Frage nach der Vollmacht Jesu", footnotes: ["℘ Mk 11,27-33; Lk 20,1-8", "℘ Joh 2,18; Apg 4,7 ⇨Esyn: Synopse Nr. 276"] },
      { number: 24, text: "Jesus aber antwortete und sprach zu ihnen: Auch ich will euch ein Wort fragen*, und wenn ihr es mir sagt, so werde auch ich euch sagen, in welcher Vollmacht ich diese Dinge tue.", footnotes: ["℘ Kap. 22,41"] },
      { number: 25, text: "Woher war die Taufe des Johannes? Vom Himmel oder von Menschen? Sie aber überlegten bei sich selbst und sprachen: Wenn wir sagen: vom Himmel*, so wird er zu uns sagen: Warum habt ihr ihm denn nicht geglaubt*?", footnotes: ["℘ Joh 3,27", "℘ Kap. 11,18"] },
      { number: 26, text: "Wenn wir aber sagen: von Menschen, so haben wir die Volksmenge zu fürchten, denn alle halten Johannes für einen Propheten*.", footnotes: ["℘ Kap. 11,9"] },
      { number: 27, text: "Und sie antworteten Jesus und sprachen: Wir wissen es nicht. Da sagte auch er zu ihnen: So sage auch ich euch nicht, in welcher Vollmacht ich diese Dinge tue." },
      { number: 28, text: "Was meint ihr aber <hierzu>? Ein Mensch hatte zwei Söhne*, und er trat hin zu dem ersten und sprach: *Mein Sohn*, geh heute hin, arbeite im Weinberg! *", heading: "Gleichnis von den ungleichen Söhnen", footnotes: ["w. Kinder", "w. Kind", "w. Kind", "℘ ⇨Esyn: Synopse Nr. 277"] },
      { number: 29, text: "Der aber antwortete und sprach: Ich will nicht. Danach aber gereute es ihn, und er ging hin." },
      { number: 30, text: "Und er trat hin zu dem zweiten und sprach ebenso. Der aber antwortete und sprach: Ich <gehe>, Herr; und er ging nicht*.", footnotes: ["℘ Kap. 7,21; Jer 34,8-11"] },
      { number: 31, text: "Wer von den beiden hat den Willen des Vaters getan? Sie sagen: Der erste. Jesus spricht zu ihnen: Wahrlich, ich sage euch, dass die Zöllner und die Huren euch vorangehen in das Reich* Gottes*.", footnotes: ["o. die/der Königsherrschaft", "℘ Lk 18,14"] },
      { number: 32, text: "Denn Johannes kam zu euch im Weg der Gerechtigkeit, und ihr glaubtet ihm nicht*; die Zöllner aber und die Huren glaubten ihm*; euch aber, als ihr es saht, gereute es auch danach nicht, so dass ihr ihm geglaubt hättet.", footnotes: ["℘ Mk 11,31", "℘ Lk 3,12; 7,29.30"] },
      { number: 33, text: "*Hört ein anderes Gleichnis: Es war ein Hausherr, der einen Weinberg pflanzte* und einen Zaun darum setzte und eine Kelter darin grub und einen Turm baute*; und er verpachtete ihn an Weingärtner und reiste außer Landes*.", heading: "Gleichnis von den Weingärtnern", footnotes: ["℘ Mk 12,1-12; Lk 20,9-19", "℘ Ps 80,9", "℘ Jes 5,2", "℘ Kap. 25,14; Mk 13,34 ⇨Esyn: Synopse Nr. 278"] },
      { number: 34, text: "Als aber die Zeit der Früchte nahte, sandte er seine Knechte* zu den Weingärtnern, um seine Früchte zu empfangen.", footnotes: ["w. Sklaven; so auch V. 35 und 36"] },
      { number: 35, text: "Und die Weingärtner nahmen seine Knechte, einen schlugen sie, einen anderen töteten sie, einen anderen steinigten sie*.", footnotes: ["℘ Kap. 22,6; 23,37; 2Chr 24,21; Neh 9,26; Lk 6,23"] },
      { number: 36, text: "Wiederum sandte er andere Knechte*, mehr als die ersten; und sie taten ihnen ebenso*.", footnotes: ["℘ Kap. 22,4", "℘ 2Chr 36,15.16"] },
      { number: 37, text: "Zuletzt aber sandte er seinen Sohn zu ihnen, indem er sagte: Sie werden sich vor meinem Sohn scheuen!" },
      { number: 38, text: "Als aber die Weingärtner den Sohn sahen, sprachen sie untereinander: Dieser ist der Erbe*. Kommt, lasst uns ihn töten und sein Erbe in Besitz nehmen*!", footnotes: ["℘ Hebr 1,1.2", "℘ Kap. 26,3.4"] },
      { number: 39, text: "Und sie nahmen ihn, warfen ihn zum Weinberg hinaus und töteten ihn." },
      { number: 40, text: "Wenn nun der Herr des Weinbergs kommt, was wird er jenen Weingärtnern tun?" },
      { number: 41, text: "Sie sagen zu ihm: Er wird jene Übeltäter übel umbringen*, und den Weinberg wird er an andere Weingärtner verpachten, die ihm die Früchte abgeben werden zu ihrer Zeit.", footnotes: ["℘ Lk 19,27"] },
      { number: 42, text: "Jesus spricht zu ihnen: Habt ihr nie in den Schriften gelesen: »Der Stein, den die Bauleute verworfen haben, dieser ist zum Eckstein* geworden*; von dem Herrn her ist er dies geworden, und er ist wunderbar in unseren Augen«*?", footnotes: ["w. zum Haupt der Ecke", "℘ Jes 28,16; Eph 2,20; 1Petr 2,4.7", "℘ Ps 118,22.23; Apg 4,11"] },
      { number: 43, text: "Deswegen sage ich euch: Das Reich* Gottes wird von euch weggenommen und einer Nation gegeben werden, die seine Früchte bringen wird*.", footnotes: ["o. die/der Königsherrschaft", "℘ Apg 13,46"] },
      { number: 44, text: "Und wer auf diesen Stein fällt, wird zerschmettert werden*; aber auf wen er fallen wird, den wird er zermalmen*.", footnotes: ["℘ Jes 8,15", "℘ Dan 2,45"] },
      { number: 45, text: "Und als die Hohenpriester und die Pharisäer seine Gleichnisse gehört hatten, erkannten sie, dass er von ihnen redete*.", footnotes: ["℘ Jes 5,7"] },
      { number: 46, text: "Und als sie ihn zu greifen suchten*, fürchteten sie die Volksmengen, denn sie hielten ihn für einen Propheten*.", footnotes: ["℘ Kap. 12,14; Lk 19,47", "℘ V. 11; Apg 4,21"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Und Jesus begann* und redete wieder in Gleichnissen zu ihnen und sprach: *", heading: "Gleichnis vom Hochzeitsmahl", footnotes: ["℘ vgl. Lk 14,16-24", "w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "℘ ⇨Esyn: Synopse Nr. 279"] },
      { number: 2, text: "Mit dem Reich* der Himmel ist es wie* mit einem König, der seinem Sohn <die> Hochzeit bereitete.", footnotes: ["o. die/der Königsherrschaft", "w. Das Reich der Himmel ist verglichen worden (o. zu vergleichen)"] },
      { number: 3, text: "Und er sandte seine Knechte* aus, um die Eingeladenen zur Hochzeit zu rufen; und sie wollten nicht kommen.", footnotes: ["w. Sklaven; so auch V. 4—10"] },
      { number: 4, text: "Wiederum sandte er andere Knechte* aus und sprach: Sagt den Eingeladenen: Siehe, mein Mahl habe ich bereitet, meine Ochsen und mein Mastvieh sind geschlachtet, und alles ist bereit. Kommt zur Hochzeit!", footnotes: ["℘ Kap. 21,36"] },
      { number: 5, text: "Sie aber kümmerten sich nicht <darum>* und gingen weg, der eine auf seinen Acker, der andere an seinen Handel*.", footnotes: ["o. missachteten <es>", "℘ Spr 1,24.25"] },
      { number: 6, text: "Die Übrigen aber ergriffen seine Knechte, misshandelten und töteten sie*.", footnotes: ["℘ Kap. 21,35"] },
      { number: 7, text: "Der König aber wurde zornig und sandte seine Truppen aus, brachte jene Mörder um* und steckte ihre Stadt in Brand.", footnotes: ["℘ Lk 20,16"] },
      { number: 8, text: "Dann sagt er zu seinen Knechten: Die Hochzeit ist zwar bereit, aber die Eingeladenen waren nicht würdig." },
      { number: 9, text: "So geht nun hin auf die Kreuzwege der Landstraßen, und so viele immer ihr finden werdet, ladet zur Hochzeit ein." },
      { number: 10, text: "Und jene Knechte gingen aus auf die Landstraßen und brachten alle zusammen, die sie fanden, Böse wie Gute. Und der Hochzeitssaal wurde voll von Gästen." },
      { number: 11, text: "Als aber der König hereinkam, die Gäste zu besehen, sah er dort einen Menschen, der nicht mit einem Hochzeitskleid bekleidet war." },
      { number: 12, text: "Und er spricht zu ihm: Freund, wie bist du hier hereingekommen, da du kein Hochzeitskleid hast? Er aber verstummte*.", footnotes: ["℘ Ps 107,42"] },
      { number: 13, text: "Da sprach der König zu den Dienern: Bindet ihm Füße und Hände, und werft ihn hinaus in die äußere Finsternis; da wird das Weinen und das Zähneknirschen sein*.", footnotes: ["℘ Kap. 8,12"] },
      { number: 14, text: "Denn viele sind Berufene, wenige aber Auserwählte*.", footnotes: ["℘ Kap. 20,16"] },
      { number: 15, text: "*Dann gingen die Pharisäer hin und hielten Rat*, wie sie ihn bei einem Ausspruch fangen könnten*.", heading: "Die Frage nach der Steuer", footnotes: ["℘ Mk 12,13-17; Lk 20,20-26", "℘ Ps 56,7", "℘ Kap. 19,3; Lk 11,54; Joh 8,6 ⇨Esyn: Synopse Nr. 280"] },
      { number: 16, text: "Und sie senden ihre Jünger mit den Herodianern* zu ihm und sagen: Lehrer, wir wissen, dass du wahrhaftig bist und den Weg Gottes in Wahrheit lehrst und dich um niemand kümmerst, denn du siehst nicht auf die Person der Menschen*.", footnotes: ["Anhänger des Herodes Antipas; vgl. Anm. zu Kap. 14,1", "℘ 3Mo 19,15; Apg 10,34"] },
      { number: 17, text: "Sage uns nun, was denkst du: Ist es erlaubt, dem Kaiser Steuer zu geben, oder nicht?" },
      { number: 18, text: "Da aber Jesus ihre Bosheit erkannte*, sprach er: Was versucht ihr mich, Heuchler?", footnotes: ["℘ Kap. 9,4; Mk 2,8"] },
      { number: 19, text: "Zeigt mir die Steuermünze! Sie aber überreichten ihm einen Denar." },
      { number: 20, text: "Und er spricht zu ihnen: Wessen Bild und Aufschrift ist das?" },
      { number: 21, text: "Sie sagen zu ihm: Des Kaisers. Da spricht er zu ihnen: Gebt denn dem Kaiser, was des Kaisers ist*, und Gott, was Gottes ist.", footnotes: ["℘ Röm 13,7; 1Petr 2,13"] },
      { number: 22, text: "Und als sie <das> hörten, wunderten sie sich und ließen ihn und gingen weg*.", footnotes: ["℘ Joh 8,9"] },
      { number: 23, text: "*An jenem Tag kamen Sadduzäer* zu ihm, die da sagen, es gebe keine Auferstehung*; und sie fragten ihn", heading: "Die Frage nach der Auferstehung", footnotes: ["℘ Mk 12,18-27; Lk 20,27-40", "religiöse Partei, der u. a. die vornehmen Priesterfamilien angehörten; s. auch Anm. zu Kap. 3,7", "℘ Kap. 16,12; Apg 23,8 ⇨Esyn: Synopse Nr. 281"] },
      { number: 24, text: "und sprachen: Lehrer, Mose hat gesagt: Wenn jemand stirbt und keine Kinder hat, so soll sein Bruder seine Frau heiraten und soll seinem Bruder Nachkommenschaft* erwecken*.", footnotes: ["w. Samen", "℘ 1Mo 38,8; 5Mo 25,5.6"] },
      { number: 25, text: "Es waren aber bei uns sieben Brüder. Und der erste heiratete und starb; und weil er keine Nachkommenschaft* hatte, hinterließ er seine Frau seinem Bruder.", footnotes: ["w. Samen"] },
      { number: 26, text: "Ebenso auch der zweite und der dritte, bis auf den siebten." },
      { number: 27, text: "Zuletzt aber von allen starb die Frau." },
      { number: 28, text: "Wessen Frau von den sieben wird sie nun in der Auferstehung sein? Denn alle hatten sie." },
      { number: 29, text: "Jesus aber antwortete und sprach zu ihnen: Ihr irrt*, weil ihr die Schriften nicht kennt noch die Kraft Gottes;", footnotes: ["℘ Ps 95,10"] },
      { number: 30, text: "denn in der Auferstehung heiraten sie nicht, noch werden sie verheiratet, sondern sie sind wie Engel im Himmel." },
      { number: 31, text: "Was aber die Auferstehung der Toten betrifft: Habt ihr nicht gelesen, was zu euch geredet ist von Gott, der da spricht:" },
      { number: 32, text: "»Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs«*? Gott ist nicht der Gott von Toten, sondern von Lebenden.", footnotes: ["℘ 2Mo 3,6; Apg 7,32; Hebr 11,16"] },
      { number: 33, text: "Und als die Volksmengen es hörten, erstaunten sie über seine Lehre*.", footnotes: ["℘ Kap. 7,28"] },
      { number: 34, text: "*Als aber die Pharisäer hörten, dass er die Sadduzäer zum Schweigen gebracht hatte, versammelten sie sich miteinander. *", heading: "Die Frage nach dem größten Gebot", footnotes: ["℘ Mk 12,28-34; vgl. Lk 10,25-28", "℘ ⇨Esyn: Synopse Nr. 282"] },
      { number: 35, text: "Und es fragte einer von ihnen, ein Gesetzesgelehrter, und versuchte ihn und sprach*:", footnotes: ["℘ Kap. 19,3"] },
      { number: 36, text: "Lehrer, welches ist das größte Gebot im Gesetz*?", footnotes: ["w. welches Gebot <ist> groß im Gesetz"] },
      { number: 37, text: "Er aber sprach zu ihm: »Du sollst den Herrn, deinen Gott, lieben mit deinem ganzen Herzen und mit deiner ganzen Seele und mit deinem ganzen Verstand*.«", footnotes: ["℘ 5Mo 6,5; 10,12"] },
      { number: 38, text: "Dies ist das größte* und erste Gebot.", footnotes: ["w. große"] },
      { number: 39, text: "Das zweite aber ist ihm gleich: »Du sollst deinen Nächsten lieben wie dich selbst*.«", footnotes: ["℘ Kap. 5,43; 3Mo 19,18"] },
      { number: 40, text: "An diesen zwei Geboten hängt das ganze Gesetz und die Propheten*.", footnotes: ["℘ Kap. 7,12; Röm 13,10; 1Jo 4,21"] },
      { number: 41, text: "*Als aber die Pharisäer versammelt waren, fragte Jesus sie*", heading: "Die Frage nach dem Christus", footnotes: ["℘ Mk 12,35-37; Lk 20,41-44", "℘ Kap. 21,24 ⇨Esyn: Synopse Nr. 283"] },
      { number: 42, text: "und sagte: Was haltet ihr von dem Christus? Wessen Sohn ist er? Sie sagen zu ihm: Davids*.", footnotes: ["℘ Kap. 1,1; 9,27; Jer 23,5; Röm 1,3; 2Tim 2,8"] },
      { number: 43, text: "Er spricht zu ihnen: Wie nennt David ihn denn im Geist* Herr, indem er sagt:", footnotes: ["℘ 2Petr 1,21"] },
      { number: 44, text: "»Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde lege unter deine Füße«*?", footnotes: ["℘ Ps 110,1; Mk 16,19; Apg 2,34.35; 1Kor 15,25; Hebr 1,13"] },
      { number: 45, text: "Wenn nun David ihn Herr nennt, wie ist er sein Sohn*?", footnotes: ["℘ Offb 22,16"] },
      { number: 46, text: "Und niemand konnte ihm ein Wort antworten*, noch wagte jemand von dem Tag an, ihn weiter zu befragen*.", footnotes: ["℘ Lk 14,4.6", "℘ Mk 12,34; Lk 20,40"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Dann redete Jesus zu den Volksmengen und zu seinen Jüngern *", heading: "Warnung vor den Schriftgelehrten und Pharisäern", footnotes: ["℘ Mk 12,38-40; Lk 20,45-47", "℘ ⇨Esyn: Synopse Nr. 284"] },
      { number: 2, text: "und sprach: Auf Moses Lehrstuhl haben sich die Schriftgelehrten und die Pharisäer gesetzt*.", footnotes: ["℘ Joh 9,28"] },
      { number: 3, text: "Alles nun, was sie euch sagen, tut und haltet*; aber handelt nicht nach ihren Werken! Denn sie sagen es und tun es nicht*.", footnotes: ["℘ 5Mo 17,10", "℘ Mal 2,7.8; Röm 2,17-23"] },
      { number: 4, text: "Sie binden aber schwere und schwer zu tragende Lasten zusammen und legen sie auf die Schultern der Menschen, sie selbst aber wollen sie nicht mit ihrem Finger bewegen*.", footnotes: ["℘ Lk 11,46"] },
      { number: 5, text: "Alle ihre Werke aber tun sie, um sich vor den Menschen sehen zu lassen*; denn sie machen ihre Gebetsriemen* breit und die Quasten* groß.", footnotes: ["℘ Kap. 6,1.2", "Das sind lederne Bänder mit Kapseln, die vier Pergamentstreifen mit Schriftstellen aus 2. und 5. Mose enthielten. Sie wurden beim Gebet an Stirn und linkem Arm getragen.\n℘ 2Mo 13,9.16; 5Mo 6,8; 11,18", "zur Bedeutung der Quasten siehe 4Mo 15,37—40\n℘ Kap. 9,20"] },
      { number: 6, text: "Sie lieben aber den ersten Platz bei den Gastmählern* und die ersten Sitze in den Synagogen", footnotes: ["Das griech. Wort bezeichnet die abendliche Hauptmahlzeit, zu der oft Gäste geladen wurden.\n℘ Lk 14,7"] },
      { number: 7, text: "und die Begrüßungen auf den Märkten* und von den Menschen Rabbi* genannt zu werden*.", footnotes: ["℘ Lk 11,43", "d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum", "℘ Joh 5,44"] },
      { number: 8, text: "Ihr aber, lasst ihr euch nicht Rabbi nennen! Denn einer ist euer Lehrer*, ihr alle aber seid Brüder.", footnotes: ["℘ Joh 13,13"] },
      { number: 9, text: "Ihr sollt auch nicht <jemanden> auf der Erde euren Vater nennen; denn einer ist euer Vater, <nämlich> der im Himmel*.", footnotes: ["w. der himmlische\n℘ Kap. 6,9"] },
      { number: 10, text: "Lasst euch auch nicht Meister nennen; denn einer ist euer Meister, der Christus." },
      { number: 11, text: "Der Größte* aber unter euch soll* euer Diener sein*.", footnotes: ["w. Der Größere", "o. wird", "℘ Kap. 20,26.27; Lk 22,26 ⇨Esyn: Synopse Nr. 313"] },
      { number: 12, text: "Wer sich aber selbst erhöhen wird, wird erniedrigt werden; und wer sich selbst erniedrigen wird, wird erhöht werden*.", footnotes: ["℘ Kap. 18,4; 1Sam 15,17; Spr 29,23; Hes 17,24; 21,31; Lk 14,11; Phil 2,8.9; Jak 4,10; 1Petr 5,6"] },
      { number: 13, text: "*Wehe aber euch, Schriftgelehrte und Pharisäer, Heuchler*! Denn ihr verschließt das Reich* der Himmel vor den Menschen; denn ihr geht nicht hinein*, und die, die hineingehen wollen, lasst ihr <auch> nicht hineingehen.", heading: "Weherufe gegen die Schriftgelehrten und Pharisäer", footnotes: ["℘ vgl. Lk 11,38-52", "℘ Kap. 15,7", "o. die Königsherrschaft", "℘ Kap. 5,20"] },
      { number: 14, text: "[T>]*", footnotes: ["Mehrere Handschr. fügen hinzu: Wehe euch, Schriftgelehrte und Pharisäer, Heuchler! Denn ihr verschlingt die Häuser der Witwen und haltet zum Vorwand lange Gebete; deswegen werdet ihr ein schwereres Gericht empfangen."] },
      { number: 15, text: "Wehe euch, Schriftgelehrte und Pharisäer, Heuchler*! Denn ihr durchzieht das Meer und das trockene <Land>, um einen Proselyten* zu machen; und wenn er es geworden ist, so macht ihr ihn zu einem Sohn der Hölle, doppelt so schlimm wie ihr.", footnotes: ["℘ Kap. 15,7", "durch Anerkennung des Gesetzes, Beschneidung und Proselytentaufe in die Gemeinde Israels aufgenommene Heiden"] },
      { number: 16, text: "Wehe euch, ihr blinden Führer*! Die ihr sagt: Wenn jemand bei dem Tempel schwören wird, ist das nichts; wenn aber jemand bei dem Gold des Tempels schwören wird, ist er gebunden*.", footnotes: ["℘ Kap. 15,14; Joh 9,39", "d. h. ist verpflichtet, den Eid zu halten; s. auch V. 18"] },
      { number: 17, text: "Narren und Blinde! Was ist denn größer, das Gold oder der Tempel, der das Gold heiligt?" },
      { number: 18, text: "Und: Wenn jemand bei dem Altar schwören wird, ist das nichts; wenn aber jemand bei der Gabe schwören wird, die auf ihm ist, so ist er gebunden." },
      { number: 19, text: "Blinde*! Was ist denn größer, die Gabe oder der Altar, der die Gabe heiligt*?", footnotes: ["℘ Kap. 15,14; Joh 9,39", "℘ 2Mo 29,37"] },
      { number: 20, text: "Wer nun bei dem Altar schwört, schwört bei ihm und bei allem, was auf ihm ist." },
      { number: 21, text: "Und wer bei dem Tempel schwört, schwört bei ihm und bei dem, der ihn bewohnt*.", footnotes: ["℘ 1Kö 8,13"] },
      { number: 22, text: "Und wer bei dem Himmel schwört, schwört bei dem Thron Gottes und bei dem, der darauf sitzt*.", footnotes: ["℘ Kap. 5,34"] },
      { number: 23, text: "Wehe euch, Schriftgelehrte und Pharisäer, Heuchler*! Denn ihr verzehntet* die Minze* und den Dill und den Kümmel* und habt die wichtigeren Dinge des Gesetzes beiseite gelassen: das Recht* und die Barmherzigkeit* und den Glauben; diese hättet ihr tun und jene nicht lassen sollen.", footnotes: ["℘ Kap. 15,7", "℘ Lk 18,12", "ein Gewürzkraut", "℘ 3Mo 27,30; 5Mo 14,22", "o. Gericht", "℘ Kap. 9,13; Sach 7,9; Lk 6,36"] },
      { number: 24, text: "Ihr blinden Führer*, die ihr die Mücke seiht, das Kamel aber verschluckt*!", footnotes: ["℘ Kap. 15,14; Joh 9,39", "℘ Kap. 7,4"] },
      { number: 25, text: "Wehe euch, Schriftgelehrte und Pharisäer, Heuchler*! Denn ihr reinigt das Äußere des Bechers und der Schüssel*, inwendig aber sind sie voller Raub und Unenthaltsamkeit.", footnotes: ["℘ Kap. 15,7", "℘ Mk 7,4"] },
      { number: 26, text: "Blinder Pharisäer*! Reinige zuerst das Inwendige des Bechers, damit auch sein Auswendiges rein werde.", footnotes: ["℘ Kap. 15,14; Joh 9,39"] },
      { number: 27, text: "Wehe euch, Schriftgelehrte und Pharisäer, Heuchler*! Denn ihr gleicht übertünchten Gräbern*, die von außen zwar schön scheinen, inwendig aber voll von Totengebeinen und aller Unreinheit sind*.", footnotes: ["℘ Kap. 15,7", "Gräber, in Palästina meistens in Felsen ausgehauen, wurden weiß getüncht, damit Fremde sich nicht durch Berührung verunreinigten.", "℘ Apg 23,3"] },
      { number: 28, text: "So scheint auch ihr von außen zwar gerecht vor den Menschen, von innen aber seid ihr voller Heuchelei und Gesetzlosigkeit*.", footnotes: ["℘ Lk 12,1"] },
      { number: 29, text: "Wehe euch, Schriftgelehrte und Pharisäer, Heuchler*! Denn ihr baut die Gräber der Propheten und schmückt die Grabmäler der Gerechten", footnotes: ["℘ Kap. 15,7"] },
      { number: 30, text: "und sagt: Wären wir in den Tagen unserer Väter gewesen, so würden wir uns nicht an dem Blut der Propheten schuldig gemacht haben*.", footnotes: ["w. so wären wir nicht ihre Teilhaber am Blut der Propheten gewesen"] },
      { number: 31, text: "So gebt ihr euch selbst Zeugnis, dass ihr Söhne derer seid, welche die Propheten ermordet haben*.", footnotes: ["℘ Kap. 5,12"] },
      { number: 32, text: "Und ihr, macht <nur> das Maß eurer Väter voll*!", footnotes: ["℘ 1Thes 2,15.16"] },
      { number: 33, text: "Schlangen! Otternbrut*! Wie solltet ihr dem Gericht der Hölle entfliehen?", footnotes: ["℘ Kap. 3,7; Lk 3,7"] },
      { number: 34, text: "Deswegen siehe, ich sende zu euch Propheten und Weise und Schriftgelehrte; einige von ihnen werdet ihr töten und kreuzigen, und einige von ihnen werdet ihr in euren Synagogen geißeln* und werdet sie verfolgen von Stadt zu Stadt*,", footnotes: ["Die Strafe des Geißelns wurde nach dem Gesetz (vgl. 5Mo 25,3) vollzogen, und zwar in den Synagogen; s. auch Anm. zu Kap. 4,23.\n℘ Kap. 10,17; Mk 13,9", "℘ Kap. 10,23"] },
      { number: 35, text: "damit über euch komme alles gerechte Blut, das auf der Erde vergossen wurde, von dem Blut Abels, des Gerechten*, bis zu dem Blut Secharjas, des Sohnes Berechjas, den ihr zwischen dem Tempel und dem Altar ermordet habt*.", footnotes: ["℘ 1Mo 4,8; Hebr 11,4; 1Jo 3,12", "℘ 2Chr 24,21"] },
      { number: 36, text: "Wahrlich, ich sage euch, dies alles wird über dieses Geschlecht kommen*.", footnotes: ["℘ Kap. 24,34; Mk 13,30"] },
      { number: 37, text: "*Jerusalem, Jerusalem, die da tötet die Propheten und steinigt, die zu ihr gesandt sind*! Wie oft habe ich deine Kinder versammeln wollen, wie eine Henne ihre Küken versammelt unter ihre Flügel, und ihr habt nicht gewollt*!", heading: "Klage über Jerusalem", footnotes: ["℘ vgl. Lk 13,34.35", "℘ Kap. 21,35.36; Mk 12,3-5; Apg 7,59", "℘ Jes 65,2; Jer 5,3; Joh 5,40 ⇨Esyn: Synopse Nr. 285"] },
      { number: 38, text: "Siehe, euer Haus wird euch öde gelassen*;", footnotes: ["℘ Kap. 24,2; 1Kö 9,7.8; Ps 69,26; Lk 19,44"] },
      { number: 39, text: "denn ich sage euch: Ihr werdet mich von jetzt an nicht sehen, bis ihr sprecht: »Gepriesen <sei>, der da kommt im Namen des Herrn!«*", footnotes: ["℘ Kap. 21,9; Ps 118,26; Joh 12,13"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "*Und Jesus trat hinaus und ging von dem Tempel weg; und seine Jünger traten zu <ihm>, um ihn auf die Gebäude des Tempels aufmerksam zu machen. *", heading: "Endzeitrede: Tempelzerstörung und Drangsale der Endzeit", footnotes: ["℘ Mk 13,1-23; V. 1-19: Lk 21,5-12.16-23", "℘ ⇨Esyn: Synopse Nr. 287"] },
      { number: 2, text: "Er aber antwortete und sprach zu ihnen: Seht ihr nicht dies alles? Wahrlich, ich sage euch: Hier wird nicht ein Stein auf dem anderen* gelassen werden, der nicht abgebrochen werden wird*. —", footnotes: ["w. Stein auf Stein", "℘ Kap. 23,38"] },
      { number: 3, text: "Als er aber auf dem Ölberg saß, traten seine Jünger für sich allein zu ihm und sprachen: Sage uns, wann wird das sein, und was ist das Zeichen deiner Ankunft und der Vollendung des Zeitalters*?", footnotes: ["griech. Äon\n℘ Kap. 13,39 ⇨Esyn: Synopse Nr. 288"] },
      { number: 4, text: "Und Jesus antwortete und sprach zu ihnen: Seht zu, dass euch niemand verführe*!", footnotes: ["o. irreführe\n℘ 2Thes 2,3"] },
      { number: 5, text: "Denn viele werden unter meinem Namen kommen* und sagen: Ich bin der Christus! Und sie werden viele verführen*.", footnotes: ["℘ Jer 14,14", "o. irreführen\n℘ V. 11; Joh 5,43"] },
      { number: 6, text: "Ihr werdet aber von Kriegen und Kriegsgerüchten hören. Seht zu, erschreckt nicht! Denn es muss geschehen, aber es ist noch nicht das Ende." },
      { number: 7, text: "Denn es wird sich Nation gegen Nation erheben und Königreich gegen Königreich, und es werden Hungersnöte und Erdbeben da und dort sein*.", footnotes: ["℘ Jes 19,2"] },
      { number: 8, text: "Alles dies aber ist der Anfang der Wehen." },
      { number: 9, text: "Dann werden sie euch in Bedrängnis überliefern* und euch töten*; und ihr werdet von allen Nationen gehasst werden um meines Namens willen*.", footnotes: ["℘ Kap. 10,17", "℘ Joh 16,2", "℘ Kap. 10,21.22 ⇨Esyn: Synopse Nr. 289"] },
      { number: 10, text: "Und dann werden viele verleitet* werden und werden einander überliefern und einander hassen;", footnotes: ["Das griech. Wort bedeutet auch: Anstoß nehmen, sich ärgern."] },
      { number: 11, text: "und viele falsche Propheten werden aufstehen* und werden viele verführen*;", footnotes: ["℘ 2Petr 2,1", "o. irreführen\n℘ V. 5; Kap. 7,15; Apg 5,36.37; 1Tim 4,1.2"] },
      { number: 12, text: "und weil die Gesetzlosigkeit überhandnimmt, wird die Liebe der meisten* erkalten*;", footnotes: ["℘ Dan 9,27", "℘ 2Tim 3,2-4; Offb 2,4"] },
      { number: 13, text: "wer aber ausharrt bis ans Ende, der wird gerettet werden*.", footnotes: ["℘ Kap. 10,22; Hebr 3,6"] },
      { number: 14, text: "Und dieses Evangelium des Reiches* wird gepredigt werden auf dem ganzen Erdkreis, allen Nationen zu einem Zeugnis*, und dann wird das Ende kommen.", footnotes: ["o. der Königsherrschaft", "℘ Kap. 10,18"] },
      { number: 15, text: "Wenn ihr nun den Gräuel der Verwüstung, von dem durch Daniel, den Propheten, geredet ist*, an heiliger Stätte stehen seht* — wer es liest, der merke auf! —,", footnotes: ["℘ Dan 9,27; 11,31; 12,11", "℘ Apg 6,13 ⇨Esyn: Synopse Nr. 290"] },
      { number: 16, text: "dann sollen die in Judäa auf die Berge fliehen;" },
      { number: 17, text: "wer auf dem Dach ist, soll nicht hinabsteigen, um die <Sachen> aus seinem Haus zu holen*;", footnotes: ["℘ Lk 17,31"] },
      { number: 18, text: "und wer auf dem Feld ist, soll nicht zurückkehren, um seinen Mantel zu holen*.", footnotes: ["℘ Lk 17,31"] },
      { number: 19, text: "Wehe aber den Schwangeren und den Stillenden in jenen Tagen!" },
      { number: 20, text: "Betet aber, dass eure Flucht nicht im Winter geschehe noch am Sabbat!" },
      { number: 21, text: "Denn dann wird große Bedrängnis sein, wie sie von Anfang der Welt bis jetzt nicht gewesen ist und auch nie sein wird*.", footnotes: ["℘ Dan 12,1; Offb 7,14"] },
      { number: 22, text: "Und wenn jene Tage nicht verkürzt würden, so würde kein Fleisch gerettet werden; aber um der Auserwählten* willen werden jene Tage verkürzt werden.", footnotes: ["℘ Jes 65,9"] },
      { number: 23, text: "Wenn dann jemand zu euch sagt: Siehe, hier ist der Christus, oder dort! so glaubt es nicht*!", footnotes: ["℘ Lk 17,23 ⇨Esyn: Synopse Nr. 291"] },
      { number: 24, text: "Denn es werden falsche Christusse* und falsche Propheten aufstehen und werden große Zeichen und Wunder tun*, um, wenn möglich, auch die Auserwählten zu verführen*.", footnotes: ["℘ 1Jo 2,18", "℘ 2Thes 2,9; Offb 13,13", "℘ V. 11; Joh 5,43 ⇨Esyn: Synopse Nr. 289"] },
      { number: 25, text: "Siehe, ich habe es euch vorhergesagt*.", footnotes: ["℘ Kap. 28,7; Joh 14,29; 2Petr 3,17"] },
      { number: 26, text: "Wenn sie nun zu euch sagen: Siehe, er ist in der Wüste!, so geht nicht hinaus! Siehe, in den Kammern!, so glaubt es nicht*!", footnotes: ["℘ Lk 17,23"] },
      { number: 27, text: "Denn wie der Blitz ausfährt von Osten und bis nach Westen leuchtet, so wird die Ankunft des Sohnes des Menschen sein*.", footnotes: ["℘ Lk 17,24"] },
      { number: 28, text: "Wo das Aas ist, da werden sich die Adler* versammeln*.", footnotes: ["o. Geier", "℘ Hi 39,30; Hab 1,8; Lk 17,36"] },
      { number: 29, text: "*Aber gleich nach der Bedrängnis jener Tage wird die Sonne verfinstert werden und der Mond seinen Schein nicht geben*, und die Sterne werden vom Himmel fallen*, und die Kräfte der Himmel werden erschüttert werden.", heading: "Endzeitrede: Ankunft des Menschensohnes", footnotes: ["℘ Mk 13,24-27; Lk 21,25-27", "℘ Jes 13,10; Hes 32,7.8; Joe 4,15; Am 5,20", "℘ Jes 34,4; Offb 6,13 ⇨Esyn: Synopse Nr. 292"] },
      { number: 30, text: "Und dann wird das Zeichen des Sohnes des Menschen am Himmel erscheinen*; und dann werden wehklagen alle Stämme des Landes*, und sie werden den Sohn des Menschen kommen sehen auf den Wolken des Himmels mit großer Macht und Herrlichkeit*.", footnotes: ["℘ Dan 7,13", "℘ Sach 12,10-14; Offb 1,7", "℘ Kap. 16,27; Ps 68,35; Offb 19,16"] },
      { number: 31, text: "Und er wird seine Engel aussenden* mit starkem Posaunenschall*, und sie werden seine Auserwählten versammeln von den vier Winden her*, von dem einen Ende der Himmel bis zu ihrem anderen Ende*.", footnotes: ["℘ Kap. 13,41", "℘ Jes 27,13", "℘ Offb 7,1", "℘ 5Mo 30,4; Jes 11,12"] },
      { number: 32, text: "*Von dem Feigenbaum aber lernt das Gleichnis: Wenn sein Zweig schon weich geworden ist und die Blätter hervortreibt, so erkennt ihr, dass der Sommer nahe ist. *", heading: "Endzeitrede: Ermahnung zur Wachsamkeit", footnotes: ["℘ Mk 13,28-37; V. 32-35: Lk 21,29-33; V. 37-41: Lk 17,26-35; V. 42-44: Lk 12,39.40", "℘ ⇨Esyn: Synopse Nr. 293"] },
      { number: 33, text: "So sollt auch ihr, wenn ihr dies alles seht, erkennen, dass es* nahe an der Tür ist*.", footnotes: ["o. er", "℘ Jak 5,9"] },
      { number: 34, text: "Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis dies alles geschehen ist*.", footnotes: ["℘ Kap. 23,36"] },
      { number: 35, text: "Der Himmel und die Erde werden vergehen*, meine Worte aber sollen nicht vergehen*.", footnotes: ["℘ Ps 102,27; Jes 51,6; Hebr 1,11; 2Petr 3,10.12", "℘ Kap. 5,18"] },
      { number: 36, text: "Von jenem Tag aber und jener Stunde weiß niemand*, auch nicht die Engel in den Himmeln, auch nicht der Sohn, sondern der Vater allein*.", footnotes: ["℘ Kap. 25,13", "℘ Sach 14,7; Apg 1,7"] },
      { number: 37, text: "Aber wie die Tage Noahs <waren>*, so wird auch die Ankunft des Sohnes des Menschen sein.", footnotes: ["℘ 1Mo 6,11-13 ⇨Esyn: Synopse Nr. 296"] },
      { number: 38, text: "Denn wie sie in jenen Tagen vor der Flut waren: — sie aßen und tranken, sie heirateten und verheirateten bis zu dem Tag, da Noah in die Arche ging*", footnotes: ["℘ 1Mo 7,7"] },
      { number: 39, text: "und sie es nicht erkannten*, bis die Flut kam und alle wegraffte* —, so wird auch die Ankunft des Sohnes des Menschen sein.", footnotes: ["℘ 1Petr 3,20", "℘ 1Mo 7,21-23"] },
      { number: 40, text: "Dann werden zwei auf dem Feld sein, einer wird genommen und einer gelassen;" },
      { number: 41, text: "zwei <Frauen> werden an dem Mühlstein mahlen, eine wird genommen und eine gelassen." },
      { number: 42, text: "Wacht also! Denn ihr wisst nicht, an welchem Tag euer Herr kommt*.", footnotes: ["℘ 1Kor 16,13"] },
      { number: 43, text: "Das aber erkennt: Wenn der Hausherr gewusst hätte, in welcher Wache* der Dieb kommt, so hätte er wohl gewacht und nicht zugelassen, dass in sein Haus eingebrochen wird*.", footnotes: ["In neutestamentl. Zeit galt die griech.-röm. Einteilung der Nacht in vier Nachtwachen.", "℘ 1Thes 5,2; 2Petr 3,10; Offb 3,3"] },
      { number: 44, text: "Deshalb seid auch ihr bereit! Denn in der Stunde, in der ihr es nicht meint, kommt der Sohn des Menschen." },
      { number: 45, text: "*Wer ist nun der treue und kluge Knecht*, den sein Herr über seine Dienerschaft gesetzt hat, um ihnen die Speise zu geben zur rechten Zeit*?", heading: "Endzeitrede: Gleichnis vom treuen und untreuen Knecht", footnotes: ["℘ Lk 12,41-46", "w. Sklave; so auch V. 46—50", "℘ Kap. 13,52 ⇨Esyn: Synopse Nr. 297"] },
      { number: 46, text: "Glückselig jener Knecht, den sein Herr, wenn er kommt, bei solchem Tun finden wird!" },
      { number: 47, text: "Wahrlich, ich sage euch, er wird ihn über seine ganze Habe setzen*.", footnotes: ["℘ Kap. 25,21.23; Lk 19,17"] },
      { number: 48, text: "Wenn aber jener <als> böser Knecht in seinem Herzen sagt: Mein Herr lässt auf sich warten*,", footnotes: ["w. säumt, o. zögert\n℘ Pred 8,11; 2Petr 3,3.4"] },
      { number: 49, text: "und anfängt, seine Mitknechte zu schlagen, und isst und trinkt mit den Betrunkenen*,", footnotes: ["℘ 1Thes 5,7"] },
      { number: 50, text: "so wird der Herr jenes Knechtes kommen an einem Tag, an dem er es nicht erwartet, und in einer Stunde, die er nicht weiß*,", footnotes: ["℘ Kap. 25,13; Mk 13,33"] },
      { number: 51, text: "und wird ihn entzweischneiden und ihm sein Teil festsetzen bei den Heuchlern; da wird das Weinen und das Zähneknirschen sein*.", footnotes: ["℘ Kap. 8,12"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Dann wird es mit dem Reich* der Himmel sein wie* mit zehn Jungfrauen, die ihre Lampen nahmen und hinausgingen, dem Bräutigam entgegen*.", heading: "Endzeitrede: Gleichnis von den zehn Jungfrauen", footnotes: ["o. der Königsherrschaft", "w. Dann wird das Reich der Himmel verglichen werden (o. zu vergleichen sein)", "℘ Ps 45,15 ⇨Esyn: Synopse Nr. 298"] },
      { number: 2, text: "Fünf aber von ihnen waren töricht und fünf klug." },
      { number: 3, text: "Denn die Törichten nahmen ihre Lampen und nahmen kein Öl mit sich;" },
      { number: 4, text: "die Klugen aber nahmen Öl in ihren Gefäßen samt ihren Lampen*.", footnotes: ["℘ Lk 12,35.36"] },
      { number: 5, text: "Als aber der Bräutigam auf sich warten ließ*, wurden sie alle schläfrig und schliefen ein*.", footnotes: ["w. säumte, o. zögerte", "℘ Mk 13,36"] },
      { number: 6, text: "Um Mitternacht aber entstand ein Geschrei: Siehe, der Bräutigam! Geht hinaus, ihm entgegen!" },
      { number: 7, text: "Da standen alle jene Jungfrauen auf und schmückten ihre Lampen." },
      { number: 8, text: "Die Törichten aber sprachen zu den Klugen: Gebt uns von eurem Öl! Denn unsere Lampen erlöschen." },
      { number: 9, text: "Die Klugen aber antworteten und sagten: Nein, damit es nicht etwa für uns und euch nicht ausreiche! Geht lieber hin zu den Verkäufern und kauft für euch selbst!" },
      { number: 10, text: "Als sie aber hingingen, zu kaufen, kam der Bräutigam; und die bereit waren, gingen mit ihm hinein zur Hochzeit, und die Tür wurde verschlossen*.", footnotes: ["℘ 1Mo 7,16"] },
      { number: 11, text: "Später aber kommen auch die übrigen Jungfrauen und sagen: Herr, Herr, öffne uns*!", footnotes: ["℘ Kap. 7,22"] },
      { number: 12, text: "Er aber antwortete und sprach: Wahrlich, ich sage euch, ich kenne euch nicht*.", footnotes: ["℘ Kap. 7,23"] },
      { number: 13, text: "So wacht nun! Denn ihr wisst weder den Tag noch die Stunde*.", footnotes: ["℘ Kap. 24,36.42.50; Lk 12,40; 1Thes 5,6"] },
      { number: 14, text: "*Denn <es ist> wie <bei> einem Menschen, der außer Landes reiste, seine eigenen Knechte* rief und ihnen seine Habe übergab*:", heading: "Endzeitrede: Gleichnis von den anvertrauten Talenten", footnotes: ["℘ vgl. Lk 19,11-27", "w. Sklaven; so auch V. 19—30", "℘ Kap. 21,33 ⇨Esyn: Synopse Nr. 299"] },
      { number: 15, text: "Und einem gab er fünf Talente*, einem anderen zwei, einem anderen eins, einem jeden nach seiner eigenen Fähigkeit; und reiste außer Landes.", footnotes: ["größte damalige Geldeinheit; s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 16, text: "Sogleich aber ging der, welcher die fünf Talente empfangen hatte, hin und handelte mit ihnen und gewann andere fünf Talente." },
      { number: 17, text: "So auch, der die zwei <empfangen hatte>, auch er gewann andere zwei." },
      { number: 18, text: "Der aber das eine empfangen hatte, ging hin, grub <ein Loch> in die Erde und verbarg das Geld seines Herrn." },
      { number: 19, text: "Nach langer Zeit aber kommt der Herr jener Knechte und rechnet mit ihnen ab*.", footnotes: ["℘ Kap. 18,23; 2Kor 5,10"] },
      { number: 20, text: "Und es trat herbei, der die fünf Talente empfangen hatte, und brachte andere fünf Talente und sagte: Herr, fünf Talente hast du mir übergeben, siehe, andere fünf Talente habe ich dazugewonnen." },
      { number: 21, text: "Sein Herr sprach zu ihm: Recht so*, du guter und treuer Knecht*! Über weniges warst du treu*, über vieles werde ich dich setzen*; geh hinein in die Freude deines Herrn.", footnotes: ["w. Gut", "℘ Kap. 24,45-47", "℘ Lk 16,10; 1Kor 4,2", "℘ Lk 12,44"] },
      { number: 22, text: "Es trat aber auch herbei, der die zwei Talente <empfangen hatte>, und sprach: Herr, zwei Talente hast du mir übergeben; siehe, andere zwei Talente habe ich dazugewonnen." },
      { number: 23, text: "Sein Herr sprach zu ihm: Recht so*, du guter und treuer Knecht*! Über weniges warst du treu*, über vieles werde ich dich setzen*; geh hinein in die Freude deines Herrn.", footnotes: ["w. Gut", "℘ Lk 12,44", "℘ Lk 12,44", "℘ Lk 12,44"] },
      { number: 24, text: "Es trat aber auch herbei, der das eine Talent empfangen hatte, und sprach: Herr, ich kannte dich, dass du ein harter Mann bist; du erntest, wo du nicht gesät, und sammelst, wo du nicht ausgestreut hast;" },
      { number: 25, text: "und ich fürchtete mich und ging hin und verbarg dein Talent in der Erde; siehe, da hast du das Deine." },
      { number: 26, text: "Sein Herr aber antwortete und sprach zu ihm: Böser und fauler Knecht! Du wusstest, dass ich ernte, wo ich nicht gesät, und sammle, wo ich nicht ausgestreut habe*?", footnotes: ["℘ Hi 15,6"] },
      { number: 27, text: "So solltest du nun mein Geld den Wechslern gegeben haben, und wenn ich kam, hätte ich das Meine mit Zinsen erhalten." },
      { number: 28, text: "Nehmt ihm nun das Talent weg, und gebt es dem, der die zehn Talente hat!" },
      { number: 29, text: "Denn jedem, der hat, wird gegeben und überreichlich gewährt werden; von dem aber, der nicht hat, von dem wird selbst, was er hat, weggenommen werden*.", footnotes: ["℘ Kap. 13,12"] },
      { number: 30, text: "Und den unnützen Knecht werft hinaus in die äußere Finsternis; da wird das Weinen und das Zähneknirschen sein*.", footnotes: ["℘ Kap. 8,12"] },
      { number: 31, text: "Wenn aber der Sohn des Menschen kommen wird in seiner Herrlichkeit und alle Engel mit ihm*, dann wird er auf seinem Thron der Herrlichkeit sitzen*;", heading: "Endzeitrede: Das Gericht", footnotes: ["℘ Sach 14,5; Mk 8,38; 1Thes 3,13; 2Thes 1,10; Jud 14", "℘ Kap. 16,27; 19,28 ⇨Esyn: Synopse Nr. 300"] },
      { number: 32, text: "und vor ihm werden versammelt werden alle Nationen, und er wird sie voneinander scheiden, wie der Hirte die Schafe von den Böcken* scheidet*.", footnotes: ["d. h. Ziegenböcken; Schafe und Ziegen wurden zusammen geweidet und für die Nacht vom Hirten getrennt.", "℘ Kap. 13,30.49; Joe 4,2; Zef 3,8; Joh 5,22.27; 2Tim 4,1"] },
      { number: 33, text: "Und er wird die Schafe zu seiner Rechten stellen, die Böcke aber zur Linken*.", footnotes: ["℘ Hes 34,17"] },
      { number: 34, text: "Dann wird der König* zu denen zu seiner Rechten sagen: Kommt her, Gesegnete meines Vaters, erbt das Reich*, das euch bereitet ist* von Grundlegung der Welt an!", footnotes: ["℘ Offb 19,16", "o. die Königsherrschaft\n℘ Lk 12,32", "℘ Kap. 20,23"] },
      { number: 35, text: "Denn mich hungerte, und ihr gabt mir zu essen; mich dürstete, und ihr gabt mir zu trinken; ich war Fremdling, und ihr nahmt mich auf*;", footnotes: ["℘ Hi 31,32; Jes 58,7"] },
      { number: 36, text: "nackt, und ihr bekleidetet mich*; ich war krank, und ihr besuchtet mich; ich war im Gefängnis, und ihr kamt zu mir*.", footnotes: ["℘ Hi 31,19", "℘ 2Tim 1,16.17; Hebr 10,34"] },
      { number: 37, text: "Dann werden die Gerechten ihm antworten und sagen: Herr, wann sahen wir dich hungrig und speisten dich? Oder durstig und gaben dir zu trinken?" },
      { number: 38, text: "Wann aber sahen wir dich als Fremdling und nahmen dich auf? Oder nackt und bekleideten dich?" },
      { number: 39, text: "Wann aber sahen wir dich krank oder im Gefängnis und kamen zu dir?" },
      { number: 40, text: "Und der König wird antworten und zu ihnen sagen: Wahrlich, ich sage euch, was* ihr einem dieser meiner geringsten Brüder* getan habt, habt ihr mir getan*.", footnotes: ["w. so viel, o. in dem Maße wie", "℘ Kap. 28,10; Hebr 2,11.12", "℘ Kap. 10,40; Spr 19,17"] },
      { number: 41, text: "Dann wird er auch zu denen zur Linken sagen: Geht von mir, Verfluchte*, in das ewige Feuer*, das bereitet ist dem Teufel und seinen Engeln*!", footnotes: ["℘ Kap. 7,23", "℘ Lk 16,24; 2Thes 1,9", "℘ Kap. 5,22; 13,42; Jud 6.7; Offb 20,10.15; 21,8"] },
      { number: 42, text: "Denn mich hungerte, und ihr gabt mir nicht zu essen; mich dürstete, und ihr gabt mir nicht zu trinken;" },
      { number: 43, text: "ich war Fremdling, und ihr nahmt mich nicht auf; nackt, und ihr bekleidetet mich nicht; krank und im Gefängnis, und ihr besuchtet mich nicht." },
      { number: 44, text: "Dann werden auch sie antworten und sagen: Herr, wann sahen wir dich hungrig oder durstig oder als Fremdling oder nackt oder krank oder im Gefängnis und haben dir nicht gedient?" },
      { number: 45, text: "Dann wird er ihnen antworten und sagen: Wahrlich, ich sage euch, was* ihr einem dieser Geringsten nicht getan habt, habt ihr auch mir nicht getan.", footnotes: ["w. so viel, o. in dem Maße wie"] },
      { number: 46, text: "Und diese werden hingehen zur ewigen Strafe*, die Gerechten aber in das ewige Leben*.", footnotes: ["℘ Jak 2,13", "℘ Dan 12,2; Joh 5,29; Röm 2,7.8"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "*Und es geschah, als Jesus alle diese Reden beendet hatte*, sprach er zu seinen Jüngern:", heading: "Anschlag der Hohenpriester und Verrat des Judas — Salbung Jesu in Betanien", footnotes: ["℘ Mk 14,1.2; Lk 22,1.2", "℘ Kap. 7,28 ⇨Esyn: Synopse Nr. 305"] },
      { number: 2, text: "Ihr wisst, dass nach zwei Tagen das Passah ist, und der Sohn des Menschen wird überliefert, um gekreuzigt zu werden*.", footnotes: ["℘ Kap. 16,21"] },
      { number: 3, text: "Dann versammelten sich die Hohenpriester* und die Ältesten des Volkes* in dem Hof des Hohenpriesters, der Kaiphas hieß*,", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ Joh 11,47", "℘ Lk 3,2"] },
      { number: 4, text: "und ratschlagten miteinander*, um Jesus mit List zu greifen und zu töten*.", footnotes: ["℘ Kap. 27,1", "℘ Kap. 12,14; Ps 31,14"] },
      { number: 5, text: "Sie sagten aber: Nicht an dem Fest, damit nicht ein Aufruhr unter dem Volk entstehe*.", footnotes: ["℘ Lk 22,6"] },
      { number: 6, text: "*Als aber Jesus in Betanien war, im Hause Simons, des Aussätzigen*, *", footnotes: ["℘ Mk 14,3-9; Joh 12,1-8", "»Aussatz« umfasste in bibl. Zeit mehrere Hautkrankheiten; s. auch Anm. zu Kap. 8,2.", "℘ ⇨Esyn: Synopse Nr. 306"] },
      { number: 7, text: "kam eine Frau zu ihm, die ein Alabasterfläschchen mit sehr kostbarem Salböl hatte, und goss es aus auf <sein> Haupt, als er zu Tisch lag*.", footnotes: ["℘ Lk 7,37"] },
      { number: 8, text: "Als aber die Jünger es sahen, wurden sie unwillig und sprachen: Wozu diese Verschwendung?" },
      { number: 9, text: "Denn dies hätte teuer verkauft und <der Erlös> den Armen gegeben werden können." },
      { number: 10, text: "Als aber Jesus es erkannte, sprach er zu ihnen: Was macht ihr der Frau Mühe? Sie hat doch ein gutes Werk an mir getan;" },
      { number: 11, text: "denn die Armen habt ihr allezeit bei euch*, mich aber habt ihr nicht allezeit.", footnotes: ["℘ 5Mo 15,11"] },
      { number: 12, text: "Denn als sie dieses Salböl über meinen Leib goss, tat sie es zu meinem Begräbnis." },
      { number: 13, text: "Wahrlich, ich sage euch: Wo dieses Evangelium gepredigt werden wird in der ganzen Welt, wird auch von dem geredet werden, was sie getan hat, zu ihrem Gedächtnis*.", footnotes: ["℘ 1Sam 2,30"] },
      { number: 14, text: "*Dann ging einer von den Zwölfen, Judas Iskariot* mit Namen*, zu den Hohenpriestern*", footnotes: ["℘ Mk 14,10.11; Lk 22,3-6", "Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Joh 14,22).", "℘ Kap. 10,4", "℘ Joh 11,57 ⇨Esyn: Synopse Nr. 307"] },
      { number: 15, text: "und sprach: Was wollt ihr mir geben, und ich werde ihn euch überliefern? Sie aber setzten ihm dreißig Silberlinge fest*.", footnotes: ["℘ Kap. 27,3.9.10; 1Tim 6,10"] },
      { number: 16, text: "Und von da an suchte er Gelegenheit, ihn zu überliefern." },
      { number: 17, text: "*Am ersten <Tag des Festes> der ungesäuerten Brote* aber traten die Jünger zu Jesus und sprachen: Wo willst du, dass wir dir das Passah<mahl>* zu essen bereiten?", heading: "Vorbereitung des Passahmahles", footnotes: ["℘ Mk 14,12-16; Lk 22,7-13", "℘ 2Mo 12,18-20", "℘ 2Mo 12,11; 3Mo 23,5.6; 4Mo 28,16.17; 5Mo 16,2.3 ⇨Esyn: Synopse Nr. 308"] },
      { number: 18, text: "Er aber sprach: Geht in die Stadt zu dem und dem und sprecht zu ihm: Der Lehrer sagt*: Meine Zeit ist nahe; bei dir halte ich das Passah mit meinen Jüngern.", footnotes: ["℘ Kap. 21,3"] },
      { number: 19, text: "Und die Jünger taten, wie Jesus ihnen befohlen hatte, und bereiteten das Passah." },
      { number: 20, text: "*Als es aber Abend geworden war, legte er sich mit den Zwölfen zu Tisch.", heading: "Bezeichnung des Verräters", footnotes: ["℘ Mk 14,17-21; Lk 22,14.21-23; Joh 13,18-30"] },
      { number: 21, text: "Und während sie aßen, sprach er: Wahrlich, ich sage euch: Einer von euch wird mich überliefern*.", footnotes: ["℘ Joh 6,70.71 ⇨Esyn: Synopse Nr. 310"] },
      { number: 22, text: "Und sie wurden sehr betrübt, und jeder von ihnen fing an, zu ihm zu sagen: Ich bin es doch nicht, Herr?" },
      { number: 23, text: "Er aber antwortete und sprach: Der mit mir die Hand in die Schüssel eintaucht, der wird mich überliefern." },
      { number: 24, text: "Der Sohn des Menschen geht zwar dahin, wie über ihn geschrieben steht*. Wehe aber jenem Menschen, durch den der Sohn des Menschen überliefert wird! Es wäre jenem Menschen gut, wenn er nicht geboren wäre*.", footnotes: ["℘ V. 54; Jes 53,7.8; Dan 9,26; Lk 18,31; 1Petr 1,11", "℘ Kap. 18,7"] },
      { number: 25, text: "Judas aber, der ihn überlieferte, antwortete und sprach: Ich bin es doch nicht, Rabbi*? Er spricht zu ihm: Du hast es gesagt.", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum"] },
      { number: 26, text: "*Während sie aber aßen, nahm Jesus Brot und segnete*, brach und gab es den Jüngern und sprach: Nehmt, esst, dies ist mein Leib!", heading: "Einsetzung des Herrenmahles", footnotes: ["℘ Mk 14,22-26; Lk 22,15-20; 1Kor 11,23-25", "℘ Kap. 14,19 ⇨Esyn: Synopse Nr. 311"] },
      { number: 27, text: "Und er nahm einen Kelch und dankte und gab ihnen <den> und sprach: Trinkt alle daraus!" },
      { number: 28, text: "Denn dies ist mein Blut des Bundes*, das für viele* vergossen wird zur Vergebung der Sünden*.", footnotes: ["℘ 2Mo 24,8; Jer 31,31; Sach 9,11; Hebr 10,16", "℘ Kap. 20,28", "℘ Eph 1,7; Hebr 9,22"] },
      { number: 29, text: "Ich sage euch aber, dass ich von nun an nicht mehr von diesem Gewächs des Weinstocks trinken werde bis zu jenem Tag, da ich es neu mit euch trinken werde in dem Reich* meines Vaters.", footnotes: ["o. der Königsherrschaft"] },
      { number: 30, text: "Und als sie ein Loblied* gesungen hatten, gingen sie hinaus zum Ölberg*.", footnotes: ["Damit ist wohl der zweite Teil des sog. Hallel, nämlich Ps 115—118, gemeint, der nach dem Schlussgebet des Passahmahls gesungen wurde.", "℘ Lk 22,39; Joh 14,31; 18,1 ⇨Esyn: Synopse Nr. 315"] },
      { number: 31, text: "*Darauf spricht Jesus zu ihnen: Ihr werdet euch alle in dieser Nacht an mir ärgern*; denn es steht geschrieben: »Ich werde den Hirten schlagen, und die Schafe der Herde werden zerstreut werden*.«", heading: "Ankündigung der Verleugnung durch Petrus", footnotes: ["℘ Mk 14,27-31; Lk 22,31-34; Joh 13,36-38", "Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, zur Sünde verleitet werden.\n℘ Kap. 11,6", "℘ V. 56; Sach 13,7; Joh 16,32"] },
      { number: 32, text: "Nachdem ich aber auferweckt sein werde, werde ich vor euch hingehen nach Galiläa*.", footnotes: ["℘ Kap. 28,7.10"] },
      { number: 33, text: "Petrus aber antwortete und sprach zu ihm: Wenn sich alle an dir ärgern werden, ich werde mich niemals ärgern*.", footnotes: ["Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, zur Sünde verleitet werden."] },
      { number: 34, text: "Jesus sprach zu ihm: Wahrlich, ich sage dir, dass du in dieser Nacht, ehe der Hahn kräht, mich dreimal verleugnen wirst*.", footnotes: ["℘ V. 75"] },
      { number: 35, text: "Petrus spricht zu ihm: Selbst wenn ich mit dir sterben müsste, werde ich dich nicht verleugnen. Ebenso sprachen auch alle Jünger*.", footnotes: ["℘ Joh 11,16"] },
      { number: 36, text: "*Dann kommt Jesus mit ihnen an ein Gut*, genannt Gethsemane, und er spricht zu den Jüngern: Setzt euch hier, bis ich hingegangen bin und dort gebetet habe*!", heading: "Gethsemane", footnotes: ["℘ Mk 14,32-42; Lk 22,39-46", "o. Grundstück", "℘ Joh 18,1 ⇨Esyn: Synopse Nr. 330"] },
      { number: 37, text: "Und er nahm den Petrus und die zwei Söhne des Zebedäus mit* und fing an, betrübt und geängstigt zu werden.", footnotes: ["℘ Kap. 17,1"] },
      { number: 38, text: "Dann spricht er zu ihnen: Meine Seele ist sehr betrübt, bis zum Tod*. Bleibt hier und wacht mit mir!", footnotes: ["℘ Ps 88,4; Lk 12,50"] },
      { number: 39, text: "Und er ging ein wenig weiter und fiel auf sein Angesicht und betete und sprach: Mein Vater, wenn es möglich ist, so gehe dieser Kelch an mir vorüber*! Doch nicht wie ich will, sondern wie du <willst>*.", footnotes: ["℘ Kap. 20,22", "℘ Joh 4,34; Phil 2,8"] },
      { number: 40, text: "Und er kommt zu den Jüngern und findet sie schlafend; und er spricht zu Petrus: Also nicht eine Stunde konntet ihr mit mir wachen*?", footnotes: ["℘ Ps 69,21"] },
      { number: 41, text: "Wacht und betet*, damit ihr nicht in Versuchung kommt*! Der Geist zwar ist willig, das Fleisch aber schwach*.", footnotes: ["℘ Lk 18,1; Eph 6,18", "℘ 1Petr 5,8", "℘ Röm 7,18"] },
      { number: 42, text: "Wiederum, zum zweiten Mal, ging er hin und betete und sprach: Mein Vater, wenn dieser <Kelch> nicht vorübergehen kann, ohne dass ich ihn trinke, so geschehe dein Wille*!", footnotes: ["℘ Kap. 6,10; Joh 18,11"] },
      { number: 43, text: "Und als er kam, fand er sie wieder schlafend, denn ihre Augen waren beschwert*.", footnotes: ["℘ Lk 9,32"] },
      { number: 44, text: "Und er ließ sie, ging wieder hin, betete zum dritten Mal* und sprach wieder dasselbe Wort.", footnotes: ["℘ 2Kor 12,8"] },
      { number: 45, text: "Dann kommt er zu den Jüngern und spricht zu ihnen: So schlaft denn fort und ruht aus! Siehe, die Stunde ist nahe gekommen*, und der Sohn des Menschen wird in Sünderhände überliefert*.", footnotes: ["℘ Joh 12,23", "℘ Kap. 17,22"] },
      { number: 46, text: "Steht auf, lasst uns gehen! Siehe, nahe ist gekommen, der mich überliefert*.", footnotes: ["℘ Ps 119,150; Joh 18,3"] },
      { number: 47, text: "*Und während er noch redete, siehe, da kam Judas, einer der Zwölf, und mit ihm eine große Menge mit Schwertern und Stöcken, von den Hohenpriestern und Ältesten des Volkes. *", heading: "Gefangennahme", footnotes: ["℘ Mk 14,43-50; Lk 22,47-53; Joh 18,2-12", "℘ ⇨Esyn: Synopse Nr. 331"] },
      { number: 48, text: "Der ihn aber überlieferte, hatte ihnen ein Zeichen gegeben und gesagt: Wen ich küssen werde, der ist es, den ergreift!" },
      { number: 49, text: "Und sogleich trat er zu Jesus und sprach: Sei gegrüßt, Rabbi*!, und küsste ihn*.", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum\n℘ Ps 55,22", "o. küsste ihn zärtlich\n℘ 2Sam 20,9"] },
      { number: 50, text: "Jesus aber sprach zu ihm: Freund, wozu bist du gekommen? Dann traten sie heran und legten die Hände an Jesus und ergriffen ihn." },
      { number: 51, text: "Und siehe, einer von denen, die mit Jesus waren, streckte die Hand aus, zog sein Schwert und schlug den Knecht* des Hohenpriesters und hieb ihm das Ohr ab.", footnotes: ["w. Sklaven"] },
      { number: 52, text: "Da spricht Jesus zu ihm: Stecke dein Schwert wieder an seinen Ort! Denn alle, die das Schwert nehmen, werden durchs Schwert umkommen*.", footnotes: ["℘ 1Mo 9,6; Offb 13,10"] },
      { number: 53, text: "Oder meinst du, dass ich nicht meinen Vater bitten könne und er mir jetzt mehr als zwölf Legionen Engel stellen werde?" },
      { number: 54, text: "Wie sollten denn die Schriften erfüllt werden, dass es so geschehen muss*?", footnotes: ["℘ V. 24"] },
      { number: 55, text: "In jener Stunde sprach Jesus zu den Volksmengen: Seid ihr ausgezogen wie gegen einen Räuber mit Schwertern und Stöcken, mich zu fangen? Täglich saß ich bei euch im Tempel und lehrte*, und ihr habt mich nicht gegriffen.", footnotes: ["℘ Lk 19,47"] },
      { number: 56, text: "Aber dies alles ist geschehen, damit die Schriften der Propheten erfüllt werden. Da verließen ihn die Jünger alle und flohen*.", footnotes: ["℘ V. 31; Kap. 27,9; Ps 88,19"] },
      { number: 57, text: "*Die aber Jesus gegriffen hatten, führten ihn weg zu Kaiphas, dem Hohenpriester, wo die Schriftgelehrten und die Ältesten versammelt waren. *", heading: "Vor dem Hohen Rat", footnotes: ["℘ Mk 14,53-65; Lk 22,54.55.63-71; Joh 18,13.14.19-24", "℘ ⇨Esyn: Synopse Nr. 332"] },
      { number: 58, text: "Petrus aber folgte ihm von weitem bis zu dem Hof des Hohenpriesters und ging hinein und setzte sich zu den Dienern, um den Ausgang zu sehen." },
      { number: 59, text: "Die Hohenpriester aber und der ganze Hohe Rat* suchten falsches Zeugnis* gegen Jesus, um ihn zu Tode zu bringen;", footnotes: ["w. Synedrium. Der Hohe Rat war, abgesehen vom römischen Statthalter, die höchste Behörde der Juden. Er bestand unter dem Vorsitz des Hohenpriesters aus 71 Mitgliedern und umfasste die Gruppen der Hohenpriester, Schriftgelehrten und Ältesten. Vgl. auch die Anmerkungen zu Kap. 2,4 und 3,7.", "℘ Apg 6,11"] },
      { number: 60, text: "und sie fanden keins, obwohl viele falsche Zeugen herzutraten*. Zuletzt aber traten zwei falsche Zeugen herbei*", footnotes: ["℘ Ps 27,12", "℘ 5Mo 19,15"] },
      { number: 61, text: "und sprachen: Dieser sagte: Ich kann den Tempel Gottes abbrechen und in drei Tagen ihn wieder aufbauen*.", footnotes: ["℘ Kap. 27,40; Joh 2,19"] },
      { number: 62, text: "Und der Hohepriester stand auf und sprach zu ihm: Antwortest du nichts? Was zeugen diese gegen dich?" },
      { number: 63, text: "Jesus aber schwieg*. Und der Hohepriester sagte zu ihm: Ich beschwöre dich bei dem lebendigen Gott, dass du uns sagst, ob du der Christus bist, der Sohn Gottes*!", footnotes: ["℘ Kap. 27,12.14; Ps 38,14.15; Jes 53,7; Lk 23,9; Joh 19,9", "℘ Joh 5,18"] },
      { number: 64, text: "Jesus spricht zu ihm: Du hast es gesagt. Doch ich sage euch: Von nun an werdet ihr den Sohn des Menschen sitzen sehen zur Rechten der Macht* und kommen auf den Wolken des Himmels*.", footnotes: ["℘ Mk 16,19; Hebr 1,3", "℘ Kap. 16,27; Lk 21,27; Offb 1,7"] },
      { number: 65, text: "Da zerriss der Hohepriester seine Kleider* und sprach: Er hat gelästert. Was brauchen wir noch Zeugen? Siehe, jetzt habt ihr die Lästerung gehört*.", footnotes: ["℘ 3Mo 21,10", "℘ Kap. 9,3; Mk 2,7; Joh 10,33"] },
      { number: 66, text: "Was meint ihr? Sie aber antworteten und sprachen: Er ist des Todes schuldig*.", footnotes: ["℘ Kap. 20,18; 3Mo 24,16"] },
      { number: 67, text: "Dann spien sie ihm ins Angesicht und schlugen ihn mit Fäusten; einige aber schlugen <ihn ins Gesicht>*", footnotes: ["℘ Kap. 27,30; Ps 69,8; Jes 50,6; 53,7; Mk 10,34"] },
      { number: 68, text: "und sprachen: Weissage uns, Christus, wer ist es, der dich schlug?" },
      { number: 69, text: "*Petrus aber saß draußen im Hof; und es trat eine Magd zu ihm und sprach: Auch du warst mit Jesus, dem Galiläer*.", heading: "Verleugnung durch Petrus", footnotes: ["℘ Mk 14,66-72; Lk 22,56-62; Joh 18,15-18.25-27", "℘ Kap. 21,11 ⇨Esyn: Synopse Nr. 333"] },
      { number: 70, text: "Er aber leugnete vor allen und sprach: Ich weiß nicht, was du sagst." },
      { number: 71, text: "Als er aber in das Torgebäude hinausgegangen war, sah ihn eine andere; und sie spricht zu denen, die dort waren: Auch dieser war mit Jesus, dem Nazoräer*.", footnotes: ["Dies ist eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; es ist möglich, dass in Anlehnung an Jes 11,1 das hebr. Wort nezer (d. h. Spross) anklingt.\n℘ Kap. 2,22.23"] },
      { number: 72, text: "Und wieder leugnete er mit einem Eid: Ich kenne den Menschen nicht!" },
      { number: 73, text: "Kurz nachher aber traten die Umstehenden herbei und sprachen zu Petrus: Wahrhaftig, auch du bist <einer> von ihnen, denn auch deine Sprache verrät dich." },
      { number: 74, text: "Da fing er an, sich zu verwünschen und zu schwören: Ich kenne den Menschen nicht! Und gleich darauf krähte der Hahn." },
      { number: 75, text: "Und Petrus gedachte des Wortes Jesu, der gesagt hatte: Ehe der Hahn kräht, wirst du mich dreimal verleugnen*. Und er ging hinaus und weinte bitterlich.", footnotes: ["℘ V. 34"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "*Als es aber Morgen geworden war, hielten alle Hohenpriester* und Ältesten des Volkes Rat gegen Jesus, um ihn zu Tode zu bringen*.", heading: "Überlieferung an Pilatus", footnotes: ["℘ Mk 15,1; Lk 22,66; 23,1; Joh 18,28", "Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ Kap. 26,3.4 ⇨Esyn: Synopse Nr. 334"] },
      { number: 2, text: "Und nachdem sie ihn gebunden hatten, führten sie ihn weg und überlieferten ihn dem Statthalter Pilatus*.", footnotes: ["Statthalter des röm. Kaisers in Judäa und Samaria (ca. 26—36 n. Chr.)\n℘ Kap. 20,19; Apg 13,28"] },
      { number: 3, text: "*Als nun Judas, der ihn überliefert hatte, sah, dass er verurteilt wurde, reute es ihn, und er brachte die dreißig Silberlinge* den Hohenpriestern und den Ältesten zurück", heading: "Ende des Judas", footnotes: ["℘ Apg 1,16-19", "℘ Kap. 26,15 ⇨Esyn: Synopse Nr. 335"] },
      { number: 4, text: "und sagte: Ich habe gesündigt, denn ich habe schuldloses Blut überliefert*. Sie aber sagten: Was geht das uns an? Sieh du zu!", footnotes: ["℘ V. 24"] },
      { number: 5, text: "Und er warf die Silberlinge in den Tempel und machte sich davon und ging hin und erhängte sich*.", footnotes: ["℘ 2Sam 17,23"] },
      { number: 6, text: "Die Hohenpriester aber nahmen die Silberlinge und sprachen: Es ist nicht erlaubt, sie in den Tempelschatz zu werfen, weil es Blutgeld ist." },
      { number: 7, text: "Sie hielten aber Rat und kauften dafür den Acker des Töpfers zum Begräbnis für die Fremden." },
      { number: 8, text: "Deswegen ist jener Acker Blutacker genannt worden bis auf den heutigen Tag." },
      { number: 9, text: "Da wurde erfüllt*, was durch den Propheten Jeremia geredet ist, der spricht: »Und sie nahmen die dreißig Silberlinge, den Preis des Geschätzten, den man geschätzt hatte seitens der Söhne Israels,", footnotes: ["℘ Kap. 26,56"] },
      { number: 10, text: "und gaben sie für den Acker des Töpfers, wie mir der Herr befohlen hat*.«", footnotes: ["℘ Sach 11,12.13; Jer 32,9"] },
      { number: 11, text: "*Jesus aber wurde dem Statthalter vorgeführt. Und der Statthalter fragte ihn und sprach: Bist du der König der Juden*? Jesus aber sprach zu ihm: Du sagst es*.", heading: "Anklage vor Pilatus", footnotes: ["℘ Mk 15,2-5; Lk 23,2-5; Joh 18,29-38", "℘ V. 29.37; Kap. 2,2", "℘ 1Tim 6,13 ⇨Esyn: Synopse Nr. 336"] },
      { number: 12, text: "Und als er von den Hohenpriestern und den Ältesten angeklagt wurde, antwortete er nichts*.", footnotes: ["℘ Kap. 26,63"] },
      { number: 13, text: "Da spricht Pilatus zu ihm: Hörst du nicht, wie vieles sie gegen dich vorbringen?" },
      { number: 14, text: "Und er antwortete ihm auch nicht auf ein einziges Wort*, so dass der Statthalter sich sehr wunderte.", footnotes: ["℘ Kap. 26,63"] },
      { number: 15, text: "*Zum Fest aber war der Statthalter gewohnt, der Volksmenge einen Gefangenen loszugeben, den sie verlangten. *", heading: "Freilassung für Barabbas — Todesurteil für Jesus", footnotes: ["℘ Mk 15,6-15; Lk 23,13-25; Joh 18,39.40; 19,1.16", "℘ ⇨Esyn: Synopse Nr. 339"] },
      { number: 16, text: "Sie hatten aber damals einen berüchtigten Gefangenen, mit Namen Barabbas*.", footnotes: ["d. h. Sohn des Vaters; mehrere Handschr. haben hier: Jesus Barabbas"] },
      { number: 17, text: "Als sie nun versammelt waren, sprach Pilatus zu ihnen: Wen wollt ihr, dass ich euch losgeben soll, Barabbas* oder Jesus, der Christus genannt wird*?", footnotes: ["Mehrere Handschr. haben hier: Jesus den Barabbas", "℘ Kap. 1,16"] },
      { number: 18, text: "Denn er wusste, dass sie ihn aus Neid überliefert hatten." },
      { number: 19, text: "Während er aber auf dem Richterstuhl saß*, sandte seine Frau zu ihm und ließ <ihm> sagen: Habe du nichts zu schaffen mit jenem Gerechten*! Denn im Traum habe ich heute um seinetwillen viel gelitten.", footnotes: ["℘ Joh 19,13", "℘ Lk 23,47"] },
      { number: 20, text: "Aber die Hohenpriester und die Ältesten überredeten die Volksmengen, dass sie den Barabbas forderten, Jesus aber umbrächten*.", footnotes: ["℘ Apg 13,28"] },
      { number: 21, text: "Der Statthalter aber antwortete und sprach zu ihnen: Welchen von den beiden wollt ihr, dass ich euch losgebe? Sie aber sprachen: Barabbas." },
      { number: 22, text: "Pilatus spricht zu ihnen: Was soll ich denn mit Jesus tun, der Christus genannt wird*? Sie sagen alle: Er werde gekreuzigt*!", footnotes: ["℘ Kap. 1,16", "℘ Kap. 20,19; 26,2"] },
      { number: 23, text: "Er aber sagte: Was hat er denn Böses getan*? Sie aber schrien über die Maßen und sagten: Er werde gekreuzigt*!", footnotes: ["℘ Lk 23,41; Joh 8,46", "℘ Kap. 20,19; 26,2"] },
      { number: 24, text: "Als aber Pilatus sah, dass er nichts ausrichtete, sondern vielmehr ein Tumult entstand, nahm er Wasser, wusch seine Hände vor der Volksmenge* und sprach: Ich bin schuldlos an dem Blut dieses Gerechten*. Seht ihr zu*!", footnotes: ["℘ 5Mo 21,6.7", "Mehrere alte Handschr. haben: dieses <Menschen>\n℘ Lk 23,47", "℘ V. 4 ⇨Esyn: Synopse Nr. 341"] },
      { number: 25, text: "Und das ganze Volk antwortete und sprach: Sein Blut <komme> über uns und über unsere Kinder*!", footnotes: ["℘ 2Mo 20,5; 5Mo 19,10; Apg 5,28"] },
      { number: 26, text: "Dann gab er ihnen den Barabbas los; Jesus aber ließ er geißeln* und überlieferte ihn, damit er gekreuzigt werde*.", footnotes: ["℘ Jes 50,6", "℘ Ps 94,21"] },
      { number: 27, text: "*Dann nahmen die Soldaten des Statthalters Jesus mit in das Prätorium* und versammelten um ihn die ganze Schar*; *", heading: "Verspottung durch die Soldaten", footnotes: ["℘ Mk 15,16-20; Joh 19,2-5", "So hieß der Palast eines Statthalters in den römischen Provinzen.", "Gemeint ist »Kohorte«, eine militärische Einheit der Römer von etwa 600 Mann unter dem Befehl eines Obersten; vgl. Anm. zu Apg 21,31.", "℘ ⇨Esyn: Synopse Nr. 342"] },
      { number: 28, text: "und sie zogen ihn aus und legten ihm einen scharlachroten Mantel* um*.", footnotes: ["Solche Mäntel trugen die römischen Soldaten.", "℘ Lk 23,11"] },
      { number: 29, text: "Und sie flochten eine Krone aus Dornen und setzten sie auf sein Haupt und <gaben ihm> ein Rohr in seine Rechte; und sie fielen vor ihm auf die Knie und verspotteten ihn* und sagten: Sei gegrüßt, König der Juden*!", footnotes: ["℘ Ps 69,20", "℘ V. 11"] },
      { number: 30, text: "Und sie spien ihn an, nahmen das Rohr und schlugen ihn auf das Haupt*.", footnotes: ["℘ Kap. 26,67"] },
      { number: 31, text: "Und als sie ihn verspottet hatten, zogen sie ihm den Mantel aus und zogen ihm seine <eigenen> Kleider an; und sie führten ihn ab, um ihn zu kreuzigen. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 343"] },
      { number: 32, text: "*Als sie aber hinauszogen, trafen sie einen Mann von Kyrene, mit Namen Simon; den zwangen sie, dass er sein Kreuz trage.", heading: "Golgatha: Kreuzigung", footnotes: ["℘ Mk 15,21-32; Lk 23,26-43; Joh 19,16-27"] },
      { number: 33, text: "Und als sie an einen Ort gekommen waren, genannt Golgatha, das heißt Schädelstätte, *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 344"] },
      { number: 34, text: "gaben sie ihm mit Galle vermischten Wein zu trinken*; und als er davon gekostet hatte, wollte er nicht trinken.", footnotes: ["℘ V. 48; Ps 69,22"] },
      { number: 35, text: "Als sie ihn aber gekreuzigt hatten*, verteilten sie seine Kleider, indem sie das Los warfen*.", footnotes: ["℘ Phil 2,8", "℘ Ps 22,19"] },
      { number: 36, text: "Und sie saßen und bewachten ihn dort." },
      { number: 37, text: "Und sie brachten oben über seinem Haupt seine Beschuldigungsschrift an: Dies ist Jesus, der König der Juden*.", footnotes: ["℘ V. 11"] },
      { number: 38, text: "Dann werden zwei Räuber mit ihm gekreuzigt, einer zur Rechten und einer zur Linken*.", footnotes: ["℘ Jes 53,12 ⇨Esyn: Synopse Nr. 345"] },
      { number: 39, text: "Die Vorübergehenden aber lästerten ihn, schüttelten ihre Köpfe*", footnotes: ["℘ Ps 22,8; 109,25"] },
      { number: 40, text: "und sagten: Der du den Tempel abbrichst und in drei Tagen aufbaust*, rette dich selbst! Wenn du Gottes Sohn bist*, so steige herab vom Kreuz!", footnotes: ["℘ Kap. 26,61", "℘ Kap. 4,3.6"] },
      { number: 41, text: "Ebenso aber spotteten auch die Hohenpriester mit den Schriftgelehrten und Ältesten* und sprachen:", footnotes: ["℘ Ps 69,21"] },
      { number: 42, text: "Andere hat er gerettet, sich selbst kann er nicht retten. Er ist Israels König*, so steige er jetzt vom Kreuz herab, und wir werden an ihn glauben.", footnotes: ["℘ Lk 23,2"] },
      { number: 43, text: "Er vertraute auf Gott, der rette ihn jetzt*, wenn er ihn liebt*; denn er sagte: Ich bin Gottes Sohn*.", footnotes: ["℘ Ps 3,2.3", "w. will; o. Gefallen an ihm hat\n℘ Ps 22,9", "℘ Lk 22,70; Joh 10,36; 19,7"] },
      { number: 44, text: "Auf dieselbe Weise schmähten ihn auch die Räuber, die mit ihm gekreuzigt waren. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 346"] },
      { number: 45, text: "*Aber von der sechsten Stunde* an kam eine Finsternis über das ganze Land bis zur neunten Stunde; *", heading: "Golgatha: Tod", footnotes: ["℘ Mk 15,33-41; Lk 23,44-49; Joh 19,28-30", "In neutestamentl. Zeit teilte man Tag und Nacht in je 12 Stunden ein, wobei sich die Länge der Stunden nach der Länge des Tages zwischen Sonnenauf- und Sonnenuntergang richtete. Das Ende der 6. Stunde fiel dabei also immer auf den Mittag 12 Uhr unserer Zeit.", "℘ ⇨Esyn: Synopse Nr. 347"] },
      { number: 46, text: "um die neunte Stunde aber schrie Jesus mit lauter Stimme auf* und sagte: Eli, Eli, lemá sabachtháni? Das heißt: Mein Gott, mein Gott, warum hast du mich verlassen*?", footnotes: ["℘ Hebr 5,7", "℘ Ps 22,2"] },
      { number: 47, text: "Als aber einige von den Umstehenden es hörten, sagten sie: Der ruft den Elia." },
      { number: 48, text: "Und sogleich lief einer von ihnen und nahm einen Schwamm, füllte ihn mit Essig und steckte ihn auf ein Rohr und gab ihm zu trinken*.", footnotes: ["℘ V. 34"] },
      { number: 49, text: "Die Übrigen aber sagten: Halt, lasst uns sehen, ob Elia kommt, ihn zu retten!" },
      { number: 50, text: "Jesus aber schrie wieder mit lauter Stimme* und gab den Geist auf.", footnotes: ["℘ Hebr 5,7"] },
      { number: 51, text: "Und siehe, der Vorhang* des Tempels* zerriss in zwei <Stücke>, von oben bis unten*; und die Erde erbebte*, und die Felsen zerrissen,", footnotes: ["℘ 2Mo 26,31-33", "℘ 2Chr 3,14", "℘ Hebr 10,19.20", "℘ Kap. 28,2"] },
      { number: 52, text: "und die Grüfte öffneten sich, und viele Leiber der entschlafenen Heiligen wurden auferweckt," },
      { number: 53, text: "und sie gingen nach seiner Auferweckung aus den Grüften und gingen in die heilige Stadt* und erschienen vielen.", footnotes: ["℘ Kap. 4,5"] },
      { number: 54, text: "Als aber der Hauptmann und die, die mit ihm Jesus bewachten, das Erdbeben sahen und das, was geschah, fürchteten sie sich sehr und sprachen: Wahrhaftig, dieser war Gottes Sohn*!", footnotes: ["℘ Kap. 14,33"] },
      { number: 55, text: "Es sahen aber dort viele Frauen von weitem zu*, die Jesus von Galiläa nachgefolgt waren und ihm gedient hatten*;", footnotes: ["℘ Ps 38,12", "℘ Lk 8,2.3 ⇨Esyn: Synopse Nr. 348"] },
      { number: 56, text: "unter ihnen waren Maria Magdalena* und Maria, des Jakobus' und Josefs Mutter, und die Mutter der Söhne des Zebedäus*.", footnotes: ["d. h. die aus Magdala (Ort in der Nähe des Sees Genezareth); so auch V. 61", "℘ Joh 19,25"] },
      { number: 57, text: "*Als es aber Abend geworden war, kam ein reicher Mann von Arimathäa, mit Namen Josef, der selbst auch ein Jünger Jesu war. *", heading: "Grablegung", footnotes: ["℘ Mk 15,42-47; Lk 23,50-56; Joh 19,38-42", "℘ ⇨Esyn: Synopse Nr. 350"] },
      { number: 58, text: "Dieser ging hin zu Pilatus und bat um den Leib Jesu. Da befahl Pilatus, <den Leib> zu übergeben." },
      { number: 59, text: "Und Josef nahm den Leib und wickelte ihn in ein reines Leinentuch" },
      { number: 60, text: "und legte ihn in seine neue Gruft*, die er in den Felsen ausgehauen hatte; und er wälzte einen großen Stein an die Tür der Gruft* und ging weg.", footnotes: ["℘ Jes 53,9; Apg 13,29", "℘ Mk 16,4; Joh 11,38"] },
      { number: 61, text: "Es waren aber dort Maria Magdalena und die andere Maria, die dem Grab gegenübersaßen*.", footnotes: ["℘ Kap. 28,1"] },
      { number: 62, text: "Am nächsten Tag aber, der auf den Rüsttag* folgt*, versammelten sich die Hohenpriester und die Pharisäer bei Pilatus", heading: "Bewachung des Grabes", footnotes: ["der Wochentag vor einem Sabbat oder Fest, in der Regel ein Freitag", "℘ Mk 15,42; Lk 23,54; Joh 19,31 ⇨Esyn: Synopse Nr. 351"] },
      { number: 63, text: "und sprachen: Herr, wir haben uns erinnert, dass jener Verführer* sagte, als er noch lebte: Nach drei Tagen stehe ich <wieder> auf*.", footnotes: ["℘ Joh 7,12", "℘ Kap. 16,21"] },
      { number: 64, text: "So befiehl nun, dass das Grab gesichert werde bis zum dritten Tag, damit nicht etwa seine Jünger kommen, ihn stehlen* und dem Volk sagen: Er ist von den Toten auferweckt worden. Und die letzte Verführung wird schlimmer sein als die erste.", footnotes: ["℘ Kap. 28,13"] },
      { number: 65, text: "Pilatus sprach zu ihnen: Ihr sollt eine Wache haben. Geht hin, sichert es, so gut ihr könnt!" },
      { number: 66, text: "Sie aber gingen hin und sicherten, nachdem sie den Stein versiegelt hatten*, das Grab mit der Wache.", footnotes: ["℘ Dan 6,18"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "*Aber nach dem Sabbat, in der <Morgen>dämmerung des ersten Wochentages*, kam Maria Magdalena* und die andere Maria*, um das Grab zu besehen.", heading: "Die Frauen am leeren Grab — Erscheinung des Auferstandenen", footnotes: ["℘ Mk 16,1-11; Lk 24,1-12; Joh 20,1-18", "Der Tag beginnt mit dem Sonnenuntergang, also mit der ersten Nachtwache.", "d. h. die aus Magdala (Ort in der Nähe des Sees Genezareth); so auch V. 61", "℘ Kap. 27,61 ⇨Esyn: Synopse Nr. 352"] },
      { number: 2, text: "Und siehe, da geschah ein großes Erdbeben*; denn ein Engel des Herrn kam aus dem Himmel herab, trat hinzu, wälzte den Stein weg und setzte sich darauf.", footnotes: ["℘ Kap. 27,51"] },
      { number: 3, text: "Sein Ansehen aber war wie der Blitz und sein Gewand weiß wie Schnee*.", footnotes: ["℘ Kap. 17,2"] },
      { number: 4, text: "Aber aus Furcht vor ihm bebten die Wächter und wurden wie Tote*.", footnotes: ["℘ Lk 2,9"] },
      { number: 5, text: "Der Engel aber begann* und sprach zu den Frauen: Fürchtet euch nicht*! Denn ich weiß, dass ihr Jesus, den Gekreuzigten, sucht.", footnotes: ["w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "℘ Lk 2,10"] },
      { number: 6, text: "Er ist nicht hier, denn er ist auferweckt worden*, wie er gesagt hat*. Kommt her, seht die Stätte, wo er gelegen hat,", footnotes: ["℘ Apg 2,24; Röm 1,4", "℘ Kap. 16,21"] },
      { number: 7, text: "und geht schnell hin und sagt seinen Jüngern, dass er von den Toten auferweckt worden ist*! Und siehe, er geht vor euch hin nach Galiläa*, dort werdet ihr ihn sehen*. Siehe, ich habe es euch gesagt*.", footnotes: ["℘ Lk 24,23; Offb 1,18", "℘ Kap. 26,32", "℘ Joh 16,16", "℘ Kap. 24,25"] },
      { number: 8, text: "Und sie gingen schnell von der Gruft weg mit Furcht und großer Freude* und liefen, es seinen Jüngern zu verkünden.", footnotes: ["℘ Joh 16,22"] },
      { number: 9, text: "Und siehe, Jesus kam* ihnen entgegen und sprach: Seid gegrüßt! Sie aber traten zu <ihm>, umfassten seine Füße und warfen sich <vor ihm> nieder. *", footnotes: ["Mehrere Handschr. haben: Als sie aber hingingen, um es seinen Jüngern zu verkünden, siehe, da kam Jesus", "℘ ⇨Esyn: Synopse Nr. 353"] },
      { number: 10, text: "Da spricht Jesus zu ihnen: Fürchtet euch nicht! Geht hin, verkündet meinen Brüdern*, dass sie hingehen nach Galiläa! Und dort werden sie mich sehen*.", footnotes: ["℘ Kap. 25,40; Ps 22,23", "℘ Apg 1,3"] },
      { number: 11, text: "Während sie aber hingingen, siehe, da kamen einige von der Wache in die Stadt und verkündeten den Hohenpriestern alles, was geschehen war. *", heading: "Bestechung der Grabwächter", footnotes: ["℘ ⇨Esyn: Synopse Nr. 354"] },
      { number: 12, text: "Und sie versammelten sich mit den Ältesten und hielten Rat; und sie gaben den Soldaten reichlich Geld" },
      { number: 13, text: "und sagten: Sprecht: Seine Jünger kamen bei Nacht und stahlen ihn, während wir schliefen*.", footnotes: ["℘ Kap. 27,64"] },
      { number: 14, text: "Und wenn dies dem Statthalter zu Ohren kommen sollte, so werden wir ihn beschwichtigen und machen, dass ihr ohne Sorge seid." },
      { number: 15, text: "Sie aber nahmen das Geld und taten, wie sie unterrichtet worden waren. Und diese Rede verbreitete sich bei den Juden bis auf den heutigen Tag." },
      { number: 16, text: "Die elf Jünger aber gingen nach Galiläa, an den Berg, wohin Jesus sie bestellt hatte*.", heading: "Erscheinung des Auferstandenen vor den Jüngern — Missionsbefehl", footnotes: ["℘ V. 7 ⇨Esyn: Synopse Nr. 364"] },
      { number: 17, text: "Und als sie ihn sahen, warfen sie sich <vor ihm> nieder*; einige aber zweifelten.", footnotes: ["℘ Lk 24,52; 1Kor 15,5"] },
      { number: 18, text: "Und Jesus trat zu <ihnen> und redete mit ihnen und sprach: Mir ist alle Macht* gegeben im Himmel und auf Erden*.", footnotes: ["o. Vollmacht", "℘ Kap. 11,27; Dan 7,14; Lk 10,22; Eph 1,21.22; Phil 2,9; 1Petr 3,22"] },
      { number: 19, text: "Geht nun hin und macht alle Nationen zu Jüngern*, und tauft sie* auf den Namen des Vaters und des Sohnes und des Heiligen Geistes,", footnotes: ["℘ Mk 16,15.16", "w. sie taufend"] },
      { number: 20, text: "und lehrt sie* alles zu bewahren*, was ich euch geboten habe*! Und siehe, ich bin bei euch alle Tage bis zur Vollendung des Zeitalters*.", footnotes: ["w. sie lehrend", "o. zu halten", "℘ 1Thes 4,1.2", "griech. Äon"] },
    ]},
  ]
};
